    async def ensure_file_mutation_journal(
        self, journal: LibraryFileMutationJournal
    ) -> LibraryFileMutationJournal:
        """Create a journal intent or return the exact durable retry."""

        def operation(connection: sqlite3.Connection) -> LibraryFileMutationJournal:
            connection.execute(
                "INSERT OR IGNORE INTO library_file_mutation_journal "
                "(id, job_id, plan_item_ordinal, subject_kind, subject_key, "
                "local_track_id, source_root_id, source_relative_path, temporary_root_id, "
                "temporary_relative_path, backup_root_id, backup_relative_path, "
                "destination_root_id, destination_relative_path, source_fingerprint, "
                "staged_fingerprint, baseline_id, operation_snapshot_id, state, attempts, "
                "failure_code, recovery_evidence_json, created_at, updated_at, row_revision) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    journal.id,
                    journal.job_id,
                    journal.plan_item_ordinal,
                    journal.subject_kind,
                    journal.subject_key,
                    journal.local_track_id,
                    journal.source_root_id,
                    journal.source_relative_path,
                    journal.temporary_root_id,
                    journal.temporary_relative_path,
                    journal.backup_root_id,
                    journal.backup_relative_path,
                    journal.destination_root_id,
                    journal.destination_relative_path,
                    journal.source_fingerprint,
                    journal.staged_fingerprint,
                    journal.baseline_id,
                    journal.operation_snapshot_id,
                    journal.state,
                    journal.attempts,
                    journal.failure_code,
                    journal.recovery_evidence_json,
                    journal.created_at,
                    journal.updated_at,
                    journal.row_revision,
                ),
            )
            row = connection.execute(
                "SELECT * FROM library_file_mutation_journal WHERE job_id=? "
                "AND plan_item_ordinal=? AND subject_kind=? AND subject_key=?",
                (
                    journal.job_id,
                    journal.plan_item_ordinal,
                    journal.subject_kind,
                    journal.subject_key,
                ),
            ).fetchone()
            if row is None:
                raise ConflictError("The mutation journal ID is already in use.")
            saved = msgspec.convert(
                dict(row), type=LibraryFileMutationJournal, strict=False
            )
            immutable_fields = (
                "id",
                "job_id",
                "plan_item_ordinal",
                "subject_kind",
                "subject_key",
                "local_track_id",
                "source_root_id",
                "source_relative_path",
                "temporary_root_id",
                "temporary_relative_path",
                "backup_root_id",
                "backup_relative_path",
                "destination_root_id",
                "destination_relative_path",
                "source_fingerprint",
                "baseline_id",
                "operation_snapshot_id",
            )
            if any(
                getattr(saved, field) != getattr(journal, field)
                for field in immutable_fields
            ):
                raise ConflictError(
                    "The mutation journal retry does not match its durable intent."
                )
            return saved

        return await self._write(operation)

    async def list_file_mutation_journals_for_bundle(
        self, job_id: str, bundle_ordinal: int
    ) -> list[LibraryFileMutationJournal]:
        def operation(
            connection: sqlite3.Connection,
        ) -> list[LibraryFileMutationJournal]:
            rows = connection.execute(
                "SELECT journal.* FROM library_file_mutation_journal journal "
                "JOIN library_management_plan_items item ON item.job_id=journal.job_id "
                "AND item.ordinal=journal.plan_item_ordinal WHERE journal.job_id=? "
                "AND item.bundle_ordinal=? ORDER BY "
                "CASE WHEN json_extract(journal.recovery_evidence_json, '$.mutation') "
                "= 'recycle' THEN 0 ELSE 1 END, journal.plan_item_ordinal, "
                "journal.subject_kind, journal.subject_key",
                (job_id, bundle_ordinal),
            ).fetchall()
            return [
                msgspec.convert(
                    dict(row), type=LibraryFileMutationJournal, strict=False
                )
                for row in rows
            ]

        return await self._read(operation)

    async def transition_file_mutation_journal(
        self,
        journal_id: str,
        *,
        expected_state: MutationJournalState,
        new_state: MutationJournalState,
        expected_row_revision: int,
        updated_at: float,
        failure_code: str | None = None,
        increment_attempts: bool = False,
        staged_fingerprint: str | None = None,
        recovery_evidence_json: str | None = None,
    ) -> LibraryFileMutationJournal:
        if new_state not in _MUTATION_JOURNAL_TRANSITIONS[expected_state]:
            raise ValidationError(
                f"Invalid mutation journal transition: {expected_state} -> {new_state}."
            )

        def operation(connection: sqlite3.Connection) -> LibraryFileMutationJournal:
            self._refuse_max_revision(
                connection,
                table="library_file_mutation_journal",
                predicate="id = ?",
                parameters=(journal_id,),
            )
            updated = connection.execute(
                "UPDATE library_file_mutation_journal SET state = ?, updated_at = ?, "
                "failure_code = ?, staged_fingerprint = COALESCE(?, staged_fingerprint), "
                "recovery_evidence_json = COALESCE(?, recovery_evidence_json), "
                "attempts = attempts + ?, row_revision = row_revision + 1 "
                "WHERE id = ? AND state = ? AND row_revision = ? RETURNING *",
                (
                    new_state,
                    updated_at,
                    failure_code,
                    staged_fingerprint,
                    recovery_evidence_json,
                    1 if increment_attempts else 0,
                    journal_id,
                    expected_state,
                    expected_row_revision,
                ),
            ).fetchone()
            if updated is None:
                current = connection.execute(
                    "SELECT 1 FROM library_file_mutation_journal WHERE id = ?",
                    (journal_id,),
                ).fetchone()
                if current is None:
                    raise ResourceNotFoundError("Mutation journal entry not found.")
                raise StaleRevisionError(
                    "The mutation journal changed before its transition."
                )
            return msgspec.convert(
                dict(updated), type=LibraryFileMutationJournal, strict=False
            )

        return await self._write(operation)

    async def list_recoverable_file_mutation_journals(
        self, *, limit: int = MANAGEMENT_PERSISTENCE_BATCH_SIZE
    ) -> list[LibraryFileMutationJournal]:
        if limit < 1 or limit > MANAGEMENT_PERSISTENCE_BATCH_SIZE:
            raise ValidationError("Mutation recovery page size is out of range.")

        def operation(
            connection: sqlite3.Connection,
        ) -> list[LibraryFileMutationJournal]:
            rows = connection.execute(
                "SELECT * FROM library_file_mutation_journal "
                "WHERE state NOT IN ('completed','rolled_back','needs_attention') "
                "ORDER BY updated_at, id LIMIT ?",
                (limit,),
            ).fetchall()
            return [
                msgspec.convert(
                    dict(row), type=LibraryFileMutationJournal, strict=False
                )
                for row in rows
            ]

        return await self._read(operation)

    async def list_recoverable_management_bundles(
        self, *, limit: int = 100
    ) -> list[dict[str, Any]]:
        """Return bounded album bundles with journal work that can still progress."""

        if limit < 1 or limit > MANAGEMENT_PERSISTENCE_BATCH_SIZE:
            raise ValidationError("Management recovery page size is out of range.")

        def operation(connection: sqlite3.Connection) -> list[dict[str, Any]]:
            rows = connection.execute(
                "SELECT journal.job_id, item.bundle_ordinal, "
                "MIN(journal.updated_at) AS oldest_updated_at, COUNT(*) AS journal_count "
                "FROM library_file_mutation_journal journal "
                "JOIN library_management_plan_items item ON item.job_id=journal.job_id "
                "AND item.ordinal=journal.plan_item_ordinal "
                "WHERE journal.state NOT IN "
                "('completed','rolled_back','needs_attention') "
                "GROUP BY journal.job_id,item.bundle_ordinal "
                "ORDER BY oldest_updated_at,journal.job_id,item.bundle_ordinal LIMIT ?",
                (limit,),
            ).fetchall()
            return [dict(row) for row in rows]

        return await self._read(operation)

    async def library_management_recovery_diagnostics(self) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            rows = connection.execute(
                "SELECT state,COUNT(*) AS count FROM library_file_mutation_journal "
                "WHERE state NOT IN ('completed','rolled_back') "
                "GROUP BY state ORDER BY state"
            ).fetchall()
            bundle = connection.execute(
                "SELECT COUNT(*) AS count,MIN(oldest_updated_at) AS oldest_updated_at "
                "FROM (SELECT journal.job_id,item.bundle_ordinal,"
                "MIN(journal.updated_at) AS oldest_updated_at "
                "FROM library_file_mutation_journal journal "
                "JOIN library_management_plan_items item "
                "ON item.job_id=journal.job_id "
                "AND item.ordinal=journal.plan_item_ordinal "
                "WHERE journal.state NOT IN "
                "('completed','rolled_back','needs_attention') "
                "GROUP BY journal.job_id,item.bundle_ordinal)"
            ).fetchone()
            import_bundles = connection.execute(
                "SELECT state,COUNT(*) AS count,MIN(updated_at) AS oldest_updated_at "
                "FROM library_management_import_bundles "
                "WHERE state NOT IN ('completed','rolled_back') GROUP BY state "
                "ORDER BY state"
            ).fetchall()
            import_journals = connection.execute(
                "SELECT state,COUNT(*) AS count FROM library_management_import_journal "
                "WHERE state NOT IN ('completed','rolled_back') GROUP BY state"
            ).fetchall()
            import_recoverable_count = sum(
                int(row["count"])
                for row in import_bundles
                if str(row["state"]) != "needs_attention"
            )
            import_oldest = min(
                (
                    float(row["oldest_updated_at"])
                    for row in import_bundles
                    if str(row["state"]) != "needs_attention"
                    and row["oldest_updated_at"] is not None
                ),
                default=None,
            )
            manual_oldest = (
                float(bundle["oldest_updated_at"])
                if bundle["oldest_updated_at"] is not None
                else None
            )
            oldest = min(
                (
                    value
                    for value in (manual_oldest, import_oldest)
                    if value is not None
                ),
                default=None,
            )
            states = {str(row["state"]): int(row["count"]) for row in rows}
            states.update(
                {f"import_{row['state']}": int(row["count"]) for row in import_bundles}
            )
            return {
                "recoverable_bundle_count": int(bundle["count"])
                + import_recoverable_count,
                "nonterminal_journal_count": sum(
                    int(row["count"])
                    for row in rows
                    if str(row["state"]) != "needs_attention"
                )
                + sum(
                    int(row["count"])
                    for row in import_journals
                    if str(row["state"]) != "needs_attention"
                ),
                "needs_attention_count": sum(
                    int(row["count"])
                    for row in rows
                    if str(row["state"]) == "needs_attention"
                )
                + sum(
                    int(row["count"])
                    for row in import_bundles
                    if str(row["state"]) == "needs_attention"
                ),
                "cleanup_pending_count": sum(
                    int(row["count"])
                    for row in rows
                    if str(row["state"]) == "cleanup_pending"
                )
                + sum(
                    int(row["count"])
                    for row in import_bundles
                    if str(row["state"]) == "cleanup_pending"
                ),
                "oldest_updated_at": oldest,
                "state_counts": states,
            }

        return await self._read(operation)

    async def claim_management_bundle_for_recovery(
        self,
        job_id: str,
        bundle_ordinal: int,
        worker_id: str,
        *,
        now: float,
        lease_seconds: float,
        force_expired_process_lease: bool = False,
    ) -> bool:
        """Claim one applying bundle without racing a live operation worker."""

        def operation(connection: sqlite3.Connection) -> bool:
            job = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id=? "
                "AND kind='library_management'",
                (job_id,),
            ).fetchone()
            snapshot = connection.execute(
                "SELECT phase FROM library_management_job_snapshots WHERE job_id=?",
                (job_id,),
            ).fetchone()
            work = connection.execute(
                "SELECT * FROM library_operation_work WHERE job_id=? AND ordinal=?",
                (job_id, bundle_ordinal),
            ).fetchone()
            if (
                job is None
                or snapshot is None
                or work is None
                or str(snapshot["phase"]) != "applying"
                or str(work["state"]) not in {"pending", "running"}
            ):
                return False
            state = str(job["state"])
            if state == "running":
                active_other_lease = (
                    job["lease_owner"] != worker_id
                    and job["lease_expires_at"] is not None
                    and float(job["lease_expires_at"]) >= now
                )
                if active_other_lease and not force_expired_process_lease:
                    return False
            elif state != "queued":
                return False
            self._refuse_max_revision(
                connection,
                table="library_operation_jobs",
                predicate="id = ?",
                parameters=(job_id,),
                include_event_revision=True,
            )
            self._refuse_max_revision(
                connection,
                table="library_operation_work",
                predicate="job_id = ? AND ordinal = ?",
                parameters=(job_id, bundle_ordinal),
            )
            connection.execute(
                "UPDATE library_operation_jobs SET state='running',"
                "started_at=COALESCE(started_at,?),lease_owner=?,lease_expires_at=?,"
                "heartbeat_at=?,updated_at=?,row_revision=row_revision+1,"
                "event_revision=event_revision+1 WHERE id=?",
                (now, worker_id, now + lease_seconds, now, now, job_id),
            )
            connection.execute(
                "UPDATE library_operation_work SET state='running',updated_at=?,"
                "row_revision=row_revision+1 WHERE job_id=? AND ordinal=?",
                (now, job_id, bundle_ordinal),
            )
            self._bump_stream(connection, "operation")
            return True

        return await self._write(operation)

    async def release_management_recovery_lease(
        self, job_id: str, worker_id: str, *, now: float
    ) -> bool:
        def operation(connection: sqlite3.Connection) -> bool:
            work = connection.execute(
                "SELECT COUNT(*) AS total,"
                "SUM(state IN ('pending','running')) AS active,"
                "SUM(state='failed') AS failed FROM library_operation_work "
                "WHERE job_id=?",
                (job_id,),
            ).fetchone()
            terminal = int(work["total"]) > 0 and int(work["active"] or 0) == 0
            state = "failed" if int(work["failed"] or 0) else "succeeded"
            terminal_code = "RECOVERY_FAILED" if state == "failed" else "COMPLETED"
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state=?,terminal_code=?,"
                "terminal_at=?,lease_owner=NULL,lease_expires_at=NULL,heartbeat_at=NULL,updated_at=?,"
                "row_revision=row_revision+1,event_revision=event_revision+1 "
                "WHERE id=? AND kind='library_management' AND state='running' "
                "AND lease_owner=? RETURNING id",
                (
                    state if terminal else "queued",
                    terminal_code if terminal else None,
                    now if terminal else None,
                    now,
                    job_id,
                    worker_id,
                ),
            ).fetchone()
            if updated is not None:
                self._bump_stream(connection, "operation")
            return updated is not None

        return await self._write(operation)

    async def settle_management_recovery_job(self, job_id: str, *, now: float) -> bool:
        """Finish a recovered operation whose durable work is already terminal."""

        def operation(connection: sqlite3.Connection) -> bool:
            work = connection.execute(
                "SELECT COUNT(*) AS total,"
                "SUM(state IN ('pending','running')) AS active,"
                "SUM(state='failed') AS failed FROM library_operation_work "
                "WHERE job_id=?",
                (job_id,),
            ).fetchone()
            if int(work["total"]) == 0 or int(work["active"] or 0) != 0:
                return False
            state = "failed" if int(work["failed"] or 0) else "succeeded"
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state=?,terminal_code=?,terminal_at=?,"
                "lease_owner=NULL,lease_expires_at=NULL,heartbeat_at=NULL,updated_at=?,"
                "row_revision=row_revision+1,event_revision=event_revision+1 "
                "WHERE id=? AND kind='library_management' "
                "AND state IN ('queued','running') RETURNING id",
                (
                    state,
                    "RECOVERY_FAILED" if state == "failed" else "COMPLETED",
                    now,
                    now,
                    job_id,
                ),
            ).fetchone()
            if updated is not None:
                self._bump_stream(connection, "operation")
            return updated is not None

        return await self._write(operation)

    async def fail_management_bundle_recovery(
        self,
        job_id: str,
        bundle_ordinal: int,
        *,
        failure_code: str,
        now: float,
    ) -> None:
        """Make one bundle's recovery failure visible without failing its siblings.

        E30 scopes a recovery failure to every still-active row in the bundle;
        E31 keeps unrelated bundles continuing. The operation job therefore
        stays live while sibling work rows remain resumable and settles
        terminal only when this was its last active bundle.
        """

        def operation(connection: sqlite3.Connection) -> None:
            work = connection.execute(
                "SELECT state FROM library_operation_work WHERE job_id=? AND ordinal=?",
                (job_id, bundle_ordinal),
            ).fetchone()
            if work is None:
                return
            was_active = str(work["state"]) in {"pending", "running"}
            if was_active:
                connection.execute(
                    "UPDATE library_operation_work SET state='failed',failure_code=?,"
                    "updated_at=?,row_revision=row_revision+1 WHERE job_id=? AND ordinal=?",
                    (failure_code, now, job_id, bundle_ordinal),
                )
            siblings = connection.execute(
                "SELECT COUNT(*) AS active FROM library_operation_work "
                "WHERE job_id=? AND ordinal<>? AND state IN ('pending','running')",
                (job_id, bundle_ordinal),
            ).fetchone()
            if int(siblings["active"] or 0):
                # Sibling bundles stay resumable; only this work row failed.
                self._bump_stream(connection, "operation")
                return
            connection.execute(
                "UPDATE library_operation_jobs SET state='failed',terminal_code=?,"
                "terminal_at=?,lease_owner=NULL,lease_expires_at=NULL,heartbeat_at=NULL,"
                "completed_count=completed_count+?,failed_count=failed_count+?,"
                "updated_at=?,row_revision=row_revision+1,event_revision=event_revision+1 "
                "WHERE id=? AND kind='library_management'",
                (
                    failure_code,
                    now,
                    int(was_active),
                    int(was_active),
                    now,
                    job_id,
                ),
            )
            self._bump_stream(connection, "operation")

        await self._write(operation)

    async def mark_management_recovery_destination_missing(
        self,
        local_track_id: str,
        root_id: str,
        relative_path: str,
        *,
        now: float,
    ) -> bool:
        """Keep catalog availability honest when committed output cannot be restored."""

        def operation(connection: sqlite3.Connection) -> bool:
            updated = connection.execute(
                "UPDATE local_tracks SET availability='missing',missing_since=?,"
                "row_revision=row_revision+1 WHERE id=? AND root_id=? AND relative_path=? "
                "AND availability='indexed' RETURNING local_album_id",
                (now, local_track_id, root_id, relative_path),
            ).fetchone()
            if updated is None:
                return False
            self._bump_catalog(connection)
            return True

        return await self._write(operation)

    @classmethod
    def _management_artist_credits_tx(
        cls,
        connection: sqlite3.Connection,
        credits: list[AudioArtistCredit],
        *,
        fallback_name: str,
        fallback_sort_name: str | None,
        fallback_mbid: str | None,
        now: float,
    ) -> list[LocalArtistCredit]:
        source = credits or [
            AudioArtistCredit(
                name=fallback_name,
                credited_name=fallback_name,
                sort_name=fallback_sort_name,
                musicbrainz_artist_id=fallback_mbid,
            )
        ]
        normalized: list[LocalArtistCredit] = []
        for position, credit in enumerate(source):
            display_name = credit.name.strip() or fallback_name
            sort_name = credit.sort_name
            provider_id = credit.musicbrainz_artist_id
            local_artist_id: str | None = None
            if provider_id:
                identity = connection.execute(
                    "SELECT local_artist_id FROM local_artist_external_identities "
                    "WHERE provider='musicbrainz' AND provider_artist_id=?",
                    (provider_id,),
                ).fetchone()
                if identity is not None:
                    local_artist_id = str(identity["local_artist_id"])
            if local_artist_id is None:
                candidate_id = str(
                    uuid.uuid5(
                        _MANAGEMENT_ARTIST_NAMESPACE,
                        (
                            f"artist-mbid:{provider_id}"
                            if provider_id
                            else f"artist:{display_name}:{sort_name or ''}:group"
                        ),
                    )
                )
                if provider_id:
                    existing_candidate = connection.execute(
                        "SELECT id FROM local_artists WHERE id=? "
                        "AND retired_into_artist_id IS NULL",
                        (candidate_id,),
                    ).fetchone()
                    if existing_candidate is not None:
                        local_artist_id = candidate_id
                    else:
                        unclaimed = connection.execute(
                            "SELECT artist.id,artist.sort_name FROM local_artists artist "
                            "LEFT JOIN local_artist_external_identities identity "
                            "ON identity.local_artist_id=artist.id "
                            "AND identity.provider='musicbrainz' "
                            "WHERE artist.normalized_name=? AND artist.kind='group' "
                            "AND artist.retired_into_artist_id IS NULL "
                            "AND identity.local_artist_id IS NULL ORDER BY artist.created_at,artist.id",
                            (_normalize_exact(display_name),),
                        ).fetchall()
                        compatible = [
                            row
                            for row in unclaimed
                            if not _normalize_exact(sort_name)
                            or not _normalize_exact(row["sort_name"])
                            or _normalize_exact(row["sort_name"])
                            == _normalize_exact(sort_name)
                        ]
                        if len(compatible) == 1:
                            local_artist_id = str(compatible[0]["id"])
                        else:
                            connection.execute(
                                "INSERT INTO local_artists "
                                "(id,display_name,sort_name,folded_name,normalized_name,kind,"
                                "created_at,updated_at) VALUES (?,?,?,?,?,'group',?,?)",
                                (
                                    candidate_id,
                                    display_name,
                                    sort_name,
                                    _fold(display_name) or "",
                                    _normalize_exact(display_name),
                                    now,
                                    now,
                                ),
                            )
                            local_artist_id = candidate_id
                    connection.execute(
                        "INSERT OR IGNORE INTO local_artist_external_identities "
                        "(local_artist_id,provider,provider_artist_id,decision_source,selected_at) "
                        "VALUES (?,'musicbrainz',?,'automatic',?)",
                        (local_artist_id, provider_id, now),
                    )
                else:
                    local_artist_id, _reused = cls._resolve_or_create_local_artist(
                        connection,
                        display_name=display_name,
                        sort_name=sort_name,
                        kind="group",
                        candidate_id=candidate_id,
                        normalized=_normalize_exact(display_name),
                        folded=_fold(display_name) or "",
                        normalized_sort=_normalize_exact(sort_name),
                        now=now,
                    )
            normalized.append(
                LocalArtistCredit(
                    local_artist_id=local_artist_id,
                    position=position,
                    credited_name=credit.credited_name or display_name,
                    join_phrase=credit.join_phrase,
                )
            )
        return normalized

    @staticmethod
    def _management_override_revision_tx(
        connection: sqlite3.Connection,
        local_album_id: str,
        local_track_id: str,
    ) -> str:
        revisions: list[str] = []
        for subject_kind, subject_column, subject_id in (
            ("album", "local_album_id", local_album_id),
            ("track", "local_track_id", local_track_id),
        ):
            rows = connection.execute(
                "SELECT id,field_name,row_revision FROM "
                "library_management_overrides WHERE subject_kind=? AND "
                + subject_column
                + "=? ORDER BY field_name,id",
                (subject_kind, subject_id),
            ).fetchall()
            material = [
                (str(row["id"]), str(row["field_name"]), int(row["row_revision"]))
                for row in rows
            ]
            revisions.append(
                hashlib.sha256(
                    json.dumps(material, separators=(",", ":")).encode()
                ).hexdigest()
            )
        return hashlib.sha256(f"{revisions[0]}\x00{revisions[1]}".encode()).hexdigest()

    @staticmethod
    def _validate_tag_edit_intent_tx(
        connection: sqlite3.Connection,
        intent: LibraryManagementTagEditIntent,
        mutations: list[LibraryManagementCatalogMutation],
    ) -> None:
        if (
            not intent.fields
            or intent.local_track_id
            not in {value.local_track_id for value in mutations}
            or {value.local_album_id for value in mutations} != {intent.local_album_id}
        ):
            raise ValidationError(
                "The manual tag-edit intent does not match its bundle."
            )
        keys = [(value.subject_kind, value.field_name) for value in intent.fields]
        if len(set(keys)) != len(keys):
            raise ValidationError("The manual tag-edit intent repeats a field.")
        for field in intent.fields:
            subject_column = (
                "local_album_id" if field.subject_kind == "album" else "local_track_id"
            )
            subject_id = (
                intent.local_album_id
                if field.subject_kind == "album"
                else intent.local_track_id
            )
            existing = connection.execute(
                "SELECT id,row_revision FROM library_management_overrides "
                f"WHERE subject_kind=? AND {subject_column}=? AND field_name=?",
                (field.subject_kind, subject_id, field.field_name),
            ).fetchone()
            if intent.mode == "write_once":
                continue
            if field.override_id is None:
                if intent.mode == "reset_canonical" or existing is not None:
                    raise StaleRevisionError(
                        "A manual tag override changed after preview."
                    )
                continue
            if (
                existing is None
                or str(existing["id"]) != field.override_id
                or int(existing["row_revision"]) != field.expected_override_row_revision
            ):
                raise StaleRevisionError("A manual tag override changed after preview.")

    @classmethod
    def _apply_tag_edit_intent_tx(
        cls,
        connection: sqlite3.Connection,
        job_id: str,
        actor_user_id: str | None,
        intent: LibraryManagementTagEditIntent,
        mutations: list[LibraryManagementCatalogMutation],
        *,
        now: float,
    ) -> None:
        if intent.mode == "write_once":
            return
        for field in intent.fields:
            subject_table = (
                "local_albums" if field.subject_kind == "album" else "local_tracks"
            )
            subject_id = (
                intent.local_album_id
                if field.subject_kind == "album"
                else intent.local_track_id
            )
            subject = connection.execute(
                f"SELECT row_revision FROM {subject_table} WHERE id=?",
                (subject_id,),
            ).fetchone()
            if subject is None:
                raise ResourceNotFoundError("Management override subject not found.")
            if intent.mode == "reset_canonical":
                deleted = connection.execute(
                    "DELETE FROM library_management_overrides WHERE id=? "
                    "AND row_revision=? RETURNING id",
                    (field.override_id, field.expected_override_row_revision),
                ).fetchone()
                if deleted is None:
                    raise StaleRevisionError(
                        "A manual tag override changed after preview."
                    )
                continue

            override_id = field.override_id or str(
                uuid.uuid5(
                    _MANAGEMENT_OVERRIDE_NAMESPACE,
                    (
                        f"{job_id}\x00{field.subject_kind}\x00"
                        f"{subject_id}\x00{field.field_name}"
                    ),
                )
            )
            value = msgspec.to_builtins(field.value)
            mode = "clear" if value is None or value == "" or value == [] else "replace"
            value_json = json.dumps(
                None if mode == "clear" else value,
                ensure_ascii=False,
                separators=(",", ":"),
            )
            if field.override_id is None:
                try:
                    connection.execute(
                        "INSERT INTO library_management_overrides "
                        "(id,subject_kind,local_album_id,local_track_id,field_name,"
                        "value_json,mode,actor_user_id,reason,subject_revision,"
                        "created_at,updated_at,row_revision) "
                        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,1)",
                        (
                            override_id,
                            field.subject_kind,
                            subject_id if field.subject_kind == "album" else None,
                            subject_id if field.subject_kind == "track" else None,
                            field.field_name,
                            value_json,
                            mode,
                            actor_user_id,
                            "Manual tag editor",
                            int(subject["row_revision"]),
                            now,
                            now,
                        ),
                    )
                except sqlite3.IntegrityError as error:
                    raise StaleRevisionError(
                        "A manual tag override changed after preview."
                    ) from error
            else:
                updated = connection.execute(
                    "UPDATE library_management_overrides SET value_json=?,mode=?,"
                    "actor_user_id=?,reason='Manual tag editor',subject_revision=?,"
                    "updated_at=?,row_revision=row_revision+1 WHERE id=? "
                    "AND row_revision=? RETURNING id",
                    (
                        value_json,
                        mode,
                        actor_user_id,
                        int(subject["row_revision"]),
                        now,
                        field.override_id,
                        field.expected_override_row_revision,
                    ),
                ).fetchone()
                if updated is None:
                    raise StaleRevisionError(
                        "A manual tag override changed after preview."
                    )

        for mutation in mutations:
            revision = cls._management_override_revision_tx(
                connection, mutation.local_album_id, mutation.local_track_id
            )
            connection.execute(
                "UPDATE library_track_management_state SET "
                "applied_override_revision=?,row_revision=row_revision+1 "
                "WHERE local_track_id=?",
                (revision, mutation.local_track_id),
            )

    async def commit_library_management_bundle(
        self,
        job_id: str,
        bundle_ordinal: int,
        worker_id: str,
        mutations: list[LibraryManagementCatalogMutation],
        *,
        now: float,
    ) -> LibraryManagementBundleCommitResult:
        """Commit one fully published bundle and its durable operation state."""

        if not mutations or len(mutations) > MANAGEMENT_PERSISTENCE_BATCH_SIZE:
            raise ValidationError("Management bundle size is out of range.")
        if len({value.local_track_id for value in mutations}) != len(mutations):
            raise ValidationError("A management bundle repeats a local track.")
        if len({value.journal_id for value in mutations}) != len(mutations):
            raise ValidationError("A management bundle repeats a mutation journal.")

        def operation(
            connection: sqlite3.Connection,
        ) -> LibraryManagementBundleCommitResult:
            job = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id=? AND kind='library_management'",
                (job_id,),
            ).fetchone()
            snapshot = connection.execute(
                "SELECT * FROM library_management_job_snapshots WHERE job_id=?",
                (job_id,),
            ).fetchone()
            work = connection.execute(
                "SELECT * FROM library_operation_work WHERE job_id=? AND ordinal=?",
                (job_id, bundle_ordinal),
            ).fetchone()
            if job is None or snapshot is None or work is None:
                raise ResourceNotFoundError("Library management bundle not found.")

            journal_rows = connection.execute(
                "SELECT journal.* FROM library_file_mutation_journal journal "
                "JOIN library_management_plan_items item ON item.job_id=journal.job_id "
                "AND item.ordinal=journal.plan_item_ordinal WHERE journal.job_id=? "
                "AND item.bundle_ordinal=? ORDER BY journal.id",
                (job_id, bundle_ordinal),
            ).fetchall()
            journal_by_id = {str(row["id"]): row for row in journal_rows}
            mutation_ids = {value.journal_id for value in mutations}
            audio_journal_ids = {
                str(row["id"])
                for row in journal_rows
                if str(row["subject_kind"]) == "audio"
            }
            if mutation_ids != audio_journal_ids:
                raise ValidationError(
                    "Every audio journal needs exactly one catalog mutation."
                )
            for mutation in mutations:
                journal = journal_by_id[mutation.journal_id]
                if (
                    int(journal["plan_item_ordinal"]) != mutation.plan_item_ordinal
                    or str(journal["local_track_id"]) != mutation.local_track_id
                ):
                    raise ValidationError(
                        "A catalog mutation does not match its journal intent."
                    )
            committed_states = {"catalog_committed", "cleanup_pending", "completed"}
            if journal_rows and all(
                str(row["state"]) in committed_states for row in journal_rows
            ):
                if str(work["state"]) != "succeeded":
                    raise ConflictError(
                        "Committed management journals have incomplete operation work."
                    )
                return LibraryManagementBundleCommitResult(
                    catalog_revision=int(snapshot["catalog_revision"]),
                    snapshot_revision=int(snapshot["row_revision"]),
                    committed_journal_ids=tuple(sorted(journal_by_id)),
                    committed_journal_revisions={
                        str(row["id"]): int(row["row_revision"]) for row in journal_rows
                    },
                )
            if not journal_rows or any(
                str(row["state"]) != "published" for row in journal_rows
            ):
                raise StaleRevisionError(
                    "Every bundle journal must be published before catalog commit."
                )
            if (
                str(job["state"]) != "running"
                or str(job["lease_owner"]) != worker_id
                or str(snapshot["phase"]) not in {"applying", "undoing", "restoring"}
                or str(work["state"]) != "running"
            ):
                raise StaleRevisionError(
                    "The management operation lease changed before catalog commit."
                )
            catalog_revision = int(
                connection.execute(
                    "SELECT value FROM library_catalog_revision WHERE singleton=1"
                ).fetchone()[0]
            )
            if catalog_revision != int(snapshot["catalog_revision"]):
                raise StaleRevisionError(
                    "The library catalog changed before management commit."
                )

            intent_json = str(snapshot["intent_json"])
            tag_edit_intent = None
            if intent_json != "{}":
                try:
                    tag_edit_intent = msgspec.json.decode(
                        intent_json.encode(), type=LibraryManagementTagEditIntent
                    )
                except msgspec.DecodeError as error:
                    raise ValidationError(
                        "The durable manual tag-edit intent is invalid."
                    ) from error
                self._validate_tag_edit_intent_tx(
                    connection, tag_edit_intent, mutations
                )

            actor_user_id = job["requested_by_user_id"]
            conversion_restore_track_ids: set[str] = set()
            if any(value.allow_unmapped_conversion_restore for value in mutations):
                if (
                    str(snapshot["mode"]) != "undo"
                    or snapshot["linked_operation_job_id"] is None
                ):
                    raise ValidationError(
                        "Unmapped conversion restoration is only valid during Undo."
                    )
                source_snapshot = connection.execute(
                    "SELECT intent_json FROM library_management_job_snapshots "
                    "WHERE job_id=?",
                    (snapshot["linked_operation_job_id"],),
                ).fetchone()
                try:
                    source_intent = (
                        json.loads(str(source_snapshot["intent_json"]))
                        if source_snapshot is not None
                        else {}
                    )
                except json.JSONDecodeError as error:
                    raise ValidationError(
                        "The source conversion history is invalid."
                    ) from error
                conversion_before = source_intent.get("edition_conversion_before")
                if not isinstance(conversion_before, dict):
                    raise ValidationError(
                        "The source conversion history is incomplete."
                    )
                conversion_restore_track_ids = {
                    str(value)
                    for value in conversion_before.get("original_track_ids", [])
                }
            updated_albums: set[str] = set()
            for mutation in mutations:
                track = connection.execute(
                    "SELECT * FROM local_tracks WHERE id=?",
                    (mutation.local_track_id,),
                ).fetchone()
                if track is None:
                    raise ResourceNotFoundError("Managed track not found.")
                if (
                    int(track["row_revision"]) != mutation.expected_track_revision
                    or str(track["local_album_id"]) != mutation.local_album_id
                    or str(track["root_id"]) != mutation.expected_root_id
                    or str(track["relative_path"]) != mutation.expected_relative_path
                    or str(track["stat_revision"]) != mutation.expected_stat_revision
                    or str(track["tag_revision"]) != mutation.expected_tag_revision
                ):
                    raise StaleRevisionError(
                        "A managed track changed after its preview."
                    )
                album_identity = connection.execute(
                    "SELECT release_group_mbid,release_mbid,row_revision FROM local_album_external_identities "
                    "WHERE local_album_id=? AND provider='musicbrainz'",
                    (mutation.local_album_id,),
                ).fetchone()
                track_identity = connection.execute(
                    "SELECT release_mbid,recording_mbid,release_track_mbid,row_revision "
                    "FROM local_track_external_identities "
                    "WHERE local_track_id=? AND provider='musicbrainz'",
                    (mutation.local_track_id,),
                ).fetchone()
                custom_active = (
                    connection.execute(
                        "SELECT active.manifest_id FROM library_custom_edition_active active "
                        "WHERE active.local_album_id=?",
                        (mutation.local_album_id,),
                    ).fetchone()
                    if mutation.expected_identity_kind == "custom_edition"
                    else None
                )
                album_identity_changed = (
                    album_identity is None
                    or int(album_identity["row_revision"])
                    != mutation.expected_album_identity_revision
                    or str(album_identity["release_group_mbid"] or "")
                    != mutation.expected_release_group_mbid
                )
                if mutation.allow_unmapped_conversion_restore:
                    track_identity_changed = (
                        mutation.expected_identity_revision is None
                        and track_identity is not None
                    ) or (
                        mutation.expected_identity_revision is not None
                        and (
                            track_identity is None
                            or int(track_identity["row_revision"])
                            != mutation.expected_identity_revision
                        )
                    )
                    identity_changed = (
                        mutation.local_track_id not in conversion_restore_track_ids
                        or mutation.expected_identity_kind != "exact_release"
                        or album_identity_changed
                        or str(album_identity["release_mbid"] or "")
                        != str(mutation.expected_release_mbid or "")
                        or track_identity_changed
                    )
                elif mutation.expected_identity_kind == "custom_edition":
                    track_identity_changed = (
                        mutation.expected_identity_revision is None
                        and track_identity is not None
                    ) or (
                        mutation.expected_identity_revision is not None
                        and (
                            track_identity is None
                            or int(track_identity["row_revision"])
                            != mutation.expected_identity_revision
                            or track_identity["release_mbid"] is not None
                            or track_identity["release_track_mbid"] is not None
                            or str(track_identity["recording_mbid"] or "")
                            != str(mutation.expected_recording_mbid or "")
                        )
                    )
                    identity_changed = (
                        album_identity_changed
                        or album_identity["release_mbid"] is not None
                        or custom_active is None
                        or str(custom_active["manifest_id"])
                        != mutation.expected_custom_manifest_id
                        or track_identity_changed
                    )
                else:
                    identity_changed = (
                        album_identity_changed
                        or str(album_identity["release_mbid"] or "")
                        != str(mutation.expected_release_mbid or "")
                        or track_identity is None
                        or mutation.expected_identity_revision is None
                        or int(track_identity["row_revision"])
                        != mutation.expected_identity_revision
                        or str(track_identity["release_mbid"] or "")
                        != str(mutation.expected_release_mbid or "")
                        or str(track_identity["recording_mbid"] or "")
                        != str(mutation.expected_recording_mbid or "")
                        or str(track_identity["release_track_mbid"] or "")
                        != str(mutation.expected_release_track_mbid or "")
                    )
                if identity_changed:
                    raise StaleRevisionError(
                        "An accepted MusicBrainz mapping changed after preview."
                    )
                override_revision = self._management_override_revision_tx(
                    connection, mutation.local_album_id, mutation.local_track_id
                )
                if override_revision != mutation.expected_override_revision:
                    raise StaleRevisionError(
                        "Management overrides changed after preview."
                    )
                album = connection.execute(
                    "SELECT * FROM local_albums WHERE id=?",
                    (mutation.local_album_id,),
                ).fetchone()
                if album is None or (
                    mutation.local_album_id not in updated_albums
                    and int(album["row_revision"]) != mutation.expected_album_revision
                ):
                    raise StaleRevisionError(
                        "A managed album changed after its preview."
                    )
                if mutation.recycle_only:
                    before = {
                        "root_id": track["root_id"],
                        "relative_path": track["relative_path"],
                        "row_revision": int(track["row_revision"]),
                    }
                    connection.execute(
                        "UPDATE local_tracks SET root_id=?,file_path=?,relative_path=?,"
                        "path_hash=?,file_size_bytes=?,file_mtime_ns=?,stat_revision=?,"
                        "stat_revision_kind='exact',tag_revision=?,availability='missing',"
                        "missing_since=?,excluded_at=NULL,row_revision=row_revision+1 "
                        "WHERE id=?",
                        (
                            mutation.destination_root_id,
                            mutation.destination_file_path,
                            mutation.destination_relative_path,
                            mutation.destination_path_hash,
                            mutation.file_size_bytes,
                            mutation.file_mtime_ns,
                            mutation.stat_revision,
                            mutation.tag_revision,
                            now,
                            mutation.local_track_id,
                        ),
                    )
                    connection.execute(
                        "INSERT INTO library_track_management_state "
                        "(local_track_id,baseline_id,applied_profile_id,"
                        "applied_profile_revision,applied_projection_hash,"
                        "applied_naming_script_revision,applied_override_revision,"
                        "last_operation_job_id,managed_root_id,managed_path_revision,"
                        "last_managed_at,last_outcome,last_reason_code,row_revision) "
                        "VALUES (?,?,NULL,NULL,NULL,NULL,NULL,?,?,?,?,?,?,1) "
                        "ON CONFLICT(local_track_id) DO UPDATE SET "
                        "baseline_id=excluded.baseline_id,applied_profile_id=NULL,"
                        "applied_profile_revision=NULL,applied_projection_hash=NULL,"
                        "applied_naming_script_revision=NULL,applied_override_revision=NULL,"
                        "last_operation_job_id=excluded.last_operation_job_id,"
                        "managed_root_id=excluded.managed_root_id,"
                        "managed_path_revision=excluded.managed_path_revision,"
                        "last_managed_at=excluded.last_managed_at,"
                        "last_outcome=excluded.last_outcome,"
                        "last_reason_code=excluded.last_reason_code,"
                        "row_revision=library_track_management_state.row_revision+1",
                        (
                            mutation.local_track_id,
                            mutation.baseline_id,
                            job_id,
                            mutation.destination_root_id,
                            mutation.destination_path_hash,
                            now,
                            "recycled",
                            None,
                        ),
                    )
                    connection.execute(
                        "INSERT INTO library_catalog_actions "
                        "(id,idempotency_key,actor_user_id,action_kind,local_album_id,"
                        "local_track_id,operation_job_id,before_json,after_json,reason_code,"
                        "created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                        (
                            str(uuid.uuid4()),
                            f"management:{job_id}:{mutation.journal_id}",
                            actor_user_id,
                            "library_management",
                            mutation.local_album_id,
                            mutation.local_track_id,
                            job_id,
                            json.dumps(before, separators=(",", ":"), sort_keys=True),
                            json.dumps(
                                {
                                    "root_id": mutation.destination_root_id,
                                    "relative_path": mutation.destination_relative_path,
                                    "file_fingerprint": mutation.file_fingerprint,
                                    "availability": "missing",
                                },
                                separators=(",", ":"),
                                sort_keys=True,
                            ),
                            "LIBRARY_MANAGEMENT_DUPLICATE_RECYCLED",
                            now,
                        ),
                    )
                    continue
                tag = mutation.tag
                catalog_tag = mutation.catalog_tag
                info = mutation.info
                track_credits = self._management_artist_credits_tx(
                    connection,
                    catalog_tag.artists,
                    fallback_name=catalog_tag.artist,
                    fallback_sort_name=catalog_tag.artist_sort,
                    fallback_mbid=catalog_tag.musicbrainz_artist_id,
                    now=now,
                )
                album_credits = None
                if mutation.local_album_id not in updated_albums:
                    album_credits = self._management_artist_credits_tx(
                        connection,
                        catalog_tag.album_artists,
                        fallback_name=(catalog_tag.album_artist or catalog_tag.artist),
                        fallback_sort_name=catalog_tag.album_artist_sort,
                        fallback_mbid=catalog_tag.musicbrainz_album_artist_id,
                        now=now,
                    )
                before = {
                    "root_id": track["root_id"],
                    "relative_path": track["relative_path"],
                    "title": track["title"],
                    "artist": track["artist_name"],
                    "album": track["album_title"],
                    "row_revision": int(track["row_revision"]),
                }
                connection.execute(
                    "UPDATE local_tracks SET root_id=?, file_path=?, relative_path=?, "
                    "path_hash=?, file_size_bytes=?, file_mtime_ns=?, stat_revision=?, "
                    "stat_revision_kind='exact', tag_revision=?, tags_read_at=?, "
                    "metadata_incomplete=0, title=?, title_folded=?, artist_name=?, "
                    "artist_name_folded=?, album_title=?, album_title_folded=?, "
                    "album_artist_name=?, album_artist_name_folded=?, tag_album_title=?, "
                    "tag_album_artist_name=?, disc_number=?, track_number=?, year=?, "
                    "genre=?, genre_folded=?, title_sort=?, artist_sort=?, album_sort=?, "
                    "album_artist_sort=?, disc_subtitle=?, is_compilation=?, "
                    "embedded_release_group_mbid=?, embedded_release_mbid=?, "
                    "embedded_recording_mbid=?, embedded_release_track_mbid=?, "
                    "embedded_artist_mbid=?, "
                    "embedded_album_artist_mbid=?, duration_seconds=?, file_format=?, "
                    "bit_rate=?, sample_rate=?, bit_depth=?, channels=?, "
                    "replaygain_track_gain=?, replaygain_album_gain=?, "
                    "replaygain_track_peak=?, replaygain_album_peak=?, availability='indexed', "
                    "missing_since=NULL, excluded_at=NULL, row_revision=row_revision+1 "
                    "WHERE id=?",
                    (
                        mutation.destination_root_id,
                        mutation.destination_file_path,
                        mutation.destination_relative_path,
                        mutation.destination_path_hash,
                        mutation.file_size_bytes,
                        mutation.file_mtime_ns,
                        mutation.stat_revision,
                        mutation.tag_revision,
                        now,
                        catalog_tag.title,
                        _fold(catalog_tag.title),
                        catalog_tag.artist,
                        _fold(catalog_tag.artist),
                        catalog_tag.album,
                        _fold(catalog_tag.album),
                        catalog_tag.album_artist or catalog_tag.artist,
                        _fold(catalog_tag.album_artist or catalog_tag.artist),
                        tag.album,
                        tag.album_artist or "",
                        catalog_tag.disc_number,
                        catalog_tag.track_number,
                        catalog_tag.year,
                        catalog_tag.genre,
                        _fold(catalog_tag.genre),
                        catalog_tag.title_sort,
                        catalog_tag.artist_sort,
                        catalog_tag.album_sort,
                        catalog_tag.album_artist_sort,
                        catalog_tag.disc_subtitle,
                        int(catalog_tag.compilation),
                        tag.musicbrainz_release_group_id,
                        tag.musicbrainz_release_id,
                        tag.musicbrainz_recording_id,
                        tag.musicbrainz_release_track_id,
                        tag.musicbrainz_artist_id,
                        tag.musicbrainz_album_artist_id,
                        info.duration_seconds,
                        info.file_format,
                        info.bitrate,
                        info.sample_rate,
                        info.bit_depth,
                        info.channels,
                        tag.replaygain_track_gain,
                        tag.replaygain_album_gain,
                        tag.replaygain_track_peak,
                        tag.replaygain_album_peak,
                        mutation.local_track_id,
                    ),
                )
                genres = [
                    LocalTrackGenre(
                        local_track_id=mutation.local_track_id,
                        position=position,
                        name=value,
                        folded_name=_fold(value) or "",
                        source="local",
                        source_document_revision=mutation.tag_revision,
                    )
                    for position, value in enumerate(
                        catalog_tag.genres
                        or ([catalog_tag.genre] if catalog_tag.genre else [])
                    )
                ]
                self._replace_track_genres_tx(
                    connection,
                    mutation.local_track_id,
                    genres,
                    scalar_genre=catalog_tag.genre,
                )
                connection.execute(
                    "DELETE FROM local_track_artists WHERE local_track_id=?",
                    (mutation.local_track_id,),
                )
                connection.executemany(
                    "INSERT INTO local_track_artists "
                    "(local_track_id,position,local_artist_id,role,credited_name,join_phrase) "
                    "VALUES (?,?,?,'primary',?,?)",
                    [
                        (
                            mutation.local_track_id,
                            credit.position,
                            credit.local_artist_id,
                            credit.credited_name,
                            credit.join_phrase,
                        )
                        for credit in track_credits
                    ],
                )
                if mutation.local_album_id not in updated_albums:
                    assert album_credits is not None
                    relative_parent = str(
                        PurePosixPath(mutation.destination_relative_path).parent
                    )
                    grouping_key = (
                        f"{relative_parent}\x00{catalog_tag.album.casefold()}\x00"
                        f"{(catalog_tag.album_artist or catalog_tag.artist).casefold()}"
                    )
                    connection.execute(
                        "UPDATE local_albums SET root_id=?, grouping_key=?, title=?, "
                        "title_folded=?, album_artist_name=?, album_artist_name_folded=?, "
                        "tag_album_title=?,tag_album_artist_name=?,album_artist_id=?,"
                        "album_artist_sort_name=?, year=?,original_release_date=?,primary_genre=?, "
                        "is_compilation=?, updated_at=?, row_revision=row_revision+1 "
                        "WHERE id=?",
                        (
                            mutation.destination_root_id,
                            grouping_key,
                            catalog_tag.album,
                            _fold(catalog_tag.album),
                            catalog_tag.album_artist or catalog_tag.artist,
                            _fold(catalog_tag.album_artist or catalog_tag.artist),
                            tag.album,
                            tag.album_artist or "",
                            album_credits[0].local_artist_id,
                            catalog_tag.album_artist_sort,
                            catalog_tag.year,
                            catalog_tag.original_release_date,
                            catalog_tag.genre,
                            int(catalog_tag.compilation),
                            now,
                            mutation.local_album_id,
                        ),
                    )
                    connection.execute(
                        "DELETE FROM local_album_artists WHERE local_album_id=?",
                        (mutation.local_album_id,),
                    )
                    connection.executemany(
                        "INSERT INTO local_album_artists "
                        "(local_album_id,position,local_artist_id,role,credited_name,join_phrase) "
                        "VALUES (?,?,?,'primary',?,?)",
                        [
                            (
                                mutation.local_album_id,
                                credit.position,
                                credit.local_artist_id,
                                credit.credited_name,
                                credit.join_phrase,
                            )
                            for credit in album_credits
                        ],
                    )
                    updated_albums.add(mutation.local_album_id)
                managed_path_revision = hashlib.sha256(
                    (
                        f"{mutation.destination_root_id}\x00"
                        f"{mutation.destination_relative_path}\x00"
                        f"{mutation.file_fingerprint}"
                    ).encode()
                ).hexdigest()
                restored_state = (
                    json.loads(mutation.restored_management_state_json)
                    if mutation.restored_management_state_json is not None
                    else None
                )
                if restored_state is not None and not isinstance(restored_state, dict):
                    raise ValidationError("The restored management state is invalid.")
                state_values = (
                    (
                        restored_state.get("baseline_id") or mutation.baseline_id,
                        restored_state.get("applied_profile_id"),
                        restored_state.get("applied_profile_revision"),
                        restored_state.get("applied_projection_hash"),
                        restored_state.get("applied_naming_script_revision"),
                        restored_state.get("applied_override_revision"),
                        restored_state.get("last_operation_job_id") or job_id,
                        restored_state.get("managed_root_id")
                        or mutation.destination_root_id,
                        restored_state.get("managed_path_revision")
                        or managed_path_revision,
                        restored_state.get("last_managed_at") or now,
                        restored_state.get("last_outcome") or "undone",
                        restored_state.get("last_reason_code"),
                    )
                    if restored_state is not None
                    else (
                        mutation.baseline_id,
                        mutation.applied_profile_id,
                        mutation.applied_profile_revision,
                        mutation.applied_projection_hash,
                        mutation.applied_naming_script_revision,
                        mutation.applied_override_revision,
                        job_id,
                        mutation.destination_root_id,
                        managed_path_revision,
                        now,
                        "succeeded",
                        None,
                    )
                )
                connection.execute(
                    "INSERT INTO library_track_management_state "
                    "(local_track_id,baseline_id,applied_profile_id,"
                    "applied_profile_revision,applied_projection_hash,"
                    "applied_naming_script_revision,applied_override_revision,"
                    "last_operation_job_id,managed_root_id,managed_path_revision,"
                    "last_managed_at,last_outcome,last_reason_code,row_revision) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,1) "
                    "ON CONFLICT(local_track_id) DO UPDATE SET baseline_id=excluded.baseline_id,"
                    "applied_profile_id=excluded.applied_profile_id,"
                    "applied_profile_revision=excluded.applied_profile_revision,"
                    "applied_projection_hash=excluded.applied_projection_hash,"
                    "applied_naming_script_revision=excluded.applied_naming_script_revision,"
                    "applied_override_revision=excluded.applied_override_revision,"
                    "last_operation_job_id=excluded.last_operation_job_id,"
                    "managed_root_id=excluded.managed_root_id,"
                    "managed_path_revision=excluded.managed_path_revision,"
                    "last_managed_at=excluded.last_managed_at,"
                    "last_outcome=excluded.last_outcome,"
                    "last_reason_code=excluded.last_reason_code,"
                    "row_revision=library_track_management_state.row_revision+1",
                    (
                        mutation.local_track_id,
                        *state_values,
                    ),
                )
                connection.execute(
                    "INSERT INTO library_catalog_actions "
                    "(id,idempotency_key,actor_user_id,action_kind,local_album_id,"
                    "local_track_id,operation_job_id,before_json,after_json,reason_code,"
                    "created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                    (
                        str(uuid.uuid4()),
                        f"management:{job_id}:{mutation.journal_id}",
                        actor_user_id,
                        "library_management",
                        mutation.local_album_id,
                        mutation.local_track_id,
                        job_id,
                        json.dumps(before, separators=(",", ":"), sort_keys=True),
                        json.dumps(
                            {
                                "root_id": mutation.destination_root_id,
                                "relative_path": mutation.destination_relative_path,
                                "title": catalog_tag.title,
                                "artist": catalog_tag.artist,
                                "album": catalog_tag.album,
                                "file_fingerprint": mutation.file_fingerprint,
                            },
                            separators=(",", ":"),
                            sort_keys=True,
                        ),
                        (
                            "LIBRARY_MANAGEMENT_UNDONE"
                            if mutation.restored_management_state_json is not None
                            else "LIBRARY_MANAGEMENT_APPLIED"
                        ),
                        now,
                    ),
                )
                if str(snapshot["mode"]) == "baseline_restore":
                    connection.execute(
                        "UPDATE library_management_baselines SET "
                        "restore_status='restored',last_verified_at=?,"
                        "row_revision=row_revision+1 WHERE id=? AND row_revision<?",
                        (now, mutation.baseline_id, MAX_REVISION),
                    )
                else:
                    connection.execute(
                        "UPDATE library_management_baselines SET "
                        "restore_status='available',last_verified_at=?,"
                        "row_revision=row_revision+1 WHERE id=? "
                        "AND restore_status='restored' AND row_revision<?",
                        (now, mutation.baseline_id, MAX_REVISION),
                    )

            if tag_edit_intent is not None:
                self._apply_tag_edit_intent_tx(
                    connection,
                    job_id,
                    str(actor_user_id) if actor_user_id is not None else None,
                    tag_edit_intent,
                    mutations,
                    now=now,
                )

            if (
                str(snapshot["mode"]) == "undo"
                and snapshot["linked_operation_job_id"] is not None
            ):
                source_snapshot = connection.execute(
                    "SELECT intent_json FROM library_management_job_snapshots "
                    "WHERE job_id=?",
                    (snapshot["linked_operation_job_id"],),
                ).fetchone()
                if source_snapshot is not None:
                    try:
                        source_intent = json.loads(str(source_snapshot["intent_json"]))
                    except json.JSONDecodeError as error:
                        raise ValidationError(
                            "The source conversion history is invalid."
                        ) from error
                    conversion_before = source_intent.get("edition_conversion_before")
                    if conversion_before is not None:
                        self._restore_edition_conversion_before_tx(
                            connection, conversion_before, now=now
                        )

            new_catalog_revision = self._bump_catalog(connection)
            journal_ids = tuple(sorted(journal_by_id))
            placeholders = ",".join("?" for _ in journal_ids)
            connection.execute(
                "UPDATE library_file_mutation_journal SET state='catalog_committed', "
                "updated_at=?, row_revision=row_revision+1 WHERE id IN ("
                + placeholders
                + ") AND state='published'",
                (now, *journal_ids),
            )
            committed_revision_rows = connection.execute(
                "SELECT id,row_revision FROM library_file_mutation_journal WHERE id IN ("
                + placeholders
                + ")",
                journal_ids,
            ).fetchall()
            committed_journal_revisions = {
                str(row["id"]): int(row["row_revision"])
                for row in committed_revision_rows
            }
            connection.execute(
                "UPDATE library_operation_work SET state='succeeded', result_json=?, "
                "failure_code=NULL, updated_at=?, row_revision=row_revision+1 "
                "WHERE job_id=? AND ordinal=? AND state='running'",
                (
                    json.dumps(
                        {
                            "committed_tracks": len(mutations),
                            "catalog_revision": new_catalog_revision,
                        },
                        separators=(",", ":"),
                        sort_keys=True,
                    ),
                    now,
                    job_id,
                    bundle_ordinal,
                ),
            )
            connection.execute(
                "UPDATE library_operation_jobs SET completed_count=completed_count+1, "
                "succeeded_count=succeeded_count+1, updated_at=?, "
                "row_revision=row_revision+1,event_revision=event_revision+1 "
                "WHERE id=? AND state='running' AND lease_owner=?",
                (now, job_id, worker_id),
            )
            updated_snapshot = connection.execute(
                "UPDATE library_management_job_snapshots SET catalog_revision=?, "
                "updated_at=?,row_revision=row_revision+1 WHERE job_id=? "
                "AND phase IN ('applying','undoing','restoring') RETURNING row_revision",
                (new_catalog_revision, now, job_id),
            ).fetchone()
            if updated_snapshot is None:
                raise StaleRevisionError(
                    "The management snapshot changed before catalog commit."
                )
            self._bump_stream(connection, "operation")
            return LibraryManagementBundleCommitResult(
                catalog_revision=new_catalog_revision,
                snapshot_revision=int(updated_snapshot["row_revision"]),
                committed_journal_ids=journal_ids,
                committed_journal_revisions=committed_journal_revisions,
            )

        return await self._write(operation)

    @staticmethod
    def _restore_edition_conversion_before_tx(
        connection: sqlite3.Connection,
        before: dict[str, Any],
        *,
        now: float,
    ) -> None:
        album_id = str(before.get("local_album_id") or "")
        original_track_ids = {
            str(value) for value in before.get("original_track_ids", [])
        }
        if not album_id or not original_track_ids:
            raise ValidationError(
                "The prior edition-conversion identity is incomplete."
            )
        current_ids = {
            str(row["id"])
            for row in connection.execute(
                "SELECT id FROM local_tracks WHERE local_album_id=?",
                (album_id,),
            ).fetchall()
        }
        if original_track_ids - current_ids:
            raise StaleRevisionError(
                "Undo cannot restore a missing original conversion track."
            )
        new_ids = current_ids - original_track_ids
        if new_ids:
            placeholders = ",".join("?" for _ in new_ids)
            connection.execute(
                "UPDATE local_tracks SET availability='missing',missing_since=?,"
                "row_revision=row_revision+1 WHERE id IN (" + placeholders + ")",
                (now, *sorted(new_ids)),
            )
        connection.execute(
            "UPDATE local_tracks SET availability='indexed',missing_since=NULL,"
            "excluded_at=NULL WHERE id IN ("
            + ",".join("?" for _ in original_track_ids)
            + ")",
            tuple(sorted(original_track_ids)),
        )
        connection.execute(
            "DELETE FROM local_track_external_identities WHERE provider='musicbrainz' "
            "AND local_track_id IN (SELECT id FROM local_tracks WHERE local_album_id=?)",
            (album_id,),
        )
        for identity in before.get("track_identities", []):
            recording_mbid = identity.get("recording_mbid")
            if not recording_mbid:
                continue
            connection.execute(
                "INSERT INTO local_track_external_identities "
                "(local_track_id,provider,recording_mbid,release_mbid,"
                "release_track_mbid,medium_position,release_track_position,"
                "decision_source,attempt_id,selected_at,row_revision) "
                "VALUES (?,'musicbrainz',?,?,?,?,?,'manual',NULL,?,1)",
                (
                    identity["id"],
                    recording_mbid,
                    identity.get("identity_release_mbid"),
                    identity.get("release_track_mbid"),
                    identity.get("medium_position"),
                    identity.get("release_track_position"),
                    now,
                ),
            )
        connection.execute(
            "DELETE FROM local_album_external_identities WHERE local_album_id=? "
            "AND provider='musicbrainz'",
            (album_id,),
        )
        album_identity = before.get("album_identity")
        if album_identity is not None:
            connection.execute(
                "INSERT INTO local_album_external_identities "
                "(local_album_id,provider,release_group_mbid,release_mbid,"
                "decision_source,matcher_version,attempt_id,selected_by_user_id,"
                "selected_at,row_revision) VALUES (?,'musicbrainz',?,?,? ,NULL,NULL,NULL,?,1)",
                (
                    album_id,
                    album_identity["release_group_mbid"],
                    album_identity.get("release_mbid"),
                    album_identity.get("decision_source") or "manual",
                    now,
                ),
            )
        connection.execute(
            "DELETE FROM library_custom_edition_active WHERE local_album_id=?",
            (album_id,),
        )
        custom_active = before.get("custom_active")
        if custom_active is not None:
            previous_manifest = connection.execute(
                "SELECT * FROM library_custom_edition_manifests WHERE id=?",
                (custom_active["manifest_id"],),
            ).fetchone()
            previous_tracks = connection.execute(
                "SELECT * FROM library_custom_edition_tracks WHERE manifest_id=? "
                "ORDER BY ordinal",
                (custom_active["manifest_id"],),
            ).fetchall()
            album = connection.execute(
                "SELECT row_revision FROM local_albums WHERE id=?", (album_id,)
            ).fetchone()
            provider = connection.execute(
                "SELECT row_revision FROM local_album_external_identities "
                "WHERE local_album_id=? AND provider='musicbrainz'",
                (album_id,),
            ).fetchone()
            current_tracks = connection.execute(
                "SELECT track.*,identity.row_revision AS identity_revision "
                "FROM local_tracks track LEFT JOIN local_track_external_identities identity "
                "ON identity.local_track_id=track.id AND identity.provider='musicbrainz' "
                "WHERE track.local_album_id=? AND track.availability='indexed'",
                (album_id,),
            ).fetchall()
            current_by_id = {str(value["id"]): value for value in current_tracks}
            if (
                previous_manifest is None
                or album is None
                or provider is None
                or not previous_tracks
                or {str(value["local_track_id"]) for value in previous_tracks}
                != set(current_by_id)
            ):
                raise StaleRevisionError(
                    "Undo cannot restore the prior Custom edition manifest."
                )
            version = int(
                connection.execute(
                    "SELECT COALESCE(MAX(version),0)+1 FROM "
                    "library_custom_edition_manifests WHERE local_album_id=?",
                    (album_id,),
                ).fetchone()[0]
            )
            manifest_id = str(uuid.uuid4())
            content_hash = hashlib.sha256(
                json.dumps(
                    {
                        "restored_from": previous_manifest["id"],
                        "version": version,
                        "album_revision": int(album["row_revision"]),
                        "identity_revision": int(provider["row_revision"]),
                        "input_revision": _album_input_revision(current_tracks),
                        "tracks": [
                            {
                                "id": value["local_track_id"],
                                "revision": int(
                                    current_by_id[str(value["local_track_id"])][
                                        "row_revision"
                                    ]
                                ),
                            }
                            for value in previous_tracks
                        ],
                    },
                    separators=(",", ":"),
                    sort_keys=True,
                ).encode()
            ).hexdigest()
            connection.execute(
                "INSERT INTO library_custom_edition_manifests "
                "(id,local_album_id,version,release_group_mbid,album_title,"
                "album_artist_name,artist_mbid,album_metadata_json,"
                "source_album_revision,source_identity_revision,input_revision,"
                "content_hash,selected_candidate_key,sealed_by_user_id,sealed_at) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    manifest_id,
                    album_id,
                    version,
                    previous_manifest["release_group_mbid"],
                    previous_manifest["album_title"],
                    previous_manifest["album_artist_name"],
                    previous_manifest["artist_mbid"],
                    previous_manifest["album_metadata_json"],
                    album["row_revision"],
                    provider["row_revision"],
                    _album_input_revision(current_tracks),
                    content_hash,
                    previous_manifest["selected_candidate_key"],
                    previous_manifest["sealed_by_user_id"],
                    now,
                ),
            )
            for previous in previous_tracks:
                current = current_by_id[str(previous["local_track_id"])]
                connection.execute(
                    "INSERT INTO library_custom_edition_tracks "
                    "(manifest_id,ordinal,local_track_id,source_track_revision,"
                    "source_identity_revision,stat_revision,tag_revision,title,"
                    "artist_name,album_title,album_artist_name,disc_number,"
                    "track_number,recording_mbid,artist_mbid,album_artist_mbid,"
                    "metadata_json,file_format,duration_seconds) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (
                        manifest_id,
                        previous["ordinal"],
                        previous["local_track_id"],
                        current["row_revision"],
                        current["identity_revision"],
                        current["stat_revision"],
                        current["tag_revision"],
                        current["title"],
                        current["artist_name"] or "",
                        current["album_title"],
                        previous["album_artist_name"],
                        current["disc_number"],
                        current["track_number"],
                        previous["recording_mbid"],
                        previous["artist_mbid"],
                        previous["album_artist_mbid"],
                        previous["metadata_json"],
                        current["file_format"],
                        current["duration_seconds"],
                    ),
                )
            connection.execute(
                "INSERT INTO library_custom_edition_active "
                "(local_album_id,manifest_id,activated_at,row_revision) VALUES (?,?,?,1)",
                (
                    album_id,
                    manifest_id,
                    now,
                ),
            )
        connection.execute(
            "DELETE FROM library_management_exclusions WHERE local_album_id=?",
            (album_id,),
        )
        exclusion = before.get("management_exclusion")
        if exclusion is not None:
            connection.execute(
                "INSERT INTO library_management_exclusions "
                "(local_album_id,reason,excluded_by_user_id,excluded_at,row_revision) "
                "VALUES (?,?,?,?,1)",
                (
                    album_id,
                    exclusion["reason"],
                    exclusion["excluded_by_user_id"],
                    exclusion["excluded_at"],
                ),
            )

    async def add_management_collision_evidence(
        self, collisions: list[LibraryManagementCollisionEvidence]
    ) -> None:
        if not collisions or len(collisions) > MANAGEMENT_PERSISTENCE_BATCH_SIZE:
            raise ValidationError("Collision batches must contain 1 to 500 rows.")

        def operation(connection: sqlite3.Connection) -> None:
            connection.executemany(
                "INSERT OR IGNORE INTO library_management_collision_evidence "
                "(id, job_id, plan_item_ordinal, classification, existing_local_track_id, "
                "destination_root_id, destination_relative_path, evidence_json, created_at) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                [
                    (
                        collision.id,
                        collision.job_id,
                        collision.plan_item_ordinal,
                        collision.classification,
                        collision.existing_local_track_id,
                        collision.destination_root_id,
                        collision.destination_relative_path,
                        collision.evidence_json,
                        collision.created_at,
                    )
                    for collision in collisions
                ],
            )

        await self._write(operation)

    async def create_operation_with_work(
        self, job: OperationJob, work: list[OperationWorkItem]
    ) -> None:
        def operation(connection: sqlite3.Connection) -> None:
            connection.execute(
                "INSERT INTO library_operation_jobs "
                "(id, kind, state, requested_by_user_id, input_catalog_revision, "
                "expected_work_count, idempotency_key, created_at, updated_at, "
                "row_revision, event_revision) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                (
                    job.id,
                    job.kind,
                    job.state,
                    job.requested_by_user_id,
                    job.input_catalog_revision,
                    len(work),
                    job.idempotency_key,
                    job.created_at,
                    job.created_at,
                    job.row_revision,
                    job.event_revision,
                ),
            )
            connection.executemany(
                "INSERT INTO library_operation_work "
                "(job_id, ordinal, local_album_id, local_track_id, expected_subject_revision, "
                "expected_input_revision, action, idempotency_key, updated_at) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                [
                    (
                        job.id,
                        item.ordinal,
                        item.local_album_id,
                        item.local_track_id,
                        item.expected_subject_revision,
                        item.expected_input_revision,
                        item.action,
                        item.idempotency_key,
                        job.created_at,
                    )
                    for item in work
                ],
            )

        await self._write(operation)
        self.work_wakeups.notify("operation")

    async def materialize_bulk_review_operation(
        self,
        job: OperationJob,
        *,
        action: str,
        review_ids: list[str],
        expected_revisions: dict[str, int],
        normalized_filter: dict[str, str],
        preview_token: str,
        preview_action: str,
        candidate_key: str | None,
        confirm_local_metadata: bool,
        created_at: float,
    ) -> dict[str, Any]:
        """Create the header; work is staged separately in restart-safe batches."""

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            if job.idempotency_key:
                existing = connection.execute(
                    "SELECT * FROM library_operation_jobs WHERE idempotency_key = ?",
                    (job.idempotency_key,),
                ).fetchone()
                if existing is not None:
                    return dict(existing)
            expected_selection = {
                "review_ids": review_ids,
                "expected_revisions": expected_revisions,
                "normalized_filter": normalized_filter,
                "catalog_revision": job.input_catalog_revision,
                "candidate_key": candidate_key,
            }
            preview = connection.execute(
                "SELECT * FROM library_bulk_review_previews WHERE preview_token = ?",
                (preview_token,),
            ).fetchone()
            if (
                preview is None
                or float(preview["expires_at"]) < created_at
                or str(preview["action"]) != preview_action
                or str(preview["state"]) != "ready"
                or str(preview["selection_json"])
                != json.dumps(expected_selection, sort_keys=True)
            ):
                raise StaleRevisionError(
                    "The bulk preview changed or expired before Apply."
                )
            if (
                preview_action == "retry"
                and bool(preview["requires_local_metadata_confirmation"])
                and not confirm_local_metadata
            ):
                raise StaleRevisionError(
                    "Confirm the one-off lookup for Local metadata content."
                )
            subject_count = int(preview["subject_count"])
            if subject_count == 0:
                subject_count = int(
                    connection.execute(
                        "SELECT COUNT(*) FROM library_bulk_review_preview_subjects "
                        "WHERE preview_token = ?",
                        (preview_token,),
                    ).fetchone()[0]
                )
            connection.execute(
                "INSERT INTO library_operation_jobs "
                "(id, kind, state, requested_by_user_id, input_catalog_revision, "
                "expected_work_count, idempotency_key, created_at, updated_at) "
                "VALUES (?, 'bulk_review_apply', 'queued', ?, ?, ?, ?, ?, ?)",
                (
                    job.id,
                    job.requested_by_user_id,
                    job.input_catalog_revision,
                    subject_count,
                    job.idempotency_key,
                    created_at,
                    created_at,
                ),
            )
            connection.execute(
                "INSERT INTO library_bulk_review_snapshots "
                "(job_id, action, selection_json, normalized_filter_json, preview_token, "
                "staging_state, staging_cursor, created_at) "
                "VALUES (?,?,?,?,?,'staging',-1,?)",
                (
                    job.id,
                    action,
                    json.dumps(
                        review_ids
                        if review_ids
                        else {"normalized_filter": normalized_filter},
                        sort_keys=True,
                    ),
                    json.dumps(normalized_filter, sort_keys=True)
                    if normalized_filter
                    else None,
                    preview_token,
                    created_at,
                ),
            )
            self._bump_stream(connection, "operation")
            created = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id = ?", (job.id,)
            ).fetchone()
            return dict(created)

        result = await self._write(operation)
        self.work_wakeups.notify("operation")
        return result

    async def stage_bulk_review_operation_batch(
        self,
        job_id: str,
        worker_id: str,
        *,
        now: float,
        batch_size: int = BULK_PREVIEW_BATCH_SIZE,
    ) -> dict[str, Any]:
        limit = min(max(batch_size, 1), BULK_PREVIEW_BATCH_SIZE)

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            job = connection.execute(
                "SELECT id FROM library_operation_jobs WHERE id = ? AND state = 'running' "
                "AND lease_owner = ?",
                (job_id, worker_id),
            ).fetchone()
            if job is None:
                raise StaleRevisionError(
                    "The operation lease changed while its work was staged."
                )
            snapshot = connection.execute(
                "SELECT * FROM library_bulk_review_snapshots WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if snapshot is None:
                raise ResourceNotFoundError("Bulk review snapshot not found.")
            if str(snapshot["staging_state"]) == "ready":
                return {"complete": True, "staged_count": 0}
            rows = connection.execute(
                "SELECT * FROM library_bulk_review_preview_subjects "
                "WHERE preview_token = ? AND ordinal > ? ORDER BY ordinal LIMIT ?",
                (snapshot["preview_token"], snapshot["staging_cursor"], limit + 1),
            ).fetchall()
            page = rows[:limit]
            connection.executemany(
                "INSERT OR IGNORE INTO library_operation_work "
                "(job_id, ordinal, local_album_id, local_track_id, expected_subject_revision, "
                "expected_input_revision, action, idempotency_key, updated_at) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                [
                    (
                        job_id,
                        row["ordinal"],
                        row["local_album_id"],
                        row["local_track_id"],
                        row["expected_subject_revision"],
                        row["expected_input_revision"],
                        snapshot["action"],
                        f"{job_id}:{row['review_id']}:{snapshot['action']}",
                        now,
                    )
                    for row in page
                ],
            )
            complete = len(rows) <= limit
            cursor = (
                int(page[-1]["ordinal"]) if page else int(snapshot["staging_cursor"])
            )
            connection.execute(
                "UPDATE library_bulk_review_snapshots SET staging_state = ?, "
                "staging_cursor = ? WHERE job_id = ?",
                ("ready" if complete else "staging", cursor, job_id),
            )
            return {"complete": complete, "staged_count": len(page)}

        return await super()._background_write(operation)

    async def create_reidentification_operation(
        self,
        job: OperationJob,
        *,
        local_album_id: str,
        expected_album_revision: int,
        expected_input_revision: str,
        one_off_local_metadata: bool,
        requested_release_mbid: str | None = None,
        review_id: str | None = None,
        expected_review_revision: int | None = None,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            if job.idempotency_key:
                existing = connection.execute(
                    "SELECT * FROM library_operation_jobs WHERE idempotency_key = ?",
                    (job.idempotency_key,),
                ).fetchone()
                if existing is not None:
                    return dict(existing)
            album = connection.execute(
                "SELECT row_revision FROM local_albums WHERE id = ? "
                "AND retired_into_album_id IS NULL",
                (local_album_id,),
            ).fetchone()
            if album is None:
                raise ResourceNotFoundError("Local album not found.")
            if int(album["row_revision"]) != expected_album_revision:
                raise StaleRevisionError(
                    "The album changed before re-identification started."
                )
            current_tracks = connection.execute(
                "SELECT id,tag_revision,stat_revision,applied_policy_revision,"
                "applied_policy FROM local_tracks WHERE local_album_id=? "
                "AND availability='indexed'",
                (local_album_id,),
            ).fetchall()
            if not current_tracks:
                raise ResourceNotFoundError("Local album has no indexed tracks.")
            if _album_input_revision(list(current_tracks)) != expected_input_revision:
                raise StaleRevisionError(
                    "The album files changed before re-identification started."
                )
            policies = {
                str(row[0])
                for row in connection.execute(
                    "SELECT DISTINCT applied_policy FROM local_tracks "
                    "WHERE local_album_id = ? AND availability = 'indexed'",
                    (local_album_id,),
                )
            }
            if "excluded" in policies:
                raise StaleRevisionError("Excluded albums cannot be re-identified.")
            if "local_metadata" in policies and not one_off_local_metadata:
                raise StaleRevisionError(
                    "Confirm the one-off lookup for Local metadata content."
                )
            if review_id is not None:
                review = connection.execute(
                    "SELECT * FROM library_identification_reviews WHERE id = ? "
                    "AND local_album_id = ? AND state != 'resolved'",
                    (review_id, local_album_id),
                ).fetchone()
                if (
                    review is None
                    or expected_review_revision is None
                    or int(review["row_revision"]) != expected_review_revision
                ):
                    raise StaleRevisionError(
                        "The review decision changed before Retry identification."
                    )
            connection.execute(
                "INSERT INTO library_operation_jobs "
                "(id, kind, state, requested_by_user_id, expected_work_count, idempotency_key, "
                "created_at, updated_at) VALUES (?, 'explicit_reidentification', 'queued', ?, 1, ?, ?, ?)",
                (
                    job.id,
                    job.requested_by_user_id,
                    job.idempotency_key,
                    job.created_at,
                    job.created_at,
                ),
            )
            if review_id is not None:
                connection.execute(
                    "UPDATE library_identification_reviews SET state = 'resolved', "
                    "reason_code = 'EXPLICIT_RETRY', decided_by_user_id = ?, decided_at = ?, "
                    "updated_at = ?, decision_revision = decision_revision + 1, "
                    "row_revision = row_revision + 1 WHERE id = ?",
                    (
                        job.requested_by_user_id,
                        job.created_at,
                        job.created_at,
                        review_id,
                    ),
                )
            album_identity, identity_tracks = _identification_identity_rows(
                connection, local_album_id
            )
            expected_identity_revision = _album_identity_revision(
                album_identity, identity_tracks
            )
            connection.execute(
                "INSERT INTO library_reidentification_snapshots "
                "(job_id, local_album_id, expected_album_revision, expected_input_revision, "
                "expected_identity_revision, one_off_local_metadata, requested_release_mbid, "
                "created_at) VALUES (?,?,?,?,?,?,?,?)",
                (
                    job.id,
                    local_album_id,
                    expected_album_revision,
                    expected_input_revision,
                    expected_identity_revision,
                    int(one_off_local_metadata),
                    requested_release_mbid,
                    job.created_at,
                ),
            )
            connection.execute(
                "INSERT INTO library_operation_work "
                "(job_id, ordinal, local_album_id, expected_subject_revision, expected_input_revision, "
                "action, idempotency_key, updated_at) VALUES (?,0,?,?,?,?,?,?)",
                (
                    job.id,
                    local_album_id,
                    expected_album_revision,
                    expected_input_revision,
                    "reidentify",
                    f"{job.id}:{local_album_id}",
                    job.created_at,
                ),
            )
            self._bump_stream(connection, "operation")
            return dict(
                connection.execute(
                    "SELECT * FROM library_operation_jobs WHERE id = ?", (job.id,)
                ).fetchone()
            )

        result = await self._write(operation)
        self.work_wakeups.notify("operation")
        return result

    async def finish_reidentification_evaluation(
        self,
        job_id: str,
        ordinal: int,
        *,
        worker_id: str,
        expected_work_revision: int,
        expected_album_revision: int,
        attempt: IdentificationAttempt,
        evidence: list[IdentificationEvidenceRecord],
        now: float,
    ) -> dict[str, Any]:
        """Commit one explicit re-identification evaluation terminally.

        F-055/F-IDENT-03: degradation-flag outages no longer reach here on
        their first pass - the worker defers them like raised outages. This
        finish records the honest PROVIDER_TEMPORARILY_UNAVAILABLE failure
        only once the bounded retry budget is exhausted.
        """

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            snapshot = connection.execute(
                "SELECT * FROM library_reidentification_snapshots WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if snapshot is None:
                raise ResourceNotFoundError("Re-identification snapshot not found.")
            album = connection.execute(
                "SELECT * FROM local_albums WHERE id = ?",
                (snapshot["local_album_id"],),
            ).fetchone()
            if album is None or int(album["row_revision"]) != expected_album_revision:
                raise StaleRevisionError("The album changed during re-identification.")
            current_tracks = connection.execute(
                "SELECT id,tag_revision,stat_revision,applied_policy_revision,"
                "applied_policy FROM local_tracks WHERE local_album_id=? "
                "AND availability='indexed'",
                (snapshot["local_album_id"],),
            ).fetchall()
            if _album_input_revision(list(current_tracks)) != str(
                snapshot["expected_input_revision"]
            ):
                raise StaleRevisionError(
                    "The album files changed during re-identification."
                )
            current_album_identity, current_identity_tracks = (
                _identification_identity_rows(
                    connection, str(snapshot["local_album_id"])
                )
            )
            current_identity_revision = _album_identity_revision(
                current_album_identity, current_identity_tracks
            )
            if (
                current_identity_revision != str(snapshot["expected_identity_revision"])
                or current_identity_revision != attempt.input_identity_revision
            ):
                raise StaleRevisionError(
                    "The album identity changed during re-identification."
                )
            work = connection.execute(
                "SELECT row_revision FROM library_operation_work WHERE job_id = ? AND ordinal = ? "
                "AND state = 'running' AND row_revision = ?",
                (job_id, ordinal, expected_work_revision),
            ).fetchone()
            if work is None:
                raise StaleRevisionError("The re-identification checkpoint changed.")
            connection.execute(
                "INSERT INTO library_identification_attempts "
                "(id, local_album_id, local_track_id, trigger, requested_by_user_id, "
                "input_tag_revision, input_policy_revision, input_file_revision, "
                "input_identity_revision, matcher_version, "
                "state, terminal_reason_code, selected_candidate_key, candidate_count, "
                "degradation_flags_json, started_at, completed_at) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    attempt.id,
                    attempt.local_album_id,
                    attempt.local_track_id,
                    attempt.trigger,
                    attempt.requested_by_user_id,
                    attempt.input_tag_revision,
                    attempt.input_policy_revision,
                    attempt.input_file_revision,
                    attempt.input_identity_revision,
                    attempt.matcher_version,
                    attempt.state,
                    attempt.terminal_reason_code,
                    attempt.selected_candidate_key,
                    attempt.candidate_count,
                    json.dumps(attempt.degradation_flags),
                    attempt.started_at,
                    attempt.completed_at,
                ),
            )
            self._insert_evidence(connection, evidence)
            result = {
                "attempt_id": attempt.id,
                "candidate_keys": [record.candidate_key for record in evidence],
                "outcome": attempt.state,
                "reason_code": attempt.terminal_reason_code,
            }
            provider_unavailable = (
                not evidence
                and attempt.terminal_reason_code == "PROVIDER_TEMPORARILY_UNAVAILABLE"
            )
            connection.execute(
                "UPDATE library_operation_work SET state = ?, result_json = ?, failure_code = ?, "
                "updated_at = ?, row_revision = row_revision + 1 WHERE job_id = ? AND ordinal = ?",
                (
                    "failed" if provider_unavailable else "succeeded",
                    json.dumps(result, sort_keys=True),
                    attempt.terminal_reason_code if provider_unavailable else None,
                    now,
                    job_id,
                    ordinal,
                ),
            )
            state = (
                "failed"
                if provider_unavailable
                else ("ready" if evidence else "succeeded")
            )
            terminal_code = (
                "CANDIDATES_READY" if evidence else attempt.terminal_reason_code
            )
            connection.execute(
                "UPDATE library_reidentification_snapshots SET result_json = ? WHERE job_id = ?",
                (json.dumps(result, sort_keys=True), job_id),
            )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = ?, completed_count = 1, "
                "succeeded_count = ?, failed_count = ?, "
                "terminal_code = ?, lease_owner = NULL, lease_expires_at = NULL, heartbeat_at = NULL, "
                "updated_at = ?, terminal_at = CASE WHEN ? IN ('succeeded','failed') THEN ? ELSE NULL END, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND state = 'running' AND lease_owner = ? RETURNING *",
                (
                    state,
                    int(not provider_unavailable),
                    int(provider_unavailable),
                    terminal_code,
                    now,
                    state,
                    now,
                    job_id,
                    worker_id,
                ),
            ).fetchone()
            if updated is None:
                raise StaleRevisionError(
                    "The re-identification lease changed before completion."
                )
            self._bump_stream(connection, "operation")
            return dict(updated)

        return await self._write(operation)

    async def defer_reidentification_work(
        self,
        job_id: str,
        ordinal: int,
        *,
        worker_id: str,
        reason_code: str,
        now: float,
        retry_not_before: float,
    ) -> dict[str, Any]:
        """F-IDENT-03: durably defer one transient explicit re-identification.

        The running work item returns to 'pending' with the failure code, the
        job returns to 'queued' with ``next_attempt_at`` set, and the durable
        attempt counter advances. Nothing is marked succeeded or failed and no
        candidate is selected; the sealed snapshot stays untouched so the next
        claim re-evaluates against the original revisions.
        """

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            work_update = connection.execute(
                "UPDATE library_operation_work SET state = 'pending', failure_code = ?, "
                "updated_at = ?, row_revision = row_revision + 1 "
                "WHERE job_id = ? AND ordinal = ? AND state = 'running'",
                (reason_code, now, job_id, ordinal),
            )
            if work_update.rowcount != 1:
                raise StaleRevisionError(
                    "The re-identification work lease changed while it was deferred."
                )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = 'queued', lease_owner = NULL, "
                "lease_expires_at = NULL, heartbeat_at = NULL, updated_at = ?, "
                "next_attempt_at = ?, "
                "reidentification_attempt_count = reidentification_attempt_count + 1, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND kind = 'explicit_reidentification' "
                "AND state = 'running' AND lease_owner = ? RETURNING *",
                (now, retry_not_before, job_id, worker_id),
            ).fetchone()
            if updated is None:
                raise StaleRevisionError(
                    "The re-identification lease changed while it was deferred."
                )
            self._bump_stream(connection, "operation")
            return dict(updated)

        result = await self._write(operation)
        self.work_wakeups.notify_after("operation", retry_not_before - now)
        return result

    async def accept_reidentification_candidate(
        self,
        job_id: str,
        *,
        expected_job_revision: int,
        candidate_key: str,
        confirmation: bool,
        actor_user_id: str,
        decision_mode: str = "exact_release",
        now: float,
    ) -> dict[str, Any]:
        if decision_mode not in {
            "exact_release",
            "custom_edition",
            "leave_unmanaged",
        }:
            raise ValidationError("Unknown album management decision.")

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            job = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id = ? AND kind = 'explicit_reidentification'",
                (job_id,),
            ).fetchone()
            snapshot = connection.execute(
                "SELECT * FROM library_reidentification_snapshots WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if job is None or snapshot is None:
                raise ResourceNotFoundError("Re-identification job not found.")
            if (
                job["state"] != "ready"
                and not (
                    job["state"] == "succeeded" and decision_mode == "leave_unmanaged"
                )
            ) or int(job["row_revision"]) != expected_job_revision:
                raise StaleRevisionError(
                    "The re-identification candidates changed before selection."
                )
            album = connection.execute(
                "SELECT row_revision,album_artist_sort_name,year,"
                "original_release_date,primary_genre,is_compilation "
                "FROM local_albums WHERE id = ?",
                (snapshot["local_album_id"],),
            ).fetchone()
            if album is None or int(album["row_revision"]) != int(
                snapshot["expected_album_revision"]
            ):
                raise StaleRevisionError(
                    "The album changed after candidates were evaluated."
                )
            current_tracks = connection.execute(
                "SELECT track.id,track.title,track.artist_name,track.album_title,"
                "track.album_artist_name,track.disc_number,track.track_number,"
                "track.year,track.genre,track.title_sort,track.artist_sort,"
                "track.album_sort,track.album_artist_sort,track.disc_subtitle,"
                "track.is_compilation,track.file_format,"
                "track.duration_seconds,track.row_revision,track.tag_revision,"
                "track.stat_revision,track.applied_policy_revision,track.applied_policy,"
                "track.embedded_recording_mbid,track.embedded_artist_mbid,"
                "track.embedded_album_artist_mbid,identity.recording_mbid,"
                "identity.row_revision AS identity_row_revision "
                "FROM local_tracks track LEFT JOIN local_track_external_identities identity "
                "ON identity.local_track_id=track.id AND identity.provider='musicbrainz' "
                "WHERE track.local_album_id=? "
                "AND availability='indexed'",
                (snapshot["local_album_id"],),
            ).fetchall()
            if _album_input_revision(current_tracks) != str(
                snapshot["expected_input_revision"]
            ):
                raise StaleRevisionError(
                    "The album files changed after candidates were evaluated."
                )
            current_album_identity, current_identity_tracks = (
                _identification_identity_rows(
                    connection, str(snapshot["local_album_id"])
                )
            )
            if _album_identity_revision(
                current_album_identity, current_identity_tracks
            ) != str(snapshot["expected_identity_revision"]):
                raise StaleRevisionError(
                    "The album identity changed after candidates were evaluated."
                )
            result = json.loads(str(snapshot["result_json"]))
            attempt_id = str(result["attempt_id"])
            evidence = None
            if candidate_key != "":
                evidence_row = connection.execute(
                    "SELECT * FROM library_identification_evidence WHERE attempt_id = ? "
                    "AND candidate_key = ?",
                    (attempt_id, candidate_key),
                ).fetchone()
                if evidence_row is None:
                    raise StaleRevisionError(
                        "The selected candidate is no longer available."
                    )
                evidence = msgspec.json.decode(
                    bytes(evidence_row["evidence_json"]), type=CandidateEvidence
                )
            if decision_mode == "leave_unmanaged":
                before_identity = (
                    dict(current_album_identity)
                    if current_album_identity is not None
                    else {}
                )
                if current_album_identity is not None:
                    connection.execute(
                        "UPDATE local_album_external_identities SET release_mbid=NULL,"
                        "decision_source='manual',selected_by_user_id=?,selected_at=?,"
                        "row_revision=row_revision+1 WHERE local_album_id=? "
                        "AND provider='musicbrainz'",
                        (actor_user_id, now, snapshot["local_album_id"]),
                    )
                elif (
                    evidence is not None
                    and is_valid_mbid(evidence.release_group_mbid)
                    and evidence.album_title_classification != "contradictory"
                    and evidence.album_artist_classification != "contradictory"
                ):
                    connection.execute(
                        "INSERT INTO local_album_external_identities "
                        "(local_album_id,provider,release_group_mbid,release_mbid,"
                        "decision_source,matcher_version,attempt_id,selected_by_user_id,"
                        "selected_at) VALUES (?,'musicbrainz',?,NULL,'manual',?,?,?,?)",
                        (
                            snapshot["local_album_id"],
                            evidence.release_group_mbid,
                            evidence.matcher_version,
                            attempt_id,
                            actor_user_id,
                            now,
                        ),
                    )
                connection.execute(
                    "UPDATE local_track_external_identities SET release_mbid=NULL,"
                    "release_track_mbid=NULL,medium_position=NULL,"
                    "release_track_position=NULL,decision_source='manual',selected_at=?,"
                    "row_revision=row_revision+1 WHERE local_track_id IN "
                    "(SELECT id FROM local_tracks WHERE local_album_id=? "
                    "AND availability='indexed')",
                    (now, snapshot["local_album_id"]),
                )
                connection.execute(
                    "INSERT INTO library_management_exclusions "
                    "(local_album_id,reason,excluded_by_user_id,excluded_at,row_revision) "
                    "VALUES (?,?,?, ?,1) ON CONFLICT(local_album_id) DO UPDATE SET "
                    "reason=excluded.reason,excluded_by_user_id=excluded.excluded_by_user_id,"
                    "excluded_at=excluded.excluded_at,row_revision=row_revision+1",
                    (
                        snapshot["local_album_id"],
                        "administrator_choice",
                        actor_user_id,
                        now,
                    ),
                )
                connection.execute(
                    "DELETE FROM library_custom_edition_active WHERE local_album_id=?",
                    (snapshot["local_album_id"],),
                )
                connection.execute(
                    "UPDATE library_identification_reviews SET state='resolved',"
                    "reason_code='MANAGEMENT_EXCLUDED',decided_by_user_id=?,decided_at=?,"
                    "updated_at=?,decision_revision=decision_revision+1,"
                    "row_revision=row_revision+1 WHERE local_album_id=? "
                    "AND state!='resolved'",
                    (actor_user_id, now, now, snapshot["local_album_id"]),
                )
                result.update(
                    {
                        "selected_candidate_key": None,
                        "outcome": "leave_unmanaged",
                    }
                )
                return self._finish_reidentification_management_decision_tx(
                    connection,
                    job=job,
                    snapshot=snapshot,
                    job_id=job_id,
                    expected_job_revision=expected_job_revision,
                    actor_user_id=actor_user_id,
                    result=result,
                    selected_candidate_key=None,
                    terminal_code="LEFT_UNMANAGED",
                    reason_code="MANAGEMENT_EXCLUDED",
                    before=before_identity,
                    now=now,
                )
            if evidence is None:
                raise StaleRevisionError(
                    "The selected candidate is no longer available."
                )
            if decision_mode == "custom_edition":
                if not confirmation:
                    raise CustomEditionNotSealableError(
                        "Confirm creating a Custom edition from the current local album."
                    )
                if (
                    not is_valid_mbid(evidence.release_group_mbid)
                    or evidence.album_title_classification == "contradictory"
                    or evidence.album_artist_classification == "contradictory"
                ):
                    raise CustomEditionNotSealableError(
                        "This album's provider identity conflicts with the selected release group."
                    )
                if (
                    current_album_identity is not None
                    and current_album_identity["release_group_mbid"]
                    and str(current_album_identity["release_group_mbid"]).casefold()
                    != evidence.release_group_mbid.casefold()
                ):
                    raise CustomEditionNotSealableError(
                        "The selected release group conflicts with the album's accepted provider identity."
                    )
                album_context = connection.execute(
                    "SELECT album.title,album.album_artist_name,album.album_artist_id,"
                    "artist_identity.provider_artist_id AS artist_mbid "
                    "FROM local_albums album LEFT JOIN local_artist_external_identities "
                    "artist_identity ON artist_identity.local_artist_id=album.album_artist_id "
                    "AND artist_identity.provider='musicbrainz' WHERE album.id=?",
                    (snapshot["local_album_id"],),
                ).fetchone()
                if album_context is None:
                    raise StaleRevisionError(
                        "The album changed after candidates were evaluated."
                    )
                if (
                    not str(album_context["title"] or "").strip()
                    or not str(album_context["album_artist_name"] or "").strip()
                ):
                    raise CustomEditionNotSealableError(
                        "The local album needs a coherent title and album artist before it can be sealed."
                    )
                if (
                    evidence.artist_mbid
                    and album_context["artist_mbid"]
                    and str(album_context["artist_mbid"]).casefold()
                    != evidence.artist_mbid.casefold()
                ):
                    raise CustomEditionNotSealableError(
                        "The selected album artist conflicts with the accepted artist identity."
                    )
                positions = [
                    (int(row["disc_number"]), int(row["track_number"]))
                    for row in current_tracks
                ]
                if (
                    not current_tracks
                    or any(disc < 1 or track < 1 for disc, track in positions)
                    or len(set(positions)) != len(positions)
                ):
                    raise CustomEditionNotSealableError(
                        "Every local file needs one unique positive disc and track position before it can be sealed."
                    )
                supported_recordings = {
                    item.local_track_id: item.recording_mbid
                    for item in evidence.track_evidence
                    if item.classification == "supported" and item.recording_mbid
                }
                connection.execute(
                    "INSERT INTO local_album_external_identities "
                    "(local_album_id,provider,release_group_mbid,release_mbid,"
                    "decision_source,matcher_version,attempt_id,selected_by_user_id,"
                    "selected_at) VALUES (?,'musicbrainz',?,NULL,'manual',?,?,?,?) "
                    "ON CONFLICT(local_album_id,provider) DO UPDATE SET "
                    "release_group_mbid=excluded.release_group_mbid,release_mbid=NULL,"
                    "decision_source='manual',matcher_version=excluded.matcher_version,"
                    "attempt_id=excluded.attempt_id,"
                    "selected_by_user_id=excluded.selected_by_user_id,"
                    "selected_at=excluded.selected_at,row_revision=row_revision+1",
                    (
                        snapshot["local_album_id"],
                        evidence.release_group_mbid,
                        evidence.matcher_version,
                        attempt_id,
                        actor_user_id,
                        now,
                    ),
                )
                for row in current_tracks:
                    recording_mbid = supported_recordings.get(str(row["id"])) or (
                        str(row["recording_mbid"]) if row["recording_mbid"] else None
                    )
                    if recording_mbid is None:
                        connection.execute(
                            "DELETE FROM local_track_external_identities "
                            "WHERE local_track_id=? AND provider='musicbrainz'",
                            (row["id"],),
                        )
                        continue
                    connection.execute(
                        "INSERT INTO local_track_external_identities "
                        "(local_track_id,provider,recording_mbid,release_mbid,"
                        "release_track_mbid,medium_position,release_track_position,"
                        "decision_source,attempt_id,selected_at) "
                        "VALUES (?,'musicbrainz',?,NULL,NULL,NULL,NULL,'manual',?,?) "
                        "ON CONFLICT(local_track_id,provider) DO UPDATE SET "
                        "recording_mbid=excluded.recording_mbid,release_mbid=NULL,"
                        "release_track_mbid=NULL,medium_position=NULL,"
                        "release_track_position=NULL,decision_source='manual',"
                        "attempt_id=excluded.attempt_id,selected_at=excluded.selected_at,"
                        "row_revision=row_revision+1",
                        (row["id"], recording_mbid, attempt_id, now),
                    )
                post_album_identity = connection.execute(
                    "SELECT row_revision FROM local_album_external_identities "
                    "WHERE local_album_id=? AND provider='musicbrainz'",
                    (snapshot["local_album_id"],),
                ).fetchone()
                post_track_identities = {
                    str(row["local_track_id"]): row
                    for row in connection.execute(
                        "SELECT local_track_id,recording_mbid,row_revision FROM "
                        "local_track_external_identities WHERE provider='musicbrainz' "
                        "AND local_track_id IN (SELECT id FROM local_tracks "
                        "WHERE local_album_id=? AND availability='indexed')",
                        (snapshot["local_album_id"],),
                    ).fetchall()
                }
                ordered_tracks = sorted(
                    current_tracks,
                    key=lambda row: (
                        int(row["disc_number"]),
                        int(row["track_number"]),
                        str(row["id"]),
                    ),
                )
                manifest_payload = {
                    "local_album_id": str(snapshot["local_album_id"]),
                    "release_group_mbid": evidence.release_group_mbid,
                    "album_title": str(album_context["title"]),
                    "album_artist_name": str(album_context["album_artist_name"]),
                    "album_metadata": {
                        "album_artist_sort_name": album["album_artist_sort_name"],
                        "year": album["year"],
                        "original_release_date": album["original_release_date"],
                        "primary_genre": album["primary_genre"],
                        "is_compilation": bool(album["is_compilation"]),
                    },
                    "album_revision": int(album["row_revision"]),
                    "album_identity_revision": int(post_album_identity["row_revision"]),
                    "input_revision": str(snapshot["expected_input_revision"]),
                    "tracks": [
                        {
                            "local_track_id": str(row["id"]),
                            "track_revision": int(row["row_revision"]),
                            "identity_revision": (
                                int(
                                    post_track_identities[str(row["id"])][
                                        "row_revision"
                                    ]
                                )
                                if str(row["id"]) in post_track_identities
                                else None
                            ),
                            "stat_revision": str(row["stat_revision"]),
                            "tag_revision": str(row["tag_revision"]),
                            "title": str(row["title"]),
                            "artist_name": str(row["artist_name"] or ""),
                            "album_title": str(row["album_title"]),
                            "album_artist_name": str(
                                album_context["album_artist_name"]
                            ),
                            "metadata": {
                                "album_artist_name": row["album_artist_name"],
                                "year": row["year"],
                                "genre": row["genre"],
                                "title_sort": row["title_sort"],
                                "artist_sort": row["artist_sort"],
                                "album_sort": row["album_sort"],
                                "album_artist_sort": row["album_artist_sort"],
                                "disc_subtitle": row["disc_subtitle"],
                                "is_compilation": bool(row["is_compilation"]),
                            },
                            "disc_number": int(row["disc_number"]),
                            "track_number": int(row["track_number"]),
                            "recording_mbid": (
                                str(
                                    post_track_identities[str(row["id"])][
                                        "recording_mbid"
                                    ]
                                )
                                if str(row["id"]) in post_track_identities
                                else None
                            ),
                            "artist_mbid": (
                                str(row["embedded_artist_mbid"])
                                if row["embedded_artist_mbid"]
                                else None
                            ),
                            "album_artist_mbid": (
                                str(album_context["artist_mbid"])
                                if album_context["artist_mbid"]
                                else None
                            ),
                            "file_format": str(row["file_format"] or ""),
                            "duration_seconds": (
                                float(row["duration_seconds"])
                                if row["duration_seconds"] is not None
                                else None
                            ),
                        }
                        for row in ordered_tracks
                    ],
                }
                version = int(
                    connection.execute(
                        "SELECT COALESCE(MAX(version),0)+1 FROM "
                        "library_custom_edition_manifests WHERE local_album_id=?",
                        (snapshot["local_album_id"],),
                    ).fetchone()[0]
                )
                manifest_payload["manifest_version"] = version
                content_json = json.dumps(
                    manifest_payload,
                    ensure_ascii=True,
                    separators=(",", ":"),
                    sort_keys=True,
                )
                content_hash = hashlib.sha256(content_json.encode()).hexdigest()
                manifest_id = str(uuid.uuid4())
                try:
                    connection.execute(
                        "INSERT INTO library_custom_edition_manifests "
                        "(id,local_album_id,version,release_group_mbid,album_title,"
                        "album_artist_name,artist_mbid,album_metadata_json,"
                        "source_album_revision,source_identity_revision,input_revision,content_hash,"
                        "selected_candidate_key,sealed_by_user_id,sealed_at) "
                        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        (
                            manifest_id,
                            snapshot["local_album_id"],
                            version,
                            evidence.release_group_mbid,
                            album_context["title"],
                            album_context["album_artist_name"],
                            album_context["artist_mbid"],
                            json.dumps(
                                manifest_payload["album_metadata"],
                                separators=(",", ":"),
                                sort_keys=True,
                            ),
                            album["row_revision"],
                            post_album_identity["row_revision"],
                            snapshot["expected_input_revision"],
                            content_hash,
                            candidate_key,
                            actor_user_id,
                            now,
                        ),
                    )
                    for ordinal, track in enumerate(manifest_payload["tracks"]):
                        connection.execute(
                            "INSERT INTO library_custom_edition_tracks "
                            "(manifest_id,ordinal,local_track_id,source_track_revision,"
                            "source_identity_revision,stat_revision,tag_revision,title,"
                            "artist_name,album_title,album_artist_name,disc_number,"
                            "track_number,recording_mbid,artist_mbid,album_artist_mbid,"
                            "metadata_json,file_format,duration_seconds) "
                            "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                            (
                                manifest_id,
                                ordinal,
                                track["local_track_id"],
                                track["track_revision"],
                                track["identity_revision"],
                                track["stat_revision"],
                                track["tag_revision"],
                                track["title"],
                                track["artist_name"],
                                track["album_title"],
                                track["album_artist_name"],
                                track["disc_number"],
                                track["track_number"],
                                track["recording_mbid"],
                                track["artist_mbid"],
                                track["album_artist_mbid"],
                                json.dumps(
                                    track["metadata"],
                                    separators=(",", ":"),
                                    sort_keys=True,
                                ),
                                track["file_format"],
                                track["duration_seconds"],
                            ),
                        )
                except sqlite3.IntegrityError as error:
                    raise CustomEditionNotSealableError(
                        "The Custom edition changed while its manifest was being sealed."
                    ) from error
                connection.execute(
                    "INSERT INTO library_custom_edition_active "
                    "(local_album_id,manifest_id,activated_at,row_revision) "
                    "VALUES (?,?,?,1) ON CONFLICT(local_album_id) DO UPDATE SET "
                    "manifest_id=excluded.manifest_id,activated_at=excluded.activated_at,"
                    "row_revision=row_revision+1",
                    (snapshot["local_album_id"], manifest_id, now),
                )
                connection.execute(
                    "DELETE FROM library_management_exclusions WHERE local_album_id=?",
                    (snapshot["local_album_id"],),
                )
                connection.execute(
                    "UPDATE library_identification_reviews SET state='resolved',"
                    "reason_code='CUSTOM_EDITION_SEALED',decided_by_user_id=?,decided_at=?,"
                    "updated_at=?,decision_revision=decision_revision+1,"
                    "row_revision=row_revision+1 WHERE local_album_id=? "
                    "AND state!='resolved'",
                    (actor_user_id, now, now, snapshot["local_album_id"]),
                )
                result.update(
                    {
                        "selected_candidate_key": candidate_key,
                        "outcome": "custom_edition",
                        "custom_manifest_id": manifest_id,
                        "custom_manifest_version": version,
                        "recognized_track_count": sum(
                            1
                            for track in manifest_payload["tracks"]
                            if track["recording_mbid"]
                        ),
                    }
                )
                return self._finish_reidentification_management_decision_tx(
                    connection,
                    job=job,
                    snapshot=snapshot,
                    job_id=job_id,
                    expected_job_revision=expected_job_revision,
                    actor_user_id=actor_user_id,
                    result=result,
                    selected_candidate_key=candidate_key,
                    terminal_code="CUSTOM_EDITION_SEALED",
                    reason_code="CUSTOM_EDITION_SEALED",
                    before=(
                        dict(current_album_identity)
                        if current_album_identity is not None
                        else {}
                    ),
                    now=now,
                )
            if (
                evidence.reason_code not in AUTOMATIC_SAFE_EVIDENCE_REASONS
                or snapshot["requested_release_mbid"] is not None
            ) and not confirmation:
                raise ValidationError(
                    "Confirm the conflicting candidate evidence before applying it."
                )
            selected_tracks = _complete_track_identity_mapping(
                list(current_tracks), evidence
            )
            if selected_tracks is None:
                raise ExactReleaseMappingIncompleteError(
                    "This exact MusicBrainz edition does not map every local file uniquely. Choose Custom edition, acquire the missing tracks, or leave the album unmanaged."
                )
            connection.execute(
                "INSERT INTO local_album_external_identities "
                "(local_album_id, provider, release_group_mbid, release_mbid, decision_source, "
                "matcher_version, attempt_id, selected_by_user_id, selected_at) "
                "VALUES (?, 'musicbrainz', ?, ?, 'manual', ?, ?, ?, ?) "
                "ON CONFLICT(local_album_id, provider) DO UPDATE SET "
                "release_group_mbid = excluded.release_group_mbid, release_mbid = excluded.release_mbid, "
                "decision_source = 'manual', matcher_version = excluded.matcher_version, "
                "attempt_id = excluded.attempt_id, selected_by_user_id = excluded.selected_by_user_id, "
                "selected_at = excluded.selected_at, row_revision = row_revision + 1",
                (
                    snapshot["local_album_id"],
                    evidence.release_group_mbid,
                    evidence.release_mbid,
                    evidence.matcher_version,
                    attempt_id,
                    actor_user_id,
                    now,
                ),
            )
            connection.execute(
                "DELETE FROM local_track_external_identities WHERE local_track_id IN "
                "(SELECT id FROM local_tracks WHERE local_album_id = ? "
                "AND availability = 'indexed')",
                (snapshot["local_album_id"],),
            )
            for track in selected_tracks:
                connection.execute(
                    "INSERT INTO local_track_external_identities "
                    "(local_track_id, provider, recording_mbid, release_mbid, "
                    "release_track_mbid, medium_position, release_track_position, "
                    "decision_source, attempt_id, selected_at) "
                    "VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, 'manual', ?, ?)",
                    (
                        track.local_track_id,
                        track.recording_mbid,
                        evidence.release_mbid,
                        track.release_track_mbid,
                        track.candidate_disc_number,
                        track.candidate_track_position,
                        attempt_id,
                        now,
                    ),
                )
            connection.execute(
                "DELETE FROM library_custom_edition_active WHERE local_album_id=?",
                (snapshot["local_album_id"],),
            )
            connection.execute(
                "DELETE FROM library_management_exclusions WHERE local_album_id=?",
                (snapshot["local_album_id"],),
            )
            connection.execute(
                "UPDATE library_identification_reviews SET state = 'resolved', "
                "reason_code = 'EXPLICIT_CANDIDATE_ACCEPTED', decided_by_user_id = ?, "
                "decided_at = ?, updated_at = ?, decision_revision = decision_revision + 1, "
                "row_revision = row_revision + 1 WHERE local_album_id = ? AND state != 'resolved'",
                (actor_user_id, now, now, snapshot["local_album_id"]),
            )
            result.update(
                {"selected_candidate_key": candidate_key, "outcome": "identified"}
            )
            connection.execute(
                "UPDATE library_reidentification_snapshots SET selected_candidate_key = ?, "
                "result_json = ? WHERE job_id = ?",
                (candidate_key, json.dumps(result, sort_keys=True), job_id),
            )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = 'succeeded', terminal_code = 'IDENTIFIED', "
                "terminal_at = ?, updated_at = ?, row_revision = row_revision + 1, "
                "event_revision = event_revision + 1 WHERE id = ? AND state = 'ready' "
                "AND row_revision = ? RETURNING *",
                (now, now, job_id, expected_job_revision),
            ).fetchone()
            connection.execute(
                "INSERT INTO library_catalog_actions "
                "(id, actor_user_id, action_kind, local_album_id, operation_job_id, "
                "before_json, after_json, reason_code, created_at) VALUES (?,?,?,?,?,?,?,?,?)",
                (
                    str(uuid.uuid4()),
                    actor_user_id,
                    "explicit_reidentification",
                    snapshot["local_album_id"],
                    job_id,
                    json.dumps({}),
                    json.dumps(result, sort_keys=True),
                    "EXPLICIT_CANDIDATE_ACCEPTED",
                    now,
                ),
            )
            self._bump_catalog(connection)
            self._bump_stream(connection, "operation")
            return dict(updated)

        return await self._write(operation)

    @classmethod
    def _finish_reidentification_management_decision_tx(
        cls,
        connection: sqlite3.Connection,
        *,
        job: sqlite3.Row,
        snapshot: sqlite3.Row,
        job_id: str,
        expected_job_revision: int,
        actor_user_id: str,
        result: dict[str, Any],
        selected_candidate_key: str | None,
        terminal_code: str,
        reason_code: str,
        before: dict[str, Any],
        now: float,
    ) -> dict[str, Any]:
        del job
        connection.execute(
            "UPDATE library_reidentification_snapshots SET "
            "selected_candidate_key=?,result_json=? WHERE job_id=?",
            (
                selected_candidate_key,
                json.dumps(result, separators=(",", ":"), sort_keys=True),
                job_id,
            ),
        )
        updated = connection.execute(
            "UPDATE library_operation_jobs SET state='succeeded',terminal_code=?,"
            "terminal_at=?,updated_at=?,row_revision=row_revision+1,"
            "event_revision=event_revision+1 WHERE id=? AND state IN ('ready','succeeded') "
            "AND row_revision=? RETURNING *",
            (terminal_code, now, now, job_id, expected_job_revision),
        ).fetchone()
        if updated is None:
            raise StaleRevisionError(
                "The re-identification candidates changed before selection."
            )
        connection.execute(
            "INSERT INTO library_catalog_actions "
            "(id,actor_user_id,action_kind,local_album_id,operation_job_id,"
            "before_json,after_json,reason_code,created_at) "
            "VALUES (?,?,?,?,?,?,?,?,?)",
            (
                str(uuid.uuid4()),
                actor_user_id,
                "explicit_reidentification",
                snapshot["local_album_id"],
                job_id,
                json.dumps(before, separators=(",", ":"), sort_keys=True),
                json.dumps(result, separators=(",", ":"), sort_keys=True),
                reason_code,
                now,
            ),
        )
        cls._bump_catalog(connection)
        cls._bump_stream(connection, "operation")
        return dict(updated)

    async def request_operation_control(
        self,
        job_id: str,
        *,
        control: str,
        expected_row_revision: int,
        idempotency_key: str | None = None,
        now: float,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            assignment_parameters: tuple[Any, ...] = ()
            row = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id = ?", (job_id,)
            ).fetchone()
            if row is None:
                raise ResourceNotFoundError("Library operation not found.")
            if idempotency_key is not None:
                if not idempotency_key.strip():
                    raise ValidationError("A control idempotency key cannot be empty.")
                prior = connection.execute(
                    "SELECT job_id,control FROM "
                    "library_operation_control_idempotency WHERE idempotency_key=?",
                    (idempotency_key,),
                ).fetchone()
                if prior is not None:
                    if (
                        str(prior["job_id"]) != job_id
                        or str(prior["control"]) != control
                    ):
                        raise ConflictError(
                            "The control idempotency key belongs to another request."
                        )
                    return dict(row)
            if int(row["row_revision"]) != expected_row_revision:
                raise StaleRevisionError(
                    "The operation changed before the control request."
                )
            if control == "resume":
                if row["state"] not in {"paused", "stopped", "failed"}:
                    if idempotency_key is not None:
                        connection.execute(
                            "INSERT INTO library_operation_control_idempotency "
                            "(idempotency_key,job_id,control,requested_at) "
                            "VALUES (?,?,?,?)",
                            (idempotency_key, job_id, control, now),
                        )
                    return dict(row)
                if row["state"] == "failed" and row["terminal_code"] not in {
                    "PROVIDER_TEMPORARILY_UNAVAILABLE"
                }:
                    if idempotency_key is not None:
                        connection.execute(
                            "INSERT INTO library_operation_control_idempotency "
                            "(idempotency_key,job_id,control,requested_at) "
                            "VALUES (?,?,?,?)",
                            (idempotency_key, job_id, control, now),
                        )
                    return dict(row)
                restart_explicit = (
                    row["kind"] == "explicit_reidentification"
                    and row["state"] == "stopped"
                )
                if restart_explicit:
                    connection.execute(
                        "UPDATE library_operation_work SET state = 'pending', "
                        "failure_code = NULL, result_json = NULL, updated_at = ?, "
                        "row_revision = row_revision + 1 WHERE job_id = ?",
                        (now, job_id),
                    )
                    connection.execute(
                        "UPDATE library_reidentification_snapshots SET result_json = NULL, "
                        "selected_candidate_key = NULL WHERE job_id = ?",
                        (job_id,),
                    )
                elif row["state"] == "failed":
                    connection.execute(
                        "UPDATE library_operation_work SET state = 'pending', "
                        "failure_code = NULL, result_json = NULL, updated_at = ?, "
                        "row_revision = row_revision + 1 WHERE job_id = ? "
                        "AND state IN ('failed','running')",
                        (now, job_id),
                    )
                if restart_explicit:
                    assignments = (
                        "state = 'queued', control_request = 'none', terminal_code = NULL, "
                        "terminal_at = NULL, completed_count = 0, succeeded_count = 0, "
                        "failed_count = 0, skipped_count = 0"
                    )
                else:
                    assignments = (
                        "state = 'queued', control_request = 'none', terminal_code = NULL, "
                        "terminal_at = NULL, completed_count = CASE WHEN state = 'failed' "
                        "THEN 0 ELSE completed_count END, failed_count = CASE WHEN state = 'failed' "
                        "THEN 0 ELSE failed_count END"
                    )
            elif control in {"pause", "stop"}:
                if row["state"] in {"succeeded", "cancelled", "stopped"}:
                    if idempotency_key is not None:
                        connection.execute(
                            "INSERT INTO library_operation_control_idempotency "
                            "(idempotency_key,job_id,control,requested_at) "
                            "VALUES (?,?,?,?)",
                            (idempotency_key, job_id, control, now),
                        )
                    return dict(row)
                stale_planning_preview = False
                explicit_ready = (
                    control == "stop"
                    and row["kind"] == "explicit_reidentification"
                    and row["state"] == "ready"
                )
                if (
                    control == "stop"
                    and row["kind"] == "library_management"
                    and row["state"] == "running"
                    and (
                        row["lease_expires_at"] is None
                        or float(row["lease_expires_at"]) <= now
                    )
                ):
                    snapshot = connection.execute(
                        "SELECT mode, phase FROM library_management_job_snapshots "
                        "WHERE job_id = ?",
                        (job_id,),
                    ).fetchone()
                    stale_planning_preview = bool(
                        snapshot is not None
                        and str(snapshot["mode"]) == "preview"
                        and str(snapshot["phase"]) == "planning"
                    )
                if control == "stop" and (
                    row["state"] in {"queued", "paused"}
                    or stale_planning_preview
                    or explicit_ready
                ):
                    assignments = (
                        "state = 'stopped', control_request = 'none', "
                        "terminal_code = ?, terminal_at = ?, lease_owner = NULL, "
                        "lease_expires_at = NULL, heartbeat_at = NULL"
                    )
                    assignment_parameters = (
                        "STOPPED_EXPIRED_LEASE"
                        if stale_planning_preview
                        else "STOPPED",
                        now,
                    )
                else:
                    assignments = f"control_request = '{control}'"
            else:
                raise ValueError(f"Unsupported operation control: {control}")
            if idempotency_key is not None:
                connection.execute(
                    "INSERT INTO library_operation_control_idempotency "
                    "(idempotency_key,job_id,control,requested_at) VALUES (?,?,?,?)",
                    (idempotency_key, job_id, control, now),
                )
            updated = connection.execute(
                f"UPDATE library_operation_jobs SET {assignments}, updated_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND row_revision = ? AND row_revision < ? AND event_revision < ? "
                "RETURNING *",
                (
                    *assignment_parameters,
                    now,
                    job_id,
                    expected_row_revision,
                    MAX_REVISION,
                    MAX_REVISION,
                ),
            ).fetchone()
            if updated is None:
                raise StaleRevisionError(
                    "The operation changed before the control request."
                )
            self._bump_stream(connection, "operation")
            return dict(updated)

        result = await self._write(operation)
        if control == "resume" and result["state"] == "queued":
            self.work_wakeups.notify("operation")
        return result

    async def probe_operation_control(self, job_id: str, worker_id: str) -> bool:
        """Read-only per-unit control check (no write lock, no transaction).

        (GH-293) Workers check control at pass cadence with a real transition,
        and probe this cheap read between units so a pause/stop issued mid-pass
        is honored within one unit instead of writing a control transaction per
        subject.
        """

        def operation(connection: sqlite3.Connection) -> bool:
            row = connection.execute(
                "SELECT control_request FROM library_operation_jobs "
                "WHERE id = ? AND state = 'running' AND lease_owner = ?",
                (job_id, worker_id),
            ).fetchone()
            return row is not None and str(row["control_request"]) != "none"

        return await self._read(operation)

    async def checkpoint_operation_control(
        self, job_id: str, worker_id: str, *, now: float
    ) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            row = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id = ? AND state = 'running' "
                "AND lease_owner = ?",
                (job_id, worker_id),
            ).fetchone()
            if row is None or row["control_request"] == "none":
                return _row(row)
            state = "paused" if row["control_request"] == "pause" else "stopped"
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = ?, control_request = 'none', "
                "terminal_code = COALESCE(terminal_code, ?), lease_owner = NULL, "
                "lease_expires_at = NULL, heartbeat_at = NULL, "
                "updated_at = ?, terminal_at = CASE WHEN ? = 'stopped' THEN ? ELSE terminal_at END, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND state = 'running' AND lease_owner = ? RETURNING *",
                (state, state.upper(), now, state, now, job_id, worker_id),
            ).fetchone()
            connection.execute(
                "UPDATE library_operation_work SET state = 'pending', row_revision = row_revision + 1, "
                "updated_at = ? WHERE job_id = ? AND state = 'running'",
                (now, job_id),
            )
            self._bump_stream(connection, "operation")
            return dict(updated)

        return await self._write_background(operation)

    async def finish_operation_job(
        self, job_id: str, worker_id: str, *, state: str, terminal_code: str, now: float
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = ?, terminal_code = ?, terminal_at = ?, "
                "updated_at = ?, lease_owner = NULL, lease_expires_at = NULL, heartbeat_at = NULL, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND state = 'running' AND lease_owner = ? RETURNING *",
                (state, terminal_code, now, now, job_id, worker_id),
            ).fetchone()
            if updated is None:
                raise StaleRevisionError(
                    "The operation lease changed before completion."
                )
            self._bump_stream(connection, "operation")
            return dict(updated)

        return await self._write(operation)

    async def finish_library_management_apply(
        self, job_id: str, worker_id: str, *, now: float
    ) -> dict[str, Any]:
        """Finish apply only after every materialized bundle is terminal."""

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            active = connection.execute(
                "SELECT COUNT(*) FROM library_operation_work WHERE job_id=? "
                "AND state IN ('pending','running')",
                (job_id,),
            ).fetchone()[0]
            if int(active) != 0:
                raise StaleRevisionError(
                    "Library Management work remains before completion."
                )
            job = connection.execute(
                "SELECT failed_count,skipped_count FROM library_operation_jobs "
                "WHERE id=? AND kind='library_management' AND state='running' "
                "AND lease_owner=?",
                (job_id, worker_id),
            ).fetchone()
            if job is None:
                raise StaleRevisionError(
                    "The Library Management operation lease changed before completion."
                )
            terminal_code = (
                "COMPLETED_WITH_ERRORS"
                if int(job["failed_count"]) > 0
                else "COMPLETED_WITH_SKIPS"
                if int(job["skipped_count"]) > 0
                else "COMPLETED"
            )
            snapshot = connection.execute(
                "UPDATE library_management_job_snapshots SET phase='complete', "
                "updated_at=?,row_revision=row_revision+1 WHERE job_id=? "
                "AND (((mode='apply' OR mode='automatic_apply') AND phase='applying') "
                "OR (mode='undo' AND phase='undoing') "
                "OR (mode='baseline_restore' AND phase='restoring') "
                "OR (mode='duplicate_resolution' AND phase='applying')) "
                "AND row_revision < ? "
                "RETURNING job_id",
                (now, job_id, MAX_REVISION),
            ).fetchone()
            if snapshot is None:
                self._refuse_max_revision(
                    connection,
                    table="library_management_job_snapshots",
                    predicate="job_id = ?",
                    parameters=(job_id,),
                )
                raise StaleRevisionError(
                    "The Library Management snapshot changed before completion."
                )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state='succeeded',terminal_code=?, "
                "terminal_at=?,updated_at=?,lease_owner=NULL,lease_expires_at=NULL,"
                "heartbeat_at=NULL,row_revision=row_revision+1,event_revision=event_revision+1 "
                "WHERE id=? AND state='running' AND lease_owner=? "
                "AND row_revision < ? AND event_revision < ? RETURNING *",
                (
                    terminal_code,
                    now,
                    now,
                    job_id,
                    worker_id,
                    MAX_REVISION,
                    MAX_REVISION,
                ),
            ).fetchone()
            if updated is None:
                self._refuse_max_revision(
                    connection,
                    table="library_operation_jobs",
                    predicate="id = ?",
                    parameters=(job_id,),
                    include_event_revision=True,
                )
                raise StaleRevisionError(
                    "The Library Management operation lease changed before completion."
                )
            self._bump_stream(connection, "operation")
            return dict(updated)

        return await self._write(operation)

    async def get_operation_snapshot(self, job_id: str) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            job = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id = ?", (job_id,)
            ).fetchone()
            if job is None:
                return None
            table = {
                "bulk_review_apply": "library_bulk_review_snapshots",
                "repair": "library_repair_snapshots",
                "explicit_reidentification": "library_reidentification_snapshots",
                "library_management": "library_management_job_snapshots",
            }[str(job["kind"])]
            snapshot = connection.execute(
                f"SELECT * FROM {table} WHERE job_id = ?", (job_id,)
            ).fetchone()
            return {"job": dict(job), "snapshot": _row(snapshot)}

        return await self._read(operation)

    async def get_operation_job(self, job_id: str) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            return _row(
                connection.execute(
                    "SELECT * FROM library_operation_jobs WHERE id = ?", (job_id,)
                ).fetchone()
            )

        return await self._read(operation)

    async def list_operation_jobs(
        self,
        *,
        kind: str | None = None,
        limit: int = 50,
        before_created_at: float | None = None,
        before_id: str | None = None,
    ) -> list[dict[str, Any]]:
        def operation(connection: sqlite3.Connection) -> list[dict[str, Any]]:
            clauses = ["1 = 1"]
            parameters: list[Any] = []
            if kind is not None:
                clauses.append("kind = ?")
                parameters.append(kind)
            if before_created_at is not None and before_id is not None:
                clauses.append("(created_at < ? OR (created_at = ? AND id < ?))")
                parameters.extend((before_created_at, before_created_at, before_id))
            rows = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE "
                + " AND ".join(clauses)
                + " ORDER BY created_at DESC, id DESC LIMIT ?",
                (*parameters, min(max(limit, 1), 51)),
            ).fetchall()
            return [dict(row) for row in rows]

        return await self._read(operation)

    async def list_active_administrative_library_work(
        self, *, failed_after: float, limit: int = 20
    ) -> list[dict[str, Any]]:
        def operation(connection: sqlite3.Connection) -> list[dict[str, Any]]:
            rows = connection.execute(
                "SELECT job.*, management.mode AS management_mode, "
                "management.origin AS management_origin, "
                "management.phase AS management_phase, "
                "management.summary_json AS management_summary_json, "
                "json_extract(management.profile_snapshot_json, '$.profile.name') "
                "AS management_profile_name, "
                "json_extract(repair.scope_json, '$.purpose') AS repair_purpose, "
                "bulk.action AS bulk_action, reident.local_album_id, album.title album_title, "
                "COALESCE((SELECT json_group_array(state) FROM ("
                "SELECT DISTINCT journal.state state FROM library_file_mutation_journal journal "
                "WHERE journal.job_id=job.id ORDER BY journal.state)), '[]') journal_states_json "
                "FROM library_operation_jobs job "
                "LEFT JOIN library_management_job_snapshots management "
                "ON management.job_id=job.id "
                "LEFT JOIN library_repair_snapshots repair ON repair.job_id=job.id "
                "LEFT JOIN library_bulk_review_snapshots bulk ON bulk.job_id=job.id "
                "LEFT JOIN library_reidentification_snapshots reident ON reident.job_id=job.id "
                "LEFT JOIN local_albums album ON album.id=reident.local_album_id "
                "WHERE job.state IN ('queued','running','paused') OR "
                "(job.state='failed' AND job.terminal_at>=?) "
                "ORDER BY CASE job.state WHEN 'failed' THEN 0 WHEN 'running' THEN 1 "
                "WHEN 'paused' THEN 2 ELSE 3 END, job.updated_at DESC, job.id DESC LIMIT ?",
                (failed_after, min(max(limit, 1), 20)),
            ).fetchall()
            return [dict(row) for row in rows]

        return await self._read(operation)

    async def list_repair_operation_jobs(
        self,
        *,
        purpose: str,
        limit: int = 50,
        before_created_at: float | None = None,
        before_id: str | None = None,
    ) -> list[dict[str, Any]]:
        def operation(connection: sqlite3.Connection) -> list[dict[str, Any]]:
            clauses = [
                "j.kind = 'repair'",
                "COALESCE(json_extract(s.scope_json, '$.purpose'), "
                "'existing_matches') = ?",
            ]
            parameters: list[Any] = [purpose]
            if before_created_at is not None and before_id is not None:
                clauses.append("(j.created_at < ? OR (j.created_at = ? AND j.id < ?))")
                parameters.extend((before_created_at, before_created_at, before_id))
            rows = connection.execute(
                "SELECT j.* FROM library_operation_jobs j "
                "JOIN library_repair_snapshots s ON s.job_id = j.id WHERE "
                + " AND ".join(clauses)
                + " ORDER BY j.created_at DESC, j.id DESC LIMIT ?",
                (*parameters, min(max(limit, 1), 51)),
            ).fetchall()
            return [dict(row) for row in rows]

        return await self._read(operation)

    async def get_operation_by_idempotency_key(
        self, idempotency_key: str
    ) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            return _row(
                connection.execute(
                    "SELECT * FROM library_operation_jobs WHERE idempotency_key = ?",
                    (idempotency_key,),
                ).fetchone()
            )

        return await self._read(operation)

    async def list_operation_work_results(
        self, job_id: str, *, limit: int = 101
    ) -> list[dict[str, Any]]:
        def operation(connection: sqlite3.Connection) -> list[dict[str, Any]]:
            rows = connection.execute(
                "SELECT ordinal, local_album_id, local_track_id, action, state, "
                "failure_code, result_json FROM library_operation_work "
                "WHERE job_id = ? AND state IN ('succeeded','failed','skipped') "
                "ORDER BY ordinal LIMIT ?",
                (job_id, min(max(limit, 1), 101)),
            ).fetchall()
            return [dict(row) for row in rows]

        return await self._read(operation)

    async def claim_operation_job(
        self,
        worker_id: str,
        *,
        now: float,
        lease_seconds: float,
        kind: str | None = None,
    ) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            kind_clause = "AND kind = ?" if kind is not None else ""
            parameters: tuple[Any, ...] = (kind,) if kind is not None else ()
            candidate = connection.execute(
                "SELECT id, row_revision FROM library_operation_jobs "
                f"WHERE state = 'queued' {kind_clause} "
                "AND (next_attempt_at IS NULL OR next_attempt_at <= ?) "
                "ORDER BY updated_at, created_at, id LIMIT 1",
                (*parameters, now),
            ).fetchone()
            if candidate is None:
                return None
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = 'running', started_at = COALESCE(started_at, ?), "
                "lease_owner = ?, lease_expires_at = ?, heartbeat_at = ?, updated_at = ?, "
                "next_attempt_at = NULL, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND state = 'queued' AND row_revision = ? AND row_revision < ? "
                "AND event_revision < ? RETURNING *",
                (
                    now,
                    worker_id,
                    now + lease_seconds,
                    now,
                    now,
                    candidate["id"],
                    candidate["row_revision"],
                    MAX_REVISION,
                    MAX_REVISION,
                ),
            ).fetchone()
            if updated is None:
                self._refuse_max_revision(
                    connection,
                    table="library_operation_jobs",
                    predicate="id = ?",
                    parameters=(candidate["id"],),
                    include_event_revision=True,
                )
                return None
            self._bump_stream(connection, "operation")
            return dict(updated)

        return await self._write(operation)

    async def heartbeat_operation_job(
        self, job_id: str, worker_id: str, *, now: float, lease_seconds: float
    ) -> bool:
        def operation(connection: sqlite3.Connection) -> bool:
            cursor = connection.execute(
                "UPDATE library_operation_jobs SET heartbeat_at = ?, lease_expires_at = ?, "
                "updated_at = ? WHERE id = ? "
                "AND state = 'running' AND lease_owner = ?",
                (now, now + lease_seconds, now, job_id, worker_id),
            )
            return cursor.rowcount == 1

        return await self._write(operation)

    async def defer_explicit_operation_for_scan(
        self, job_id: str, worker_id: str, *, now: float
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            connection.execute(
                "UPDATE library_operation_work SET state = 'pending', updated_at = ?, "
                "row_revision = row_revision + 1 WHERE job_id = ? AND state = 'running'",
                (now, job_id),
            )
            deferred = connection.execute(
                "UPDATE library_operation_jobs SET state = 'queued', lease_owner = NULL, "
                "lease_expires_at = NULL, heartbeat_at = NULL, updated_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND kind = 'explicit_reidentification' AND state = 'running' "
                "AND lease_owner = ? RETURNING *",
                (now, job_id, worker_id),
            ).fetchone()
            if deferred is None:
                raise StaleRevisionError(
                    "The re-identification lease changed while it waited for the scan."
                )
            self._bump_stream(connection, "operation")
            return dict(deferred)

        return await self._write(operation)

    async def defer_library_management_preview_for_scan(
        self, job_id: str, worker_id: str, *, now: float
    ) -> dict[str, Any]:
        """Release a preview lease without discarding its durable staging cursor."""

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            snapshot = connection.execute(
                "SELECT phase FROM library_management_job_snapshots WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if snapshot is None or str(snapshot["phase"]) != "planning":
                raise StaleRevisionError(
                    "The management preview changed while it waited for the scan."
                )
            deferred = connection.execute(
                "UPDATE library_operation_jobs SET state = 'queued', lease_owner = NULL, "
                "lease_expires_at = NULL, heartbeat_at = NULL, updated_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND kind = 'library_management' AND state = 'running' "
                "AND lease_owner = ? RETURNING *",
                (now, job_id, worker_id),
            ).fetchone()
            if deferred is None:
                raise StaleRevisionError(
                    "The management preview lease changed while it waited for the scan."
                )
            self._bump_stream(connection, "operation")
            return dict(deferred)

        return await self._write(operation)

    async def recover_expired_operation_leases(self, *, now: float) -> int:
        def operation(connection: sqlite3.Connection) -> int:
            overflow = connection.execute(
                "SELECT 1 FROM library_operation_jobs WHERE state = 'running' "
                "AND lease_expires_at < ? AND (row_revision >= ? OR event_revision >= ?) LIMIT 1",
                (now, MAX_REVISION, MAX_REVISION),
            ).fetchone()
            work_overflow = connection.execute(
                "SELECT 1 FROM library_operation_work work JOIN "
                "library_operation_jobs job ON job.id=work.job_id "
                "WHERE work.state='running' AND work.row_revision>=? "
                "AND job.state='running' AND job.lease_expires_at<? LIMIT 1",
                (MAX_REVISION, now),
            ).fetchone()
            if overflow is not None or work_overflow is not None:
                raise RevisionOverflowError(
                    "An operation job revision reached its maximum value."
                )
            connection.execute(
                "UPDATE library_operation_work SET state='pending',updated_at=?,"
                "row_revision=row_revision+1 WHERE state='running' AND job_id IN "
                "(SELECT id FROM library_operation_jobs WHERE state='running' "
                "AND lease_expires_at < ?)",
                (now, now),
            )
            cursor = connection.execute(
                "UPDATE library_operation_jobs SET state = 'queued', lease_owner = NULL, "
                "lease_expires_at = NULL, heartbeat_at = NULL, updated_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE state = 'running' AND lease_expires_at < ? AND row_revision < ? "
                "AND event_revision < ?",
                (now, now, MAX_REVISION, MAX_REVISION),
            )
            superseded = self._coalesce_recovered_activation_previews(
                connection, now=now
            )
            if cursor.rowcount or superseded:
                self._bump_stream(connection, "operation")
            return cursor.rowcount + superseded

        return await self._write(operation)

    async def claim_operation_work(
        self, job_id: str, worker_id: str, *, now: float
    ) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            job = connection.execute(
                "SELECT id FROM library_operation_jobs WHERE id = ? AND state = 'running' "
                "AND lease_owner = ?",
                (job_id, worker_id),
            ).fetchone()
            if job is None:
                return None
            candidate = connection.execute(
                "SELECT ordinal, row_revision FROM library_operation_work "
                "WHERE job_id = ? AND state = 'pending' ORDER BY ordinal LIMIT 1",
                (job_id,),
            ).fetchone()
            if candidate is None:
                return None
            updated = connection.execute(
                "UPDATE library_operation_work SET state = 'running', updated_at = ?, "
                "row_revision = row_revision + 1 WHERE job_id = ? AND ordinal = ? "
                "AND state = 'pending' AND row_revision = ? AND row_revision < ? RETURNING *",
                (
                    now,
                    job_id,
                    candidate["ordinal"],
                    candidate["row_revision"],
                    MAX_REVISION,
                ),
            ).fetchone()
            if updated is not None:
                return dict(updated)
            self._refuse_max_revision(
                connection,
                table="library_operation_work",
                predicate="job_id = ? AND ordinal = ?",
                parameters=(job_id, candidate["ordinal"]),
            )
            return None

        return await self._write(operation)

    async def get_operation_work_item(
        self, job_id: str, ordinal: int
    ) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            return _row(
                connection.execute(
                    "SELECT * FROM library_operation_work WHERE job_id=? AND ordinal=?",
                    (job_id, ordinal),
                ).fetchone()
            )

        return await self._read(operation)

    async def complete_operation_work(
        self,
        job_id: str,
        ordinal: int,
        *,
        worker_id: str,
        expected_work_revision: int,
        state: str,
        result_json: str | None,
        failure_code: str | None,
        completed_at: float,
    ) -> tuple[int, int, int]:
        def operation(connection: sqlite3.Connection) -> tuple[int, int, int]:
            work_revision = connection.execute(
                "UPDATE library_operation_work SET state = ?, result_json = ?, failure_code = ?, "
                "updated_at = ?, row_revision = row_revision + 1 WHERE job_id = ? AND ordinal = ? "
                "AND state = 'running' AND row_revision = ? AND row_revision < ? "
                "RETURNING row_revision",
                (
                    state,
                    result_json,
                    failure_code,
                    completed_at,
                    job_id,
                    ordinal,
                    expected_work_revision,
                    MAX_REVISION,
                ),
            ).fetchone()
            if work_revision is None:
                self._refuse_max_revision(
                    connection,
                    table="library_operation_work",
                    predicate="job_id = ? AND ordinal = ?",
                    parameters=(job_id, ordinal),
                )
                raise StaleRevisionError(
                    "The operation subject changed before its result was recorded."
                )
            result_counter = {
                "succeeded": "succeeded_count",
                "failed": "failed_count",
                "skipped": "skipped_count",
            }.get(state)
            if result_counter is None:
                raise ValueError(f"Invalid terminal operation work state: {state}")
            job_revision = connection.execute(
                f"UPDATE library_operation_jobs SET completed_count = completed_count + 1, "
                f"{result_counter} = {result_counter} + 1, updated_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND state = 'running' AND lease_owner = ? "
                "AND row_revision < ? AND event_revision < ? RETURNING row_revision",
                (completed_at, job_id, worker_id, MAX_REVISION, MAX_REVISION),
            ).fetchone()
            if job_revision is None:
                self._refuse_max_revision(
                    connection,
                    table="library_operation_jobs",
                    predicate="id = ?",
                    parameters=(job_id,),
                    include_event_revision=True,
                )
                raise StaleRevisionError(
                    "The operation job changed before its counters were recorded."
                )
            stream_revision = self._bump_stream(connection, "operation")
            return (
                int(work_revision["row_revision"]),
                int(job_revision["row_revision"]),
                stream_revision,
            )

        return await self._write(operation)

    async def apply_bulk_review_work(
        self,
        job_id: str,
        ordinal: int,
        *,
        worker_id: str,
        expected_work_revision: int,
        actor_user_id: str,
        now: float,
    ) -> dict[str, Any]:
        """Apply one materialized review subject and counters atomically."""

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            work = connection.execute(
                "SELECT * FROM library_operation_work WHERE job_id = ? AND ordinal = ? "
                "AND state = 'running' AND row_revision = ?",
                (job_id, ordinal, expected_work_revision),
            ).fetchone()
            if work is None:
                raise StaleRevisionError(
                    "The bulk operation subject changed before Apply."
                )
            review = connection.execute(
                "SELECT * FROM library_identification_reviews WHERE "
                "((local_album_id = ? AND ? IS NOT NULL) OR (local_track_id = ? AND ? IS NOT NULL)) "
                "AND state != 'resolved' ORDER BY updated_at DESC LIMIT 1",
                (
                    work["local_album_id"],
                    work["local_album_id"],
                    work["local_track_id"],
                    work["local_track_id"],
                ),
            ).fetchone()
            terminal_state = "succeeded"
            failure_code = None
            result: dict[str, Any] = {}
            if (
                review is None
                or int(review["row_revision"]) != int(work["expected_subject_revision"])
                or str(review["input_revision"]) != str(work["expected_input_revision"])
            ):
                terminal_state = "skipped"
                failure_code = "STALE_SUBJECT"
            else:
                action = str(work["action"])
                album_id = work["local_album_id"]
                track_id = work["local_track_id"]
                if action == "keep_tagged":
                    identity = connection.execute(
                        "SELECT 1 FROM local_album_external_identities WHERE local_album_id = ?",
                        (album_id,),
                    ).fetchone()
                    if identity is not None:
                        terminal_state = "failed"
                        failure_code = "IDENTITY_REQUIRES_DETACH"
                    else:
                        connection.execute(
                            "UPDATE library_identification_reviews SET state = 'keep_tagged', "
                            "reason_code = 'BULK_KEEP_TAGGED', decided_by_user_id = ?, decided_at = ?, "
                            "updated_at = ?, decision_revision = decision_revision + 1, "
                            "row_revision = row_revision + 1 WHERE id = ?",
                            (actor_user_id, now, now, review["id"]),
                        )
                elif action == "exclude":
                    clause = "local_album_id = ?" if album_id is not None else "id = ?"
                    connection.execute(
                        "UPDATE local_tracks SET manual_excluded = 1, availability = 'excluded', "
                        f"excluded_at = ?, row_revision = row_revision + 1 WHERE {clause}",
                        (now, album_id or track_id),
                    )
                    connection.execute(
                        "UPDATE library_identification_reviews SET state = 'excluded', "
                        "reason_code = 'BULK_EXCLUDED', decided_by_user_id = ?, decided_at = ?, "
                        "updated_at = ?, decision_revision = decision_revision + 1, "
                        "row_revision = row_revision + 1 WHERE id = ?",
                        (actor_user_id, now, now, review["id"]),
                    )
                elif action == "retry":
                    if album_id is None:
                        terminal_state = "failed"
                        failure_code = "ALBUM_RETRY_REQUIRED"
                    else:
                        policies = {
                            str(row[0])
                            for row in connection.execute(
                                "SELECT DISTINCT applied_policy FROM local_tracks "
                                "WHERE local_album_id = ? AND availability = 'indexed'",
                                (album_id,),
                            )
                        }
                        if "excluded" in policies:
                            terminal_state = "failed"
                            failure_code = "EXCLUDED"
                        else:
                            album = connection.execute(
                                "SELECT row_revision FROM local_albums WHERE id = ? "
                                "AND retired_into_album_id IS NULL",
                                (album_id,),
                            ).fetchone()
                            tracks = connection.execute(
                                "SELECT id, tag_revision, stat_revision, "
                                "applied_policy_revision, applied_policy FROM local_tracks "
                                "WHERE local_album_id = ? AND availability = 'indexed' "
                                "ORDER BY id",
                                (album_id,),
                            ).fetchall()
                            if album is None or not tracks:
                                terminal_state = "skipped"
                                failure_code = "SUBJECT_NOT_AVAILABLE"
                            else:
                                retry_idempotency_key = (
                                    f"{work['idempotency_key']}:reidentification"
                                )
                                child = connection.execute(
                                    "SELECT id FROM library_operation_jobs "
                                    "WHERE idempotency_key = ?",
                                    (retry_idempotency_key,),
                                ).fetchone()
                                child_job_id = (
                                    str(child["id"])
                                    if child is not None
                                    else str(
                                        uuid.uuid5(
                                            uuid.NAMESPACE_URL,
                                            retry_idempotency_key,
                                        )
                                    )
                                )
                                input_revision = _album_input_revision(tracks)
                                album_identity, identity_tracks = (
                                    _identification_identity_rows(connection, album_id)
                                )
                                identity_revision = _album_identity_revision(
                                    album_identity, identity_tracks
                                )
                                if child is None:
                                    connection.execute(
                                        "INSERT INTO library_operation_jobs "
                                        "(id, kind, state, requested_by_user_id, "
                                        "expected_work_count, idempotency_key, created_at, updated_at) "
                                        "VALUES (?, 'explicit_reidentification', 'queued', ?, 1, ?, ?, ?)",
                                        (
                                            child_job_id,
                                            actor_user_id,
                                            retry_idempotency_key,
                                            now,
                                            now,
                                        ),
                                    )
                                    connection.execute(
                                        "INSERT INTO library_reidentification_snapshots "
                                        "(job_id, local_album_id, expected_album_revision, "
                                        "expected_input_revision, expected_identity_revision, "
                                        "one_off_local_metadata, created_at) VALUES (?,?,?,?,?,?,?)",
                                        (
                                            child_job_id,
                                            album_id,
                                            album["row_revision"],
                                            input_revision,
                                            identity_revision,
                                            int("local_metadata" in policies),
                                            now,
                                        ),
                                    )
                                    connection.execute(
                                        "INSERT INTO library_operation_work "
                                        "(job_id, ordinal, local_album_id, "
                                        "expected_subject_revision, expected_input_revision, "
                                        "action, idempotency_key, updated_at) "
                                        "VALUES (?,0,?,?,?,?,?,?)",
                                        (
                                            child_job_id,
                                            album_id,
                                            album["row_revision"],
                                            input_revision,
                                            "reidentify",
                                            f"{child_job_id}:{album_id}",
                                            now,
                                        ),
                                    )
                                connection.execute(
                                    "UPDATE library_identification_reviews "
                                    "SET state = 'resolved', reason_code = 'EXPLICIT_RETRY', "
                                    "decided_by_user_id = ?, decided_at = ?, updated_at = ?, "
                                    "decision_revision = decision_revision + 1, "
                                    "row_revision = row_revision + 1 WHERE id = ?",
                                    (actor_user_id, now, now, review["id"]),
                                )
                                result["operation_job_id"] = child_job_id
                elif action.startswith("accept_candidate:"):
                    candidate_key = action.partition(":")[2]
                    evidence = connection.execute(
                        "SELECT e.* FROM library_identification_evidence e "
                        "WHERE e.attempt_id = ? AND e.candidate_key = ?",
                        (review["attempt_id"], candidate_key),
                    ).fetchone()
                    if evidence is None:
                        terminal_state = "failed"
                        failure_code = "CANDIDATE_NOT_FOUND"
                    else:
                        parsed = msgspec.json.decode(
                            bytes(evidence["evidence_json"]), type=CandidateEvidence
                        )
                        if parsed.reason_code not in AUTOMATIC_SAFE_EVIDENCE_REASONS:
                            terminal_state = "failed"
                            failure_code = "CANDIDATE_NOT_AUTOMATIC_SAFE"
                        else:
                            connection.execute(
                                "INSERT INTO local_album_external_identities "
                                "(local_album_id, provider, release_group_mbid, release_mbid, "
                                "decision_source, matcher_version, attempt_id, selected_by_user_id, selected_at) "
                                "VALUES (?, 'musicbrainz', ?, ?, 'manual', ?, ?, ?, ?) "
                                "ON CONFLICT(local_album_id, provider) DO UPDATE SET "
                                "release_group_mbid = excluded.release_group_mbid, "
                                "release_mbid = excluded.release_mbid, decision_source = 'manual', "
                                "attempt_id = excluded.attempt_id, selected_by_user_id = excluded.selected_by_user_id, "
                                "selected_at = excluded.selected_at, row_revision = row_revision + 1",
                                (
                                    album_id,
                                    parsed.release_group_mbid,
                                    parsed.release_mbid,
                                    parsed.matcher_version,
                                    review["attempt_id"],
                                    actor_user_id,
                                    now,
                                ),
                            )
                            for track in parsed.track_evidence:
                                if (
                                    track.classification == "supported"
                                    and track.recording_mbid
                                ):
                                    connection.execute(
                                        "INSERT INTO local_track_external_identities "
                                        "(local_track_id, provider, recording_mbid, release_mbid, "
                                        "release_track_mbid, medium_position, release_track_position, "
                                        "decision_source, attempt_id, selected_at) "
                                        "VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, 'manual', ?, ?) "
                                        "ON CONFLICT(local_track_id, provider) DO UPDATE SET recording_mbid = excluded.recording_mbid, "
                                        "release_mbid = excluded.release_mbid, decision_source = 'manual', "
                                        "release_track_mbid = excluded.release_track_mbid, "
                                        "medium_position = excluded.medium_position, "
                                        "release_track_position = excluded.release_track_position, "
                                        "attempt_id = excluded.attempt_id, selected_at = excluded.selected_at, "
                                        "row_revision = row_revision + 1",
                                        (
                                            track.local_track_id,
                                            track.recording_mbid,
                                            parsed.release_mbid,
                                            track.release_track_mbid,
                                            track.candidate_disc_number,
                                            track.candidate_track_position,
                                            review["attempt_id"],
                                            now,
                                        ),
                                    )
                            connection.execute(
                                "UPDATE library_identification_reviews SET state = 'resolved', "
                                "reason_code = 'BULK_CANDIDATE_ACCEPTED', decided_by_user_id = ?, "
                                "decided_at = ?, updated_at = ?, decision_revision = decision_revision + 1, "
                                "row_revision = row_revision + 1 WHERE id = ?",
                                (actor_user_id, now, now, review["id"]),
                            )
                else:
                    terminal_state = "failed"
                    failure_code = "UNSUPPORTED_ACTION"
                if terminal_state == "succeeded":
                    connection.execute(
                        "UPDATE library_identification_jobs SET state = 'cancelled', "
                        "last_failure_code = 'ADMIN_DECISION', updated_at = ?, terminal_at = ?, "
                        "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                        "WHERE kind = 'automatic' AND state IN ('queued','paused') AND "
                        "((local_album_id = ? AND ? IS NOT NULL) OR (local_track_id = ? AND ? IS NOT NULL))",
                        (now, now, album_id, album_id, track_id, track_id),
                    )
                    connection.execute(
                        "INSERT INTO library_catalog_actions "
                        "(id, idempotency_key, actor_user_id, action_kind, local_album_id, "
                        "local_track_id, operation_job_id, before_json, after_json, reason_code, created_at) "
                        "VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                        (
                            str(uuid.uuid4()),
                            work["idempotency_key"],
                            actor_user_id,
                            action,
                            album_id,
                            track_id,
                            job_id,
                            json.dumps({"review_state": review["state"]}),
                            json.dumps({"review_state": action}),
                            "BULK_APPLY",
                            now,
                        ),
                    )
                    result["catalog_revision"] = self._bump_catalog(connection)
            encoded_result = json.dumps(result, sort_keys=True)
            connection.execute(
                "UPDATE library_operation_work SET state = ?, result_json = ?, failure_code = ?, "
                "updated_at = ?, row_revision = row_revision + 1 WHERE job_id = ? AND ordinal = ?",
                (terminal_state, encoded_result, failure_code, now, job_id, ordinal),
            )
            counter = {
                "succeeded": "succeeded_count",
                "failed": "failed_count",
                "skipped": "skipped_count",
            }[terminal_state]
            connection.execute(
                f"UPDATE library_operation_jobs SET completed_count = completed_count + 1, "
                f"{counter} = {counter} + 1, updated_at = ?, row_revision = row_revision + 1, "
                "event_revision = event_revision + 1 WHERE id = ? AND state = 'running' "
                "AND lease_owner = ?",
                (now, job_id, worker_id),
            )
            self._bump_stream(connection, "operation")
            return {"state": terminal_state, "failure_code": failure_code, **result}

        return await self._write(operation)

    async def add_repair_findings(
        self, job_id: str, findings: list[RepairFinding], *, updated_at: float
    ) -> None:
        def operation(connection: sqlite3.Connection) -> None:
            connection.executemany(
                "INSERT INTO library_identity_repair_findings "
                "(id, job_id, local_album_id, evidence_id, expected_album_revision, "
                "expected_identity_revision, finding_code, confidence, reason_code, "
                "apply_eligible, suggested_release_mbid, suggested_release_group_mbid, "
                "suggested_edition_json, created_at, updated_at) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                [
                    (
                        finding.id,
                        job_id,
                        finding.local_album_id,
                        finding.evidence_id,
                        finding.expected_album_revision,
                        finding.expected_identity_revision,
                        finding.finding_code,
                        finding.confidence,
                        finding.reason_code,
                        int(finding.apply_eligible),
                        finding.suggested_release_mbid,
                        finding.suggested_release_group_mbid,
                        finding.suggested_edition_json,
                        updated_at,
                        updated_at,
                    )
                    for finding in findings
                ],
            )

        await self._write(operation)

    async def get_latest_album_identification_evidence(
        self, local_album_id: str
    ) -> tuple[dict[str, Any], list[dict[str, Any]]] | None:
        """Latest attempt (any trigger) that still has uncompacted evidence."""

        def operation(
            connection: sqlite3.Connection,
        ) -> tuple[dict[str, Any], list[dict[str, Any]]] | None:
            attempt = connection.execute(
                "SELECT a.* FROM library_identification_attempts a "
                "WHERE a.local_album_id = ? AND EXISTS ("
                "SELECT 1 FROM library_identification_evidence e "
                "WHERE e.attempt_id = a.id AND e.compacted = 0) "
                "ORDER BY a.completed_at DESC, a.id DESC LIMIT 1",
                (local_album_id,),
            ).fetchone()
            if attempt is None:
                return None
            rows = connection.execute(
                "SELECT * FROM library_identification_evidence "
                "WHERE attempt_id = ? AND compacted = 0 ORDER BY candidate_key",
                (attempt["id"],),
            ).fetchall()
            return dict(attempt), [dict(row) for row in rows]

        return await self._read(operation)

    async def create_repair_operation(
        self,
        job: OperationJob,
        *,
        scope: dict[str, Any],
        source_matcher_version: str | None,
        target_matcher_version: str,
    ) -> dict[str, Any]:
        """Create a repair job header plus its strictly pinned materialization state.

        (GH-293) The header, snapshot, and materialization marker are created in
        one small foreground transaction. The catalog revision is captured from
        the store INSIDE this transaction and used for BOTH the job header
        (``input_catalog_revision``) and the materialization pin, so the subject
        set is fixed for the job's whole life: every materialization page
        enforces the pin and fails/stales the job BEFORE any live changed
        subject is inserted when the revision moved; an unsealed, zero-progress
        job is atomically REBASED onto the current revision by
        ``rebase_repair_operation`` (same static job, no fresh startup job).
        Work rows are materialized in keyset pages of at most 500 subjects per
        transaction by ``materialize_repair_operation_batch`` (background lock
        priority). ``expected_work_count`` starts as a pinned COUNT(*) estimate
        and is corrected to the exact staged count when materialization seals.
        """

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            if job.idempotency_key:
                existing = connection.execute(
                    "SELECT * FROM library_operation_jobs WHERE idempotency_key = ?",
                    (job.idempotency_key,),
                ).fetchone()
                if existing is not None:
                    return dict(existing)
            purpose = str(scope.get("purpose", "existing_matches"))
            from_sql, where_sql, parameters = self._repair_scope_sql(
                scope, purpose=purpose, source_matcher_version=source_matcher_version
            )
            # Strict pin: the catalog revision is captured INSIDE this creation
            # transaction and used for BOTH the job header and the materialization
            # row, so the subject set is fixed for the job's whole life.
            pinned_revision = int(
                connection.execute(
                    "SELECT value FROM library_catalog_revision WHERE singleton = 1"
                ).fetchone()[0]
            )
            estimated_count = int(
                connection.execute(
                    f"SELECT COUNT(*) {from_sql} {where_sql}", parameters
                ).fetchone()[0]
            )
            connection.execute(
                "INSERT INTO library_operation_jobs "
                "(id, kind, state, requested_by_user_id, input_catalog_revision, expected_work_count, "
                "idempotency_key, created_at, updated_at) VALUES (?, 'repair', 'queued', ?, ?, ?, ?, ?, ?)",
                (
                    job.id,
                    job.requested_by_user_id,
                    pinned_revision,
                    estimated_count,
                    job.idempotency_key,
                    job.created_at,
                    job.created_at,
                ),
            )
            connection.execute(
                "INSERT INTO library_repair_snapshots "
                "(job_id, scope_json, source_matcher_version, target_matcher_version, created_at) "
                "VALUES (?,?,?,?,?)",
                (
                    job.id,
                    json.dumps(scope, sort_keys=True),
                    source_matcher_version,
                    target_matcher_version,
                    job.created_at,
                ),
            )
            connection.execute(
                "INSERT INTO library_repair_materialization "
                "(job_id, pinned_catalog_revision, eligibility_version, purpose, "
                "staging_cursor, staged_ordinal, staged_count, sealed, created_at, updated_at) "
                "VALUES (?,?,?,?,NULL,-1,0,0,?,?)",
                (
                    job.id,
                    pinned_revision,
                    (
                        f"{purpose}:"
                        f"{source_matcher_version or ''}:"
                        f"{target_matcher_version}"
                    ),
                    purpose,
                    job.created_at,
                    job.created_at,
                ),
            )
            self._bump_stream(connection, "operation")
            return dict(
                connection.execute(
                    "SELECT * FROM library_operation_jobs WHERE id = ?", (job.id,)
                ).fetchone()
            )

        result = await self._write(operation)
        self.work_wakeups.notify("operation")
        return result

    def _repair_scope_sql(
        self,
        scope: dict[str, Any],
        *,
        purpose: str,
        source_matcher_version: str | None,
    ) -> tuple[str, str, list[Any]]:
        """Canonical eligibility predicate shared by count, pin, and pages."""
        parameters: list[Any] = []
        root_ids = [str(value) for value in scope.get("root_ids", [])]
        root_clause = ""
        if root_ids:
            root_clause = f"AND a.root_id IN ({','.join('?' for _ in root_ids)})"
            parameters.extend(root_ids)
        if purpose in {
            "artist_identity_reconciliation",
            "catalog_identity_hygiene",
        }:
            album_ids = [str(value) for value in scope.get("album_ids", [])]
            album_clause = ""
            if album_ids:
                album_clause = f"AND a.id IN ({','.join('?' for _ in album_ids)})"
                parameters.extend(album_ids)
            active_track_clause = (
                "AND EXISTS (SELECT 1 FROM local_tracks active_track "
                "WHERE active_track.local_album_id = a.id "
                "AND active_track.availability = 'indexed') "
                if purpose == "artist_identity_reconciliation"
                else ""
            )
            return (
                "FROM local_albums a LEFT JOIN local_album_external_identities i "
                "ON i.local_album_id = a.id AND i.provider = 'musicbrainz'",
                (
                    "WHERE a.retired_into_album_id IS NULL "
                    f"{active_track_clause}{root_clause} {album_clause}"
                ),
                parameters,
            )
        if purpose == "management_readiness":
            return (
                "FROM local_albums a LEFT JOIN local_album_external_identities i "
                "ON i.local_album_id = a.id AND i.provider = 'musicbrainz'",
                (
                    "WHERE a.retired_into_album_id IS NULL "
                    "AND EXISTS (SELECT 1 FROM local_tracks t WHERE t.local_album_id = a.id "
                    "AND t.availability = 'indexed') "
                    "AND NOT EXISTS (SELECT 1 FROM library_management_exclusions exclusion "
                    "WHERE exclusion.local_album_id=a.id) "
                    "AND NOT EXISTS (SELECT 1 FROM library_edition_conversion_jobs conversion "
                    "WHERE conversion.local_album_id=a.id AND conversion.state IN "
                    "('preflight','acquiring','ready','needs_recheck')) "
                    f"{root_clause}"
                ),
                parameters,
            )
        identity_clause = ""
        if source_matcher_version is not None:
            identity_clause = "AND i.matcher_version = ?"
            parameters.append(source_matcher_version)
        elif bool(scope.get("legacy_only", True)):
            identity_clause = "AND i.decision_source = 'legacy_import'"
        return (
            "FROM local_albums a "
            "JOIN local_album_external_identities i ON i.local_album_id = a.id",
            (
                "WHERE a.retired_into_album_id IS NULL "
                "AND EXISTS (SELECT 1 FROM local_tracks t "
                "WHERE t.local_album_id = a.id AND t.availability = 'indexed') "
                f"{root_clause} {identity_clause}"
            ),
            parameters,
        )

    def _repair_subject_select(
        self,
        connection: sqlite3.Connection,
        *,
        scope: dict[str, Any],
        purpose: str,
        source_matcher_version: str | None,
        after_id: str | None,
        limit: int,
    ) -> list[sqlite3.Row]:
        """Keyset page of eligible repair subjects ordered by album id.

        Shared by the creation-time COUNT(*) and by paged materialization so the
        eligibility predicate is identical for the whole job. Binds in fixed
        order (GH-293 review fix):
        root_ids -> album_ids -> identity matcher -> keyset -> limit. The page
        caller must hold the pinned catalog revision unchanged (strict pin).
        """
        from_sql, where_sql, parameters = self._repair_scope_sql(
            scope, purpose=purpose, source_matcher_version=source_matcher_version
        )
        keyset_clause = "AND a.id > ?" if after_id is not None else ""
        if after_id is not None:
            parameters.append(after_id)
        parameters.append(limit)
        sql = (
            f"SELECT a.id, a.row_revision, i.row_revision identity_revision, "
            f"i.decision_source, i.attempt_id, i.release_mbid "
            f"{from_sql} {where_sql} {keyset_clause} "
            f"ORDER BY a.id LIMIT ?"
        )
        return connection.execute(sql, parameters).fetchall()

    def _repair_materialization_backfill_tx(
        self,
        connection: sqlite3.Connection,
        job_id: str,
        *,
        now: float,
    ) -> bool:
        """Compatibility backfill for repair jobs created before GH-293.

        Old jobs carry their full work row set already (inline materialization)
        and no ``library_repair_materialization`` row. On first sight they are
        retro-sealed with the existing row count, idempotently, so queued /
        running / paused / ready / succeeded jobs keep their semantics across
        the upgrade. Returns True when a row was inserted.
        """
        existing = connection.execute(
            "SELECT 1 FROM library_repair_materialization WHERE job_id = ?",
            (job_id,),
        ).fetchone()
        if existing is not None:
            return False
        job = connection.execute(
            "SELECT input_catalog_revision FROM library_operation_jobs WHERE id = ?",
            (job_id,),
        ).fetchone()
        snapshot = connection.execute(
            "SELECT scope_json, source_matcher_version, target_matcher_version "
            "FROM library_repair_snapshots WHERE job_id = ?",
            (job_id,),
        ).fetchone()
        if job is None or snapshot is None:
            return False
        purpose = str(
            json.loads(str(snapshot["scope_json"])).get("purpose", "existing_matches")
        )
        count, max_ordinal = connection.execute(
            "SELECT COUNT(*), COALESCE(MAX(ordinal), -1) "
            "FROM library_operation_work WHERE job_id = ?",
            (job_id,),
        ).fetchone()
        connection.execute(
            "INSERT INTO library_repair_materialization "
            "(job_id, pinned_catalog_revision, eligibility_version, purpose, "
            "staging_cursor, staged_ordinal, staged_count, sealed, created_at, updated_at) "
            "VALUES (?,?,?,?,NULL,?,?,1,?,?) ON CONFLICT(job_id) DO NOTHING",
            (
                job_id,
                int(job["input_catalog_revision"] or 0),
                (
                    f"{purpose}:"
                    f"{snapshot['source_matcher_version'] or ''}:"
                    f"{snapshot['target_matcher_version']}"
                ),
                purpose,
                int(max_ordinal),
                int(count),
                now,
                now,
            ),
        )
        return True

    async def materialize_repair_operation_batch(
        self,
        job_id: str,
        worker_id: str,
        *,
        now: float,
        batch_size: int = MATERIALIZATION_PAGE_CAP,
    ) -> dict[str, Any]:
        """Materialize one keyset page of repair work rows atomically.

        (GH-293) At most ``batch_size`` subjects per transaction, in background
        lock priority, strictly pinned to the creation catalog revision. The
        page advances the durable cursor, staged ordinal and count, and seals
        materialization when the keyset is exhausted; a revision change before
        sealing raises ``StaleRevisionError`` inside the page transaction BEFORE
        any live changed subject is inserted. A crash before or after a page
        commit resumes from the cursor without omission, duplication, or false
        completion. Jobs created before this change (no materialization row,
        work already inline) are retro-sealed on first sight. Once sealed, the
        probe is a read and never opens a write transaction. The job must be
        running under this worker's lease.
        """
        limit = min(max(batch_size, 1), MATERIALIZATION_PAGE_CAP)

        async def sealed_probe() -> dict[str, Any] | None:
            def read(connection: sqlite3.Connection) -> dict[str, Any] | None:
                row = connection.execute(
                    "SELECT sealed, staged_count FROM library_repair_materialization "
                    "WHERE job_id = ?",
                    (job_id,),
                ).fetchone()
                if row is not None and int(row["sealed"]) == 1:
                    return {
                        "complete": True,
                        "materialized_count": int(row["staged_count"]),
                        "page_size": 0,
                    }
                return None

            return await self._read(read)

        sealed = await sealed_probe()
        if sealed is not None:
            # A sealed no-op must NOT open a write transaction (or acquire the
            # write lock) on the per-pass hot path (GH-293 review fix).
            return sealed

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            job = connection.execute(
                "SELECT id FROM library_operation_jobs WHERE id = ? AND state = 'running' "
                "AND lease_owner = ?",
                (job_id, worker_id),
            ).fetchone()
            if job is None:
                raise StaleRevisionError(
                    "The operation lease changed while its work was materialized."
                )
            materialization = connection.execute(
                "SELECT * FROM library_repair_materialization WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if materialization is None:
                self._repair_materialization_backfill_tx(connection, job_id, now=now)
                materialization = connection.execute(
                    "SELECT * FROM library_repair_materialization WHERE job_id = ?",
                    (job_id,),
                ).fetchone()
                if materialization is None:
                    raise ResourceNotFoundError(
                        "Repair materialization state not found."
                    )
            if int(materialization["sealed"]) == 1:
                return {
                    "complete": True,
                    "materialized_count": int(materialization["staged_count"]),
                    "page_size": 0,
                }
            # Strict pin (review fix): if the catalog revision moved since the
            # creation transaction, THIS page fails BEFORE inserting any live
            # changed subject. The job is stale and must be re-created or
            # versioned; no partial/changing set ever materializes.
            current_revision = int(
                connection.execute(
                    "SELECT value FROM library_catalog_revision WHERE singleton = 1"
                ).fetchone()[0]
            )
            if current_revision != int(materialization["pinned_catalog_revision"]):
                raise StaleRevisionError(
                    "The catalog revision changed after the repair worklist was "
                    "pinned; re-create the job at the new revision."
                )
            snapshot = connection.execute(
                "SELECT scope_json, source_matcher_version FROM library_repair_snapshots "
                "WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if snapshot is None:
                raise ResourceNotFoundError("Repair snapshot not found.")
            scope = json.loads(str(snapshot["scope_json"]))
            purpose = str(materialization["purpose"])
            rows = self._repair_subject_select(
                connection,
                scope=scope,
                purpose=purpose,
                source_matcher_version=snapshot["source_matcher_version"],
                after_id=materialization["staging_cursor"],
                limit=limit + 1,
            )
            page = rows[:limit]
            action = (
                "artist_identity_reconciliation"
                if purpose == "artist_identity_reconciliation"
                else "catalog_identity_hygiene"
                if purpose == "catalog_identity_hygiene"
                else "management_identity_audit"
                if purpose == "management_readiness"
                else "repair_audit"
            )
            connection.executemany(
                "INSERT OR IGNORE INTO library_operation_work "
                "(job_id, ordinal, local_album_id, expected_subject_revision, expected_input_revision, "
                "action, idempotency_key, updated_at) VALUES (?,?,?,?,?,?,?,?)",
                [
                    (
                        job_id,
                        int(materialization["staged_ordinal"]) + 1 + offset,
                        row["id"],
                        row["row_revision"],
                        (
                            f"{row['identity_revision'] or ''}:"
                            f"{row['decision_source'] or ''}:"
                            f"{row['attempt_id'] or ''}:"
                            f"{(row['release_mbid'] if 'release_mbid' in row.keys() else '') or ''}"
                        ),
                        action,
                        f"{job_id}:{row['id']}:audit",
                        now,
                    )
                    for offset, row in enumerate(page)
                ],
            )
            complete = len(rows) <= limit
            new_ordinal = (
                int(materialization["staged_ordinal"]) + len(page)
                if page
                else int(materialization["staged_ordinal"])
            )
            new_count = int(materialization["staged_count"]) + len(page)
            new_cursor = (
                str(page[-1]["id"]) if page else materialization["staging_cursor"]
            )
            connection.execute(
                "UPDATE library_repair_materialization SET staging_cursor = ?, "
                "staged_ordinal = ?, staged_count = ?, sealed = ?, updated_at = ? "
                "WHERE job_id = ?",
                (
                    new_cursor,
                    new_ordinal,
                    new_count,
                    int(complete),
                    now,
                    job_id,
                ),
            )
            if complete:
                # The sealed count is authoritative; make the display truthful.
                connection.execute(
                    "UPDATE library_operation_jobs SET expected_work_count = ?, "
                    "updated_at = ?, row_revision = row_revision + 1, "
                    "event_revision = event_revision + 1 WHERE id = ?",
                    (new_count, now, job_id),
                )
            self._bump_stream(connection, "operation")
            return {
                "complete": bool(complete),
                "materialized_count": new_count,
                "page_size": len(page),
            }

        return await self._write_background(operation)

    async def rebase_repair_operation(
        self,
        job_id: str,
        worker_id: str,
        *,
        now: float,
    ) -> dict[str, Any]:
        """Atomically rebase a pin-stale, unsealed repair job onto the current
        catalog revision (GH-293 review fix).

        Preconditions, verified in ONE transaction:
        - the job is running under this worker's lease,
        - materialization is UNSEALED,
        - ZERO completed work (no succeeded/failed/skipped rows, completed_count
          == 0).

        On success the SAME static-idempotency job is reused: only its staged
        work rows are deleted, the durable cursor/count/seal are reset, the job's
        ``input_catalog_revision`` AND the materialization pin are moved to the
        current in-store revision, ``expected_work_count`` is re-estimated, and
        the operation stream is bumped. The worker resumes on a later bounded
        pass (cooldown + timed wakeup), so a startup catalog change never
        strands a static-key backfill and never creates a fresh job.

        On failure of the preconditions (completed work exists, or the job is
        already sealed/terminal) the job FAILS CLOSED to a durable ``failed``
        state with terminal code ``PIN_STALE_WITH_PROGRESS`` instead of silently
        discarding evidence.
        """
        from infrastructure.persistence.gh293_calibration import (
            BACKGROUND_YIELD_COOLDOWN_SECONDS,
        )

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            job = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id = ? AND state = 'running' "
                "AND lease_owner = ?",
                (job_id, worker_id),
            ).fetchone()
            if job is None:
                raise StaleRevisionError(
                    "The operation lease changed while the pin was stale."
                )
            materialization = connection.execute(
                "SELECT * FROM library_repair_materialization WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if materialization is None:
                raise StaleRevisionError(
                    "Repair materialization state not found for rebase."
                )
            terminal_work = int(
                connection.execute(
                    "SELECT COUNT(*) FROM library_operation_work WHERE job_id = ? "
                    "AND state IN ('succeeded','failed','skipped')",
                    (job_id,),
                ).fetchone()[0]
            )
            if (
                int(materialization["sealed"]) == 1
                or terminal_work > 0
                or int(job["completed_count"]) > 0
            ):
                failed = connection.execute(
                    "UPDATE library_operation_jobs SET state = 'failed', "
                    "terminal_code = 'PIN_STALE_WITH_PROGRESS', terminal_at = ?, "
                    "updated_at = ?, lease_owner = NULL, lease_expires_at = NULL, "
                    "heartbeat_at = NULL, row_revision = row_revision + 1, "
                    "event_revision = event_revision + 1 "
                    "WHERE id = ? AND state = 'running' AND lease_owner = ? RETURNING *",
                    (now, now, job_id, worker_id),
                ).fetchone()
                self._bump_stream(connection, "operation")
                return {"rebased": False, "job": dict(failed)}

            snapshot = connection.execute(
                "SELECT scope_json, source_matcher_version FROM library_repair_snapshots "
                "WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            scope = json.loads(str(snapshot["scope_json"]))
            purpose = str(materialization["purpose"])
            from_sql, where_sql, parameters = self._repair_scope_sql(
                scope,
                purpose=purpose,
                source_matcher_version=snapshot["source_matcher_version"],
            )
            current_revision = int(
                connection.execute(
                    "SELECT value FROM library_catalog_revision WHERE singleton = 1"
                ).fetchone()[0]
            )
            estimated_count = int(
                connection.execute(
                    f"SELECT COUNT(*) {from_sql} {where_sql}", parameters
                ).fetchone()[0]
            )
            connection.execute(
                "DELETE FROM library_operation_work WHERE job_id = ?", (job_id,)
            )
            connection.execute(
                "UPDATE library_repair_materialization SET "
                "pinned_catalog_revision = ?, staging_cursor = NULL, "
                "staged_ordinal = -1, staged_count = 0, sealed = 0, updated_at = ? "
                "WHERE job_id = ?",
                (current_revision, now, job_id),
            )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET input_catalog_revision = ?, "
                "expected_work_count = ?, updated_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND state = 'running' AND lease_owner = ? RETURNING *",
                (current_revision, estimated_count, now, job_id, worker_id),
            ).fetchone()
            self._bump_stream(connection, "operation")
            return {"rebased": True, "job": dict(updated)}

        result = await self._write_background(operation)
        # Rebind the operation wakeup so a later bounded pass resumes promptly
        # (never an immediate self-wakeup into a rebase loop).
        self.work_wakeups.notify_after(
            "operation", max(0.1, BACKGROUND_YIELD_COOLDOWN_SECONDS)
        )
        return result

    async def get_repair_materialization_status(
        self, job_id: str
    ) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            return _row(
                connection.execute(
                    "SELECT * FROM library_repair_materialization WHERE job_id = ?",
                    (job_id,),
                ).fetchone()
            )

        return await self._read(operation)

    async def yield_operation_job(
        self,
        job_id: str,
        worker_id: str,
        *,
        now: float,
        reason_code: str,
        retry_not_before: float | None = None,
    ) -> dict[str, Any]:
        """Release a running operation back to 'queued' without losing progress.

        (GH-293) Used when a background timeslice expires, public bootstrap
        demand or WAL backpressure suspends background producers, or scan-active
        deferral is needed. Running work rows are reset to pending so the job
        resumes exactly at the interrupted unit; the durable cursor, sealed
        marker, and counters are untouched. A positive ``next_attempt_at``
        (default: the calibration cooldown) is persisted and a real timed
        wakeup is scheduled, so the yielding worker never wakes itself into an
        immediate re-claim hot loop.
        """

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            connection.execute(
                "UPDATE library_operation_work SET state = 'pending', failure_code = ?, "
                "updated_at = ?, row_revision = row_revision + 1 "
                "WHERE job_id = ? AND state = 'running'",
                (reason_code, now, job_id),
            )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = 'queued', lease_owner = NULL, "
                "lease_expires_at = NULL, heartbeat_at = NULL, updated_at = ?, "
                "next_attempt_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND kind = 'repair' AND state = 'running' "
                "AND lease_owner = ? RETURNING *",
                (now, next_attempt_at, job_id, worker_id),
            ).fetchone()
            if updated is None:
                raise StaleRevisionError(
                    "The operation lease changed while it yielded."
                )
            self._bump_stream(connection, "operation")
            return dict(updated)

        if retry_not_before is not None:
            next_attempt_at = retry_not_before
        else:
            next_attempt_at = now + BACKGROUND_YIELD_COOLDOWN_SECONDS
        result = await self._write_background(operation)
        if next_attempt_at is not None:
            self.work_wakeups.notify_after("operation", next_attempt_at - now)
        else:
            self.work_wakeups.notify("operation")
        return result

    async def finish_sealed_repair_operation_job(
        self,
        job_id: str,
        worker_id: str,
        *,
        state: str,
        terminal_code: str,
        now: float,
    ) -> dict[str, Any]:
        """Finish a repair job only after materialization is sealed and every
        materialized subject is terminal (GH-293). Jobs created before GH-293
        (inline work, no materialization row) are retro-sealed first."""

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            materialization = connection.execute(
                "SELECT sealed FROM library_repair_materialization WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if materialization is None:
                self._repair_materialization_backfill_tx(connection, job_id, now=now)
                materialization = connection.execute(
                    "SELECT sealed FROM library_repair_materialization WHERE job_id = ?",
                    (job_id,),
                ).fetchone()
            if materialization is None or int(materialization["sealed"]) != 1:
                raise StaleRevisionError("The repair worklist is not sealed yet.")
            active = connection.execute(
                "SELECT COUNT(*) FROM library_operation_work WHERE job_id = ? "
                "AND state IN ('pending','running')",
                (job_id,),
            ).fetchone()[0]
            if int(active) != 0:
                raise StaleRevisionError(
                    "The repair still has unfinished materialized subjects."
                )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = ?, terminal_code = ?, terminal_at = ?, "
                "updated_at = ?, lease_owner = NULL, lease_expires_at = NULL, heartbeat_at = NULL, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND state = 'running' AND lease_owner = ? RETURNING *",
                (state, terminal_code, now, now, job_id, worker_id),
            ).fetchone()
            if updated is None:
                raise StaleRevisionError(
                    "The operation lease changed before completion."
                )
            self._bump_stream(connection, "operation")
            return dict(updated)

        return await self._write_background(operation)

    async def estimate_management_identity_preparation(
        self, root_ids: list[str]
    ) -> dict[str, int]:
        def operation(connection: sqlite3.Connection) -> dict[str, int]:
            parameters: list[Any] = []
            root_clause = ""
            if root_ids:
                placeholders = ",".join("?" for _ in root_ids)
                root_clause = f"AND a.root_id IN ({placeholders})"
                parameters.extend(root_ids)
            rows = connection.execute(
                "SELECT a.id, a.row_revision album_revision, i.release_group_mbid, "
                "i.release_mbid, i.row_revision identity_revision, "
                "manifest.id custom_manifest_id,manifest.source_album_revision,"
                "manifest.source_identity_revision, "
                "COUNT(t.id) track_count, "
                "SUM(CASE WHEN ti.recording_mbid IS NOT NULL "
                "AND ti.release_track_mbid IS NOT NULL "
                "AND ti.release_mbid = i.release_mbid "
                "AND ti.medium_position IS NOT NULL "
                "AND ti.release_track_position IS NOT NULL THEN 1 ELSE 0 END) mapped_count, "
                "COUNT(DISTINCT CASE WHEN ti.recording_mbid IS NOT NULL "
                "AND ti.release_track_mbid IS NOT NULL "
                "AND ti.release_mbid = i.release_mbid "
                "AND ti.medium_position IS NOT NULL "
                "AND ti.release_track_position IS NOT NULL "
                "THEN ti.release_track_mbid END) mapped_release_track_count "
                ",SUM(CASE WHEN custom_track.local_track_id=t.id "
                "AND custom_track.source_track_revision=t.row_revision "
                "AND custom_track.stat_revision=t.stat_revision "
                "AND custom_track.tag_revision=COALESCE(t.tag_revision,'None') "
                "AND custom_track.disc_number=t.disc_number "
                "AND custom_track.track_number=t.track_number "
                "AND custom_track.title=t.title "
                "AND custom_track.artist_name=COALESCE(t.artist_name,'') "
                "AND custom_track.album_title=t.album_title "
                "AND ((custom_track.source_identity_revision IS NULL AND ti.row_revision IS NULL) "
                "OR custom_track.source_identity_revision=ti.row_revision) "
                "AND COALESCE(custom_track.recording_mbid,'')=COALESCE(ti.recording_mbid,'') "
                "THEN 1 ELSE 0 END) custom_current_count "
                "FROM local_albums a JOIN local_tracks t ON t.local_album_id = a.id "
                "AND t.availability = 'indexed' "
                "LEFT JOIN local_album_external_identities i ON i.local_album_id = a.id "
                "AND i.provider = 'musicbrainz' "
                "LEFT JOIN local_track_external_identities ti ON ti.local_track_id = t.id "
                "AND ti.provider = 'musicbrainz' "
                "LEFT JOIN library_custom_edition_active active ON active.local_album_id=a.id "
                "LEFT JOIN library_custom_edition_manifests manifest ON manifest.id=active.manifest_id "
                "LEFT JOIN library_custom_edition_tracks custom_track "
                "ON custom_track.manifest_id=manifest.id AND custom_track.local_track_id=t.id "
                "WHERE a.retired_into_album_id IS NULL "
                "AND NOT EXISTS (SELECT 1 FROM library_management_exclusions exclusion "
                "WHERE exclusion.local_album_id=a.id) "
                "AND NOT EXISTS (SELECT 1 FROM library_edition_conversion_jobs conversion "
                "WHERE conversion.local_album_id=a.id AND conversion.state IN "
                "('preflight','acquiring','ready','needs_recheck')) "
                f"{root_clause} GROUP BY a.id",
                parameters,
            ).fetchall()
            ready = 0
            mapping_required = 0
            exact_release_required = 0
            for row in rows:
                custom_ready = bool(
                    row["custom_manifest_id"]
                    and row["release_group_mbid"]
                    and row["release_mbid"] is None
                    and row["identity_revision"] is not None
                    and row["source_identity_revision"] is not None
                    and int(row["album_revision"]) == int(row["source_album_revision"])
                    and int(row["identity_revision"])
                    == int(row["source_identity_revision"])
                    and int(row["custom_current_count"] or 0) == int(row["track_count"])
                )
                if custom_ready:
                    ready += 1
                elif not row["release_group_mbid"] or not row["release_mbid"]:
                    exact_release_required += 1
                elif int(row["mapped_count"] or 0) == int(row["track_count"]) and int(
                    row["mapped_release_track_count"] or 0
                ) == int(row["track_count"]):
                    ready += 1
                else:
                    mapping_required += 1
            queued = connection.execute(
                "SELECT COUNT(*) FROM library_operation_jobs j "
                "JOIN library_repair_snapshots s ON s.job_id = j.id "
                "WHERE j.kind = 'repair' AND j.state IN "
                "('queued','running','paused','ready') "
                "AND json_extract(s.scope_json, '$.purpose') = 'management_readiness'"
            ).fetchone()[0]
            return {
                "album_count": len(rows),
                "ready_album_count": ready,
                "mapping_required_count": mapping_required,
                "exact_release_required_count": exact_release_required,
                "queued_preparation_count": int(queued),
            }

        return await self._read(operation)

    async def estimate_repair_operation(self, root_ids: list[str]) -> dict[str, int]:
        def operation(connection: sqlite3.Connection) -> dict[str, int]:
            parameters: list[Any] = []
            root_clause = ""
            if root_ids:
                placeholders = ",".join("?" for _ in root_ids)
                root_clause = f"AND a.root_id IN ({placeholders})"
                parameters.extend(root_ids)
            identity_count = connection.execute(
                "SELECT COUNT(*) FROM local_albums a "
                "JOIN local_album_external_identities i ON i.local_album_id = a.id "
                "WHERE a.retired_into_album_id IS NULL "
                "AND i.decision_source = 'legacy_import' "
                "AND EXISTS (SELECT 1 FROM local_tracks t "
                "WHERE t.local_album_id = a.id AND t.availability = 'indexed') "
                f"{root_clause}",
                parameters,
            ).fetchone()[0]
            queued_repair_count = connection.execute(
                "SELECT COUNT(*) FROM library_operation_jobs "
                "WHERE kind = 'repair' AND state IN ('queued','running','pausing','paused','ready')"
            ).fetchone()[0]
            return {
                "identity_count": int(identity_count),
                "queued_repair_count": int(queued_repair_count),
            }

        return await self._read(operation)

    async def defer_repair_audit_work(
        self,
        *,
        job_id: str,
        ordinal: int | None,
        worker_id: str,
        reason_code: str,
        now: float,
        retry_not_before: float | None = None,
    ) -> dict[str, Any]:
        """Release a running repair audit back to queued for a later retry.

        The running work item (when one is claimed) is returned to 'pending'
        with the failure code; the whole job is queued with next_attempt_at so
        the audit resumes exactly at the deferred item. Nothing is marked
        succeeded and no finding row is written.
        """

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            if ordinal is not None:
                work_update = connection.execute(
                    "UPDATE library_operation_work SET state = 'pending', failure_code = ?, "
                    "updated_at = ?, row_revision = row_revision + 1 "
                    "WHERE job_id = ? AND ordinal = ? AND state = 'running'",
                    (reason_code, now, job_id, ordinal),
                )
                if work_update.rowcount != 1:
                    raise StaleRevisionError(
                        "The repair audit work lease changed while it was deferred."
                    )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = 'queued', lease_owner = NULL, "
                "lease_expires_at = NULL, heartbeat_at = NULL, updated_at = ?, "
                "next_attempt_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND kind = 'repair' AND state = 'running' "
                "AND lease_owner = ? RETURNING *",
                (now, retry_not_before, job_id, worker_id),
            ).fetchone()
            if updated is None:
                raise StaleRevisionError(
                    "The repair audit lease changed while it was deferred."
                )
            self._bump_stream(connection, "operation")
            return dict(updated)

        result = await self._write_background(operation)
        if retry_not_before is not None:
            self.work_wakeups.notify_after("operation", retry_not_before - now)
        return result

    async def save_repair_finding_for_work(
        self,
        job_id: str,
        ordinal: int,
        *,
        worker_id: str,
        expected_work_revision: int,
        finding: RepairFinding,
        attempt: IdentificationAttempt | None = None,
        evidence: list[IdentificationEvidenceRecord] | None = None,
        auto_accept_edition: bool = False,
        now: float,
    ) -> str:
        """Persist one audit finding; optionally auto-apply the suggestion.

        With ``auto_accept_edition`` the just-saved ``exact_release_suggested``
        finding is applied in this same transaction through
        ``_apply_suggested_edition_tx`` as actor system with
        ``decision_source='automatic'`` (D-EDITION-AUTO). The finding row is
        then flipped to ``exact_release_auto_accepted``; if the apply hit a
        stale subject instead, the tx already marked it stale. Returns
        ``"saved"``, ``"auto_applied"`` or ``"auto_stale"``.
        """

        def operation(connection: sqlite3.Connection) -> str:
            work = connection.execute(
                "SELECT * FROM library_operation_work WHERE job_id = ? AND ordinal = ? "
                "AND state = 'running' AND row_revision = ?",
                (job_id, ordinal, expected_work_revision),
            ).fetchone()
            if work is None:
                raise StaleRevisionError(
                    "The repair subject changed before its finding was saved."
                )
            if attempt is not None:
                connection.execute(
                    "INSERT INTO library_identification_attempts "
                    "(id, local_album_id, local_track_id, trigger, requested_by_user_id, "
                    "input_tag_revision, input_policy_revision, input_file_revision, "
                    "input_identity_revision, matcher_version, "
                    "state, terminal_reason_code, selected_candidate_key, candidate_count, "
                    "degradation_flags_json, started_at, completed_at) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (
                        attempt.id,
                        attempt.local_album_id,
                        attempt.local_track_id,
                        attempt.trigger,
                        attempt.requested_by_user_id,
                        attempt.input_tag_revision,
                        attempt.input_policy_revision,
                        attempt.input_file_revision,
                        attempt.input_identity_revision,
                        attempt.matcher_version,
                        attempt.state,
                        attempt.terminal_reason_code,
                        attempt.selected_candidate_key,
                        attempt.candidate_count,
                        json.dumps(attempt.degradation_flags),
                        attempt.started_at,
                        attempt.completed_at,
                    ),
                )
                self._insert_evidence(connection, evidence or [])
            connection.execute(
                "INSERT INTO library_identity_repair_findings "
                "(id, job_id, local_album_id, evidence_id, expected_album_revision, "
                "expected_identity_revision, finding_code, confidence, reason_code, apply_eligible, "
                "suggested_release_mbid, suggested_release_group_mbid, suggested_edition_json, "
                "created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    finding.id,
                    job_id,
                    finding.local_album_id,
                    finding.evidence_id,
                    finding.expected_album_revision,
                    finding.expected_identity_revision,
                    finding.finding_code,
                    finding.confidence,
                    finding.reason_code,
                    int(finding.apply_eligible),
                    finding.suggested_release_mbid,
                    finding.suggested_release_group_mbid,
                    finding.suggested_edition_json,
                    now,
                    now,
                ),
            )
            outcome = "saved"
            result_payload: dict[str, object] = {"finding_id": finding.id}
            if auto_accept_edition:
                assert finding.finding_code == "exact_release_suggested"
                finding_row = connection.execute(
                    "SELECT * FROM library_identity_repair_findings WHERE id = ?",
                    (finding.id,),
                ).fetchone()
                album = connection.execute(
                    "SELECT row_revision FROM local_albums WHERE id = ?",
                    (work["local_album_id"],),
                ).fetchone()
                identity = connection.execute(
                    "SELECT * FROM local_album_external_identities "
                    "WHERE local_album_id = ?",
                    (work["local_album_id"],),
                ).fetchone()
                evidence_row = (
                    connection.execute(
                        "SELECT e.evidence_json, e.attempt_id, e.compacted, "
                        "a.input_tag_revision, a.input_file_revision, "
                        "a.input_policy_revision FROM library_identification_evidence e "
                        "JOIN library_identification_attempts a ON a.id = e.attempt_id "
                        "WHERE e.id = ?",
                        (finding.evidence_id,),
                    ).fetchone()
                    if finding.evidence_id
                    else None
                )
                track_rows = connection.execute(
                    "SELECT t.*, ti.recording_mbid, "
                    "ti.release_mbid AS identity_release_mbid, "
                    "ti.release_track_mbid, ti.medium_position, "
                    "ti.release_track_position FROM local_tracks t "
                    "LEFT JOIN local_track_external_identities ti "
                    "ON ti.local_track_id = t.id AND ti.provider = 'musicbrainz' "
                    "WHERE t.local_album_id = ? AND t.availability = 'indexed' "
                    "ORDER BY t.id",
                    (work["local_album_id"],),
                ).fetchall()
                evidence_candidate = (
                    msgspec.json.decode(
                        bytes(evidence_row["evidence_json"]), type=CandidateEvidence
                    )
                    if evidence_row is not None
                    else None
                )
                summary_payload = (
                    json.loads(finding.suggested_edition_json)
                    if finding.suggested_edition_json
                    else {}
                )
                apply_state, _failure = self._apply_suggested_edition_tx(
                    connection,
                    work=work,
                    finding=finding_row,
                    album=album,
                    identity=identity,
                    evidence_row=evidence_row,
                    track_rows=track_rows,
                    evidence=evidence_candidate,
                    job_id=job_id,
                    actor_user_id=None,
                    now=now,
                    decision_source="automatic",
                    ranking_inputs=summary_payload.get("auto_ranking"),
                )
                if apply_state == "succeeded":
                    connection.execute(
                        "UPDATE library_identity_repair_findings SET "
                        "finding_code = 'exact_release_auto_accepted', "
                        "reason_code = 'EXACT_EDITION_AUTO_ACCEPTED', "
                        "confidence = 'complete', apply_eligible = 0, "
                        "state = 'applied', apply_result = 'EDITION_AUTO_ACCEPTED', "
                        "updated_at = ?, row_revision = row_revision + 1 WHERE id = ?",
                        (now, finding.id),
                    )
                    outcome = "auto_applied"
                    result_payload["outcome"] = "EDITION_AUTO_ACCEPTED"
                else:
                    # The apply tx already flipped the inserted finding to
                    # stale; the audit unit itself still completed.
                    outcome = "auto_stale"
                    result_payload["outcome"] = "STALE_SUBJECT"
            connection.execute(
                "UPDATE library_operation_work SET state = 'succeeded', result_json = ?, "
                "updated_at = ?, row_revision = row_revision + 1 WHERE job_id = ? AND ordinal = ?",
                (json.dumps(result_payload), now, job_id, ordinal),
            )
            connection.execute(
                "UPDATE library_operation_jobs SET completed_count = completed_count + 1, "
                "succeeded_count = succeeded_count + 1, updated_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND state = 'running' AND lease_owner = ?",
                (now, job_id, worker_id),
            )
            self._bump_stream(connection, "operation")
            return outcome

        return await self._write_background(operation)

    async def get_live_automatic_edition_undo(
        self, local_album_ids: list[str]
    ) -> dict[str, tuple[int, int]]:
        """Map albums to their still-reversible auto-accept CAS revisions."""

        def operation(connection: sqlite3.Connection) -> dict[str, tuple[int, int]]:
            result: dict[str, tuple[int, int]] = {}
            for local_album_id in local_album_ids:
                snapshot = connection.execute(
                    "SELECT expected_post_album_revision, "
                    "expected_post_identity_revision FROM "
                    "library_automatic_edition_undo WHERE local_album_id = ? "
                    "AND consumed_at IS NULL",
                    (local_album_id,),
                ).fetchone()
                if snapshot is None:
                    continue
                identity = connection.execute(
                    "SELECT row_revision FROM local_album_external_identities "
                    "WHERE local_album_id = ? AND decision_source = 'automatic'",
                    (local_album_id,),
                ).fetchone()
                if identity is None or int(identity["row_revision"]) != int(
                    snapshot["expected_post_identity_revision"]
                ):
                    continue
                album = connection.execute(
                    "SELECT row_revision FROM local_albums WHERE id = ?",
                    (local_album_id,),
                ).fetchone()
                if album is None or int(album["row_revision"]) != int(
                    snapshot["expected_post_album_revision"]
                ):
                    continue
                result[local_album_id] = (
                    int(album["row_revision"]),
                    int(identity["row_revision"]),
                )
            return result

        return await self._read(operation)

    async def undo_automatic_edition_acceptance(
        self,
        local_album_id: str,
        *,
        expected_album_revision: int,
        expected_identity_revision: int,
        actor_user_id: str | None,
        now: float,
    ) -> dict[str, Any]:
        """S-2: one revisioned catalog-identity operation restoring the prior
        identity snapshot, or clearing the acceptance back to review when no
        prior existed. Never touches album pins."""

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            snapshot = connection.execute(
                "SELECT * FROM library_automatic_edition_undo "
                "WHERE local_album_id = ? AND consumed_at IS NULL",
                (local_album_id,),
            ).fetchone()
            if snapshot is None:
                raise ResourceNotFoundError(
                    "This album has no reversible automatic edition acceptance."
                )
            album = connection.execute(
                "SELECT row_revision FROM local_albums WHERE id = ?",
                (local_album_id,),
            ).fetchone()
            identity = connection.execute(
                "SELECT * FROM local_album_external_identities WHERE local_album_id = ?",
                (local_album_id,),
            ).fetchone()
            if (
                album is None
                or int(album["row_revision"]) != expected_album_revision
                or identity is None
                or identity["decision_source"] != "automatic"
                or int(identity["row_revision"]) != expected_identity_revision
                or int(snapshot["expected_post_identity_revision"])
                != int(identity["row_revision"])
            ):
                raise StaleRevisionError(
                    "The album identity changed since the automatic acceptance; "
                    "undo would restore a stale identity."
                )
            current_tracks = connection.execute(
                "SELECT ti.local_track_id, ti.recording_mbid, ti.release_mbid, "
                "ti.release_track_mbid, ti.medium_position, "
                "ti.release_track_position, ti.decision_source "
                "FROM local_track_external_identities ti JOIN local_tracks t "
                "ON t.id = ti.local_track_id WHERE t.local_album_id = ? "
                "AND t.availability = 'indexed' ORDER BY ti.local_track_id",
                (local_album_id,),
            ).fetchall()
            before = {
                "identity": {
                    "release_group_mbid": identity["release_group_mbid"],
                    "release_mbid": identity["release_mbid"],
                    "decision_source": identity["decision_source"],
                    "row_revision": int(identity["row_revision"]),
                },
                "tracks": [dict(row) for row in current_tracks],
            }
            prior_json = snapshot["prior_identity_json"]
            prior_tracks = json.loads(str(snapshot["prior_track_identities_json"]))
            review_id = None
            if prior_json is not None:
                prior = json.loads(str(prior_json))
                connection.execute(
                    "INSERT INTO local_album_external_identities "
                    "(local_album_id, provider, release_group_mbid, release_mbid, "
                    "decision_source, matcher_version, attempt_id, "
                    "selected_by_user_id, selected_at) "
                    "VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, ?, ?) "
                    "ON CONFLICT(local_album_id, provider) DO UPDATE SET "
                    "release_group_mbid = excluded.release_group_mbid, "
                    "release_mbid = excluded.release_mbid, "
                    "decision_source = excluded.decision_source, "
                    "matcher_version = excluded.matcher_version, "
                    "attempt_id = excluded.attempt_id, "
                    "selected_by_user_id = excluded.selected_by_user_id, "
                    "selected_at = excluded.selected_at, "
                    "row_revision = row_revision + 1",
                    (
                        local_album_id,
                        prior["release_group_mbid"],
                        prior["release_mbid"],
                        prior["decision_source"],
                        prior["matcher_version"],
                        prior["attempt_id"],
                        prior["selected_by_user_id"],
                        prior["selected_at"],
                    ),
                )
                outcome = "restored"
            else:
                connection.execute(
                    "DELETE FROM local_album_external_identities "
                    "WHERE local_album_id = ?",
                    (local_album_id,),
                )
                review_id = str(uuid.uuid4())
                connection.execute(
                    "INSERT INTO library_identification_reviews "
                    "(id, local_album_id, state, reason_code, attempt_id, "
                    "input_revision, created_at, updated_at) "
                    "VALUES (?, ?, 'needs_review', "
                    "'AUTOMATIC_EDITION_CLEARED_TO_REVIEW', ?, ?, ?, ?)",
                    (
                        review_id,
                        local_album_id,
                        identity["attempt_id"],
                        f"undo:{snapshot['id']}",
                        now,
                        now,
                    ),
                )
                outcome = "cleared_to_review"
            connection.execute(
                "DELETE FROM local_track_external_identities WHERE "
                "local_track_id IN (SELECT id FROM local_tracks "
                "WHERE local_album_id = ? AND availability = 'indexed')",
                (local_album_id,),
            )
            for track in prior_tracks:
                connection.execute(
                    "INSERT INTO local_track_external_identities "
                    "(local_track_id, provider, recording_mbid, release_mbid, "
                    "release_track_mbid, medium_position, release_track_position, "
                    "decision_source, attempt_id, selected_at) "
                    "VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, ?, ?, ?) "
                    "ON CONFLICT(local_track_id, provider) DO UPDATE SET "
                    "recording_mbid = excluded.recording_mbid, "
                    "release_mbid = excluded.release_mbid, "
                    "release_track_mbid = excluded.release_track_mbid, "
                    "medium_position = excluded.medium_position, "
                    "release_track_position = excluded.release_track_position, "
                    "decision_source = excluded.decision_source, "
                    "attempt_id = excluded.attempt_id, "
                    "selected_at = excluded.selected_at, "
                    "row_revision = row_revision + 1",
                    (
                        track["local_track_id"],
                        track["recording_mbid"],
                        track["release_mbid"],
                        track["release_track_mbid"],
                        track["medium_position"],
                        track["release_track_position"],
                        track["decision_source"],
                        track["attempt_id"],
                        track["selected_at"],
                    ),
                )
            action_id = str(uuid.uuid4())
            connection.execute(
                "UPDATE library_automatic_edition_undo SET consumed_at = ?, "
                "consumed_action_id = ? WHERE id = ?",
                (now, action_id, snapshot["id"]),
            )
            connection.execute(
                "INSERT INTO library_catalog_actions "
                "(id, actor_user_id, action_kind, local_album_id, before_json, "
                "after_json, reason_code, created_at) VALUES (?,?,?,?,?,?,?,?)",
                (
                    action_id,
                    actor_user_id,
                    "undo_automatic_edition",
                    local_album_id,
                    json.dumps(before, sort_keys=True),
                    json.dumps(
                        {
                            "outcome": outcome,
                            "review_id": review_id,
                            "undo_snapshot_id": snapshot["id"],
                        },
                        sort_keys=True,
                    ),
                    "AUTOMATIC_EDITION_UNDONE",
                    now,
                ),
            )
            self._bump_catalog(connection)
            self._bump_stream(connection, "operation")
            return {"outcome": outcome, "review_id": review_id}

        return await self._write(operation)

    async def mark_repair_ready(
        self, job_id: str, worker_id: str, *, now: float
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            materialization = connection.execute(
                "SELECT sealed FROM library_repair_materialization WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if materialization is None:
                # Pre-GH-293 jobs carry their work inline; retro-seal them.
                self._repair_materialization_backfill_tx(connection, job_id, now=now)
                materialization = connection.execute(
                    "SELECT sealed FROM library_repair_materialization WHERE job_id = ?",
                    (job_id,),
                ).fetchone()
            if materialization is None or int(materialization["sealed"]) != 1:
                raise StaleRevisionError("The repair worklist is not sealed yet.")
            pending = connection.execute(
                "SELECT COUNT(*) FROM library_operation_work WHERE job_id = ? "
                "AND state IN ('pending','running')",
                (job_id,),
            ).fetchone()[0]
            if pending:
                raise StaleRevisionError(
                    "The repair audit still has unfinished subjects."
                )
            snapshot = connection.execute(
                "SELECT target_matcher_version, scope_json FROM library_repair_snapshots WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            findings = connection.execute(
                "SELECT finding_code, reason_code, COUNT(*) count "
                "FROM library_identity_repair_findings WHERE job_id = ? "
                "GROUP BY finding_code, reason_code",
                (job_id,),
            ).fetchall()
            roots = connection.execute(
                "SELECT a.root_id, COUNT(DISTINCT f.local_album_id) count "
                "FROM library_identity_repair_findings f "
                "JOIN local_albums a ON a.id = f.local_album_id "
                "WHERE f.job_id = ? GROUP BY a.root_id ORDER BY a.root_id",
                (job_id,),
            ).fetchall()
            scope = json.loads(str(snapshot["scope_json"]))
            purpose = str(scope.get("purpose", "existing_matches"))
            track_scope = (
                "AND t.availability = 'indexed' "
                if purpose in {"management_readiness", "existing_matches"}
                else ""
            )
            input_tracks = int(
                connection.execute(
                    "SELECT COUNT(*) FROM local_tracks t WHERE t.local_album_id IN "
                    "(SELECT local_album_id FROM library_identity_repair_findings WHERE job_id = ?) "
                    + track_scope,
                    (job_id,),
                ).fetchone()[0]
            )
            counts_by_finding: dict[str, int] = {}
            counts_by_reason: dict[str, int] = {}
            for finding in findings:
                counts_by_finding[str(finding["finding_code"])] = counts_by_finding.get(
                    str(finding["finding_code"]), 0
                ) + int(finding["count"])
                counts_by_reason[str(finding["reason_code"])] = counts_by_reason.get(
                    str(finding["reason_code"]), 0
                ) + int(finding["count"])
            total = sum(counts_by_finding.values())
            apply_finding = (
                "mapping_ready" if purpose == "management_readiness" else "safe_detach"
            )
            summary = {
                "total_identities": total,
                "remaining_identities": 0,
                "input_track_count": input_tracks,
                "playable_after_detach_track_count": input_tracks,
                "estimated_apply_changes": counts_by_finding.get(apply_finding, 0),
                "catalog_snapshot_revision": int(
                    connection.execute(
                        "SELECT input_catalog_revision FROM library_operation_jobs WHERE id = ?",
                        (job_id,),
                    ).fetchone()[0]
                ),
                "target_matcher_version": str(snapshot["target_matcher_version"]),
                "counts_by_finding": counts_by_finding,
                "counts_by_reason": counts_by_reason,
                "album_counts_by_root": {
                    str(root["root_id"]): int(root["count"]) for root in roots
                },
                "provider_deferred_count": counts_by_reason.get("PROVIDER_DEFERRED", 0),
                "failed_evidence_count": counts_by_reason.get(
                    "EVIDENCE_UNAVAILABLE", 0
                ),
                "purpose": purpose,
                "ready_album_count": counts_by_finding.get("ready", 0),
                "mapping_candidate_count": counts_by_finding.get("mapping_ready", 0),
                "exact_release_required_count": counts_by_finding.get(
                    "exact_release_required", 0
                ),
                "needs_review_count": counts_by_finding.get("needs_review", 0),
            }
            connection.execute(
                "UPDATE library_repair_snapshots SET result_json = ? WHERE job_id = ?",
                (json.dumps(summary, sort_keys=True), job_id),
            )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = 'ready', terminal_code = 'DRY_RUN_READY', "
                "lease_owner = NULL, lease_expires_at = NULL, heartbeat_at = NULL, updated_at = ?, "
                "row_revision = row_revision + 1, event_revision = event_revision + 1 "
                "WHERE id = ? AND state = 'running' AND lease_owner = ? RETURNING *",
                (now, job_id, worker_id),
            ).fetchone()
            if updated is None:
                raise StaleRevisionError(
                    "The repair job changed before it became ready."
                )
            self._bump_stream(connection, "operation")
            return dict(updated)

        return await self._write(operation)

    async def start_repair_apply(
        self, job_id: str, *, expected_row_revision: int, now: float
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> tuple[dict[str, Any], bool]:
            job = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id = ?", (job_id,)
            ).fetchone()
            if job is None:
                raise ResourceNotFoundError("Repair job not found.")
            snapshot = connection.execute(
                "SELECT phase FROM library_repair_snapshots WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if snapshot is not None and snapshot["phase"] == "apply":
                return dict(job), False
            if (
                job["state"] != "ready"
                or int(job["row_revision"]) != expected_row_revision
            ):
                raise StaleRevisionError("The repair report changed before Apply.")
            findings = connection.execute(
                "SELECT * FROM library_identity_repair_findings WHERE job_id = ? "
                "AND apply_eligible = 1 AND state = 'open' ORDER BY id",
                (job_id,),
            ).fetchall()
            connection.execute(
                "DELETE FROM library_operation_work WHERE job_id = ?", (job_id,)
            )
            connection.executemany(
                "INSERT INTO library_operation_work "
                "(job_id, ordinal, local_album_id, expected_subject_revision, expected_input_revision, "
                "action, idempotency_key, updated_at) VALUES (?,?,?,?,?,?,?,?)",
                [
                    (
                        job_id,
                        ordinal,
                        finding["local_album_id"],
                        finding["expected_album_revision"],
                        f"{finding['expected_identity_revision'] or ''}:{finding['evidence_id'] or ''}",
                        "repair_apply",
                        f"{job_id}:{finding['id']}:apply",
                        now,
                    )
                    for ordinal, finding in enumerate(findings)
                ],
            )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = 'queued', expected_work_count = ?, "
                "completed_count = 0, succeeded_count = 0, failed_count = 0, skipped_count = 0, "
                "terminal_code = NULL, terminal_at = NULL, updated_at = ?, row_revision = row_revision + 1, "
                "event_revision = event_revision + 1 WHERE id = ? RETURNING *",
                (len(findings), now, job_id),
            ).fetchone()
            connection.execute(
                "UPDATE library_repair_snapshots SET phase = 'apply' WHERE job_id = ?",
                (job_id,),
            )
            self._bump_stream(connection, "operation")
            return dict(updated), True

        job, queued = await self._write(operation)
        if queued:
            self.work_wakeups.notify("operation")
        return job

    async def discard_management_identity_preparation(
        self,
        job_id: str,
        *,
        expected_row_revision: int,
        now: float,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            job = connection.execute(
                "SELECT * FROM library_operation_jobs WHERE id = ?", (job_id,)
            ).fetchone()
            snapshot = connection.execute(
                "SELECT scope_json, phase FROM library_repair_snapshots WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if job is None or snapshot is None:
                raise ResourceNotFoundError("Identity preparation job not found.")
            scope = json.loads(str(snapshot["scope_json"]))
            if scope.get("purpose") != "management_readiness":
                raise ResourceNotFoundError("Identity preparation job not found.")
            if job["state"] == "cancelled" and job["terminal_code"] == (
                "IDENTITY_PREPARATION_DISCARDED"
            ):
                return dict(job)
            if (
                job["state"] != "ready"
                or snapshot["phase"] != "dry_run"
                or int(job["row_revision"]) != expected_row_revision
            ):
                raise StaleRevisionError(
                    "The identity preparation report changed before it was discarded."
                )
            updated = connection.execute(
                "UPDATE library_operation_jobs SET state = 'cancelled', "
                "terminal_code = 'IDENTITY_PREPARATION_DISCARDED', terminal_at = ?, "
                "control_request = 'none', lease_owner = NULL, lease_expires_at = NULL, "
                "heartbeat_at = NULL, updated_at = ?, row_revision = row_revision + 1, "
                "event_revision = event_revision + 1 WHERE id = ? RETURNING *",
                (now, now, job_id),
            ).fetchone()
            self._bump_stream(connection, "operation")
            return dict(updated)

        return await self._write(operation)

    async def apply_repair_work(
        self,
        job_id: str,
        ordinal: int,
        *,
        worker_id: str,
        expected_work_revision: int,
        actor_user_id: str,
        now: float,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            snapshot = connection.execute(
                "SELECT scope_json FROM library_repair_snapshots WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            scope = json.loads(str(snapshot["scope_json"])) if snapshot else {}
            management_readiness = scope.get("purpose") == "management_readiness"
            work = connection.execute(
                "SELECT * FROM library_operation_work WHERE job_id = ? AND ordinal = ? "
                "AND state = 'running' AND row_revision = ?",
                (job_id, ordinal, expected_work_revision),
            ).fetchone()
            if work is None:
                raise StaleRevisionError("The repair Apply subject changed.")
            finding = connection.execute(
                "SELECT * FROM library_identity_repair_findings WHERE job_id = ? "
                "AND local_album_id = ? AND apply_eligible = 1 AND state = 'open'",
                (job_id, work["local_album_id"]),
            ).fetchone()
            album = connection.execute(
                "SELECT row_revision FROM local_albums WHERE id = ?",
                (work["local_album_id"],),
            ).fetchone()
            identity = connection.execute(
                "SELECT * FROM local_album_external_identities WHERE local_album_id = ?",
                (work["local_album_id"],),
            ).fetchone()
            state = "succeeded"
            failure_code = None
            if management_readiness:
                evidence_row = (
                    connection.execute(
                        "SELECT e.evidence_json, e.attempt_id, e.compacted, "
                        "a.input_tag_revision, a.input_file_revision, "
                        "a.input_policy_revision FROM library_identification_evidence e "
                        "JOIN library_identification_attempts a ON a.id = e.attempt_id "
                        "WHERE e.id = ?",
                        (finding["evidence_id"],),
                    ).fetchone()
                    if finding is not None and finding["evidence_id"]
                    else None
                )
                track_rows = connection.execute(
                    "SELECT t.*, ti.recording_mbid, "
                    "ti.release_mbid AS identity_release_mbid, "
                    "ti.release_track_mbid, ti.medium_position, "
                    "ti.release_track_position FROM local_tracks t "
                    "LEFT JOIN local_track_external_identities ti "
                    "ON ti.local_track_id = t.id AND ti.provider = 'musicbrainz' "
                    "WHERE t.local_album_id = ? AND t.availability = 'indexed' "
                    "ORDER BY t.id",
                    (work["local_album_id"],),
                ).fetchall()
                evidence = (
                    msgspec.json.decode(
                        bytes(evidence_row["evidence_json"]), type=CandidateEvidence
                    )
                    if evidence_row is not None
                    else None
                )
                if finding is not None and finding["finding_code"] == (
                    "exact_release_suggested"
                ):
                    state, failure_code = self._apply_suggested_edition_tx(
                        connection,
                        work=work,
                        finding=finding,
                        album=album,
                        identity=identity,
                        evidence_row=evidence_row,
                        track_rows=track_rows,
                        evidence=evidence,
                        job_id=job_id,
                        actor_user_id=actor_user_id,
                        now=now,
                    )
                else:
                    current_revisions = tuple(
                        _album_input_revision(track_rows).split(":")
                    )
                    proposed = {
                        item.local_track_id: item
                        for item in (evidence.track_evidence if evidence else [])
                        if item.classification == "supported"
                    }
                    stale = bool(
                        finding is None
                        or album is None
                        or identity is None
                        or evidence_row is None
                        or evidence is None
                        or int(album["row_revision"])
                        != int(work["expected_subject_revision"])
                        or int(identity["row_revision"])
                        != int(finding["expected_identity_revision"])
                        or str(identity["release_group_mbid"])
                        != evidence.release_group_mbid
                        or str(identity["release_mbid"] or "")
                        != str(evidence.release_mbid or "")
                        or current_revisions
                        != (
                            str(evidence_row["input_tag_revision"]),
                            str(evidence_row["input_file_revision"]),
                            str(evidence_row["input_policy_revision"]),
                        )
                        or set(proposed) != {str(row["id"]) for row in track_rows}
                    )
                    release_track_ids: set[str] = set()
                    if not stale:
                        for row in track_rows:
                            item = proposed[str(row["id"])]
                            if (
                                not item.recording_mbid
                                or not item.release_track_mbid
                                or item.candidate_disc_number is None
                                or item.candidate_track_position is None
                                or item.release_track_mbid in release_track_ids
                                or not _recording_evidence_matches(
                                    row["recording_mbid"], item
                                )
                                or (
                                    row["identity_release_mbid"]
                                    and row["identity_release_mbid"]
                                    != evidence.release_mbid
                                )
                                or (
                                    row["release_track_mbid"]
                                    and row["release_track_mbid"]
                                    != item.release_track_mbid
                                )
                                or (
                                    row["embedded_release_group_mbid"]
                                    and row["embedded_release_group_mbid"]
                                    != evidence.release_group_mbid
                                )
                                or (
                                    row["embedded_release_mbid"]
                                    and row["embedded_release_mbid"]
                                    != evidence.release_mbid
                                )
                                or not _recording_evidence_matches(
                                    row["embedded_recording_mbid"], item
                                )
                                or (
                                    row["embedded_release_track_mbid"]
                                    and row["embedded_release_track_mbid"]
                                    != item.release_track_mbid
                                )
                            ):
                                stale = True
                                break
                            release_track_ids.add(item.release_track_mbid)
                    if stale:
                        state = "skipped"
                        failure_code = "STALE_SUBJECT"
                        if finding is not None:
                            connection.execute(
                                "UPDATE library_identity_repair_findings SET finding_code = 'stale', "
                                "state = 'stale', "
                                "apply_result = 'STALE_SUBJECT', updated_at = ?, "
                                "row_revision = row_revision + 1 WHERE id = ?",
                                (now, finding["id"]),
                            )
                    else:
                        assert finding is not None
                        assert evidence is not None
                        assert evidence_row is not None
                        before = [
                            {
                                "local_track_id": str(row["id"]),
                                "recording_mbid": row["recording_mbid"],
                                "release_mbid": row["identity_release_mbid"],
                                "release_track_mbid": row["release_track_mbid"],
                            }
                            for row in track_rows
                        ]
                        for local_track_id, item in proposed.items():
                            connection.execute(
                                "INSERT INTO local_track_external_identities "
                                "(local_track_id, provider, recording_mbid, release_mbid, "
                                "release_track_mbid, medium_position, release_track_position, "
                                "decision_source, attempt_id, selected_at) "
                                "VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, 'manual', ?, ?) "
                                "ON CONFLICT(local_track_id, provider) DO UPDATE SET "
                                "recording_mbid = excluded.recording_mbid, "
                                "release_mbid = excluded.release_mbid, "
                                "release_track_mbid = excluded.release_track_mbid, "
                                "medium_position = excluded.medium_position, "
                                "release_track_position = excluded.release_track_position, "
                                "decision_source = 'manual', attempt_id = excluded.attempt_id, "
                                "selected_at = excluded.selected_at, "
                                "row_revision = row_revision + 1",
                                (
                                    local_track_id,
                                    item.recording_mbid,
                                    evidence.release_mbid,
                                    item.release_track_mbid,
                                    item.candidate_disc_number,
                                    item.candidate_track_position,
                                    evidence_row["attempt_id"],
                                    now,
                                ),
                            )
                        after = [
                            {
                                "local_track_id": local_track_id,
                                "recording_mbid": item.recording_mbid,
                                "release_mbid": evidence.release_mbid,
                                "release_track_mbid": item.release_track_mbid,
                                "medium_position": item.candidate_disc_number,
                                "release_track_position": item.candidate_track_position,
                            }
                            for local_track_id, item in sorted(proposed.items())
                        ]
                        connection.execute(
                            "INSERT INTO library_catalog_actions "
                            "(id, actor_user_id, action_kind, local_album_id, "
                            "operation_job_id, before_json, after_json, reason_code, "
                            "created_at) VALUES (?,?,?,?,?,?,?,?,?)",
                            (
                                str(uuid.uuid4()),
                                actor_user_id,
                                "accept_management_track_mappings",
                                work["local_album_id"],
                                job_id,
                                json.dumps(before, sort_keys=True),
                                json.dumps(after, sort_keys=True),
                                "EXACT_RELEASE_MAPPINGS_ACCEPTED",
                                now,
                            ),
                        )
                        connection.execute(
                            "UPDATE library_identity_repair_findings SET state = 'applied', "
                            "apply_result = 'MAPPINGS_ACCEPTED', updated_at = ?, "
                            "row_revision = row_revision + 1 WHERE id = ?",
                            (now, finding["id"]),
                        )
                        self._bump_catalog(connection)
            elif (
                finding is None
                or album is None
                or identity is None
                or int(album["row_revision"]) != int(work["expected_subject_revision"])
                or int(identity["row_revision"])
                != int(finding["expected_identity_revision"])
            ):
                state = "skipped"
                failure_code = "STALE_SUBJECT"
                if finding is not None:
                    connection.execute(
                        "UPDATE library_identity_repair_findings SET state = 'stale', "
                        "apply_result = 'STALE_SUBJECT', updated_at = ?, row_revision = row_revision + 1 "
                        "WHERE id = ?",
                        (now, finding["id"]),
                    )
            else:
                evidence_attempt = (
                    connection.execute(
                        "SELECT a.input_tag_revision,a.input_file_revision,"
                        "a.input_policy_revision,a.input_identity_revision "
                        "FROM library_identification_evidence e "
                        "JOIN library_identification_attempts a ON a.id=e.attempt_id "
                        "WHERE e.id=?",
                        (finding["evidence_id"],),
                    ).fetchone()
                    if finding is not None and finding["evidence_id"]
                    else None
                )
                current_tracks = connection.execute(
                    "SELECT id,tag_revision,stat_revision,applied_policy_revision,"
                    "applied_policy FROM local_tracks WHERE local_album_id=? "
                    "AND availability='indexed'",
                    (work["local_album_id"],),
                ).fetchall()
                current_album_identity, current_identity_tracks = (
                    _identification_identity_rows(
                        connection, str(work["local_album_id"])
                    )
                )
                if (
                    evidence_attempt is None
                    or not current_tracks
                    or _album_input_revision(list(current_tracks))
                    != ":".join(
                        (
                            str(evidence_attempt["input_tag_revision"]),
                            str(evidence_attempt["input_file_revision"]),
                            str(evidence_attempt["input_policy_revision"]),
                        )
                    )
                    or not evidence_attempt["input_identity_revision"]
                    or _album_identity_revision(
                        current_album_identity, current_identity_tracks
                    )
                    != str(evidence_attempt["input_identity_revision"])
                ):
                    state = "skipped"
                    failure_code = "STALE_SUBJECT"
                    connection.execute(
                        "UPDATE library_identity_repair_findings SET state='stale', "
                        "apply_result='STALE_SUBJECT', updated_at=?, "
                        "row_revision=row_revision+1 WHERE id=?",
                        (now, finding["id"]),
                    )
                else:
                    connection.execute(
                        "DELETE FROM local_track_external_identities WHERE local_track_id IN "
                        "(SELECT id FROM local_tracks WHERE local_album_id = ? "
                        "AND availability = 'indexed')",
                        (work["local_album_id"],),
                    )
                    connection.execute(
                        "DELETE FROM local_album_external_identities WHERE local_album_id = ?",
                        (work["local_album_id"],),
                    )
                    review_id = str(uuid.uuid4())
                    input_revision = f"repair:{job_id}:{finding['id']}"
                    connection.execute(
                        "INSERT INTO library_identification_reviews "
                        "(id, local_album_id, state, reason_code, attempt_id, input_revision, "
                        "created_at, updated_at) VALUES (?, ?, 'needs_review', "
                        "'LEGACY_IDENTITY_FAILED_SAFETY_RULES', ?, ?, ?, ?)",
                        (
                            review_id,
                            work["local_album_id"],
                            identity["attempt_id"],
                            input_revision,
                            now,
                            now,
                        ),
                    )
                    action_id = str(uuid.uuid4())
                    connection.execute(
                        "INSERT INTO library_catalog_actions "
                        "(id, actor_user_id, action_kind, local_album_id, operation_job_id, "
                        "before_json, after_json, reason_code, created_at) VALUES (?,?,?,?,?,?,?,?,?)",
                        (
                            action_id,
                            actor_user_id,
                            "repair_detach",
                            work["local_album_id"],
                            job_id,
                            json.dumps(
                                {"release_group_mbid": identity["release_group_mbid"]}
                            ),
                            json.dumps({"review_id": review_id}),
                            "LEGACY_IDENTITY_FAILED_SAFETY_RULES",
                            now,
                        ),
                    )
                    connection.execute(
                        "UPDATE library_identity_repair_findings SET state = 'applied', "
                        "apply_result = 'DETACHED', updated_at = ?, row_revision = row_revision + 1 "
                        "WHERE id = ?",
                        (now, finding["id"]),
                    )
                    self._bump_catalog(connection)
            connection.execute(
                "UPDATE library_operation_work SET state = ?, failure_code = ?, updated_at = ?, "
                "row_revision = row_revision + 1 WHERE job_id = ? AND ordinal = ?",
                (state, failure_code, now, job_id, ordinal),
            )
            counter = "succeeded_count" if state == "succeeded" else "skipped_count"
            connection.execute(
                f"UPDATE library_operation_jobs SET completed_count = completed_count + 1, "
                f"{counter} = {counter} + 1, updated_at = ?, row_revision = row_revision + 1, "
                "event_revision = event_revision + 1 WHERE id = ? AND state = 'running' AND lease_owner = ?",
                (now, job_id, worker_id),
            )
            self._bump_stream(connection, "operation")
            return {"state": state, "failure_code": failure_code}

        return await self._write_background(operation)

    def _apply_suggested_edition_tx(
        self,
        connection: sqlite3.Connection,
        *,
        work: sqlite3.Row,
        finding: sqlite3.Row,
        album: sqlite3.Row | None,
        identity: sqlite3.Row | None,
        evidence_row: sqlite3.Row | None,
        track_rows: list[sqlite3.Row],
        evidence: CandidateEvidence | None,
        job_id: str,
        actor_user_id: str,
        now: float,
        decision_source: str = "manual",
        ranking_inputs: object | None = None,
    ) -> tuple[str, str | None]:
        """Seal one accepted suggested edition; mirrors manual candidate accept.

        ``decision_source='automatic'`` (D-EDITION-AUTO) writes
        ``decision_source='automatic'`` identity rows, a dedicated
        ``library_catalog_actions`` audit row with source string
        ``automatic_exact_edition`` carrying reason/ranking inputs/evidence,
        and an undo snapshot in ``library_automatic_edition_undo`` - all
        inside this same transaction. The manual default is byte-identical
        to the pre-D-EDITION-AUTO behavior.
        """
        mapped = (
            _complete_track_identity_mapping(track_rows, evidence)
            if evidence is not None
            else None
        )
        stale = bool(
            album is None
            or evidence_row is None
            or evidence is None
            or mapped is None
            or int(evidence_row["compacted"])
            or int(album["row_revision"]) != int(work["expected_subject_revision"])
            or tuple(_album_input_revision(track_rows).split(":"))
            != (
                str(evidence_row["input_tag_revision"]),
                str(evidence_row["input_file_revision"]),
                str(evidence_row["input_policy_revision"]),
            )
            or (identity is None) != (finding["expected_identity_revision"] is None)
            or (
                identity is not None
                and (
                    int(identity["row_revision"])
                    != int(finding["expected_identity_revision"])
                    or identity["release_mbid"] is not None
                    # F-EDITION-01: an existing release group must equal the
                    # candidate's - a cross-RG write is an identity conflict,
                    # evaluated in addition to every revision guard above.
                    or (identity["release_group_mbid"] or "").casefold()
                    != (evidence.release_group_mbid or "").casefold()
                )
            )
            or evidence.reason_code not in AUTOMATIC_SAFE_EVIDENCE_REASONS
        )
        if not stale:
            assert evidence is not None
            assert mapped is not None
            for row, item in zip(track_rows, mapped, strict=True):
                if (
                    not _recording_evidence_matches(row["recording_mbid"], item)
                    or (
                        row["identity_release_mbid"]
                        and row["identity_release_mbid"] != evidence.release_mbid
                    )
                    or (
                        row["release_track_mbid"]
                        and row["release_track_mbid"] != item.release_track_mbid
                    )
                    or (
                        row["embedded_release_group_mbid"]
                        and row["embedded_release_group_mbid"]
                        != evidence.release_group_mbid
                    )
                    or (
                        row["embedded_release_mbid"]
                        and row["embedded_release_mbid"] != evidence.release_mbid
                    )
                    or not _recording_evidence_matches(
                        row["embedded_recording_mbid"], item
                    )
                    or (
                        row["embedded_release_track_mbid"]
                        and row["embedded_release_track_mbid"]
                        != item.release_track_mbid
                    )
                ):
                    stale = True
                    break
        if stale:
            connection.execute(
                "UPDATE library_identity_repair_findings SET finding_code = 'stale', "
                "state = 'stale', apply_result = 'STALE_SUBJECT', updated_at = ?, "
                "row_revision = row_revision + 1 WHERE id = ?",
                (now, finding["id"]),
            )
            return "skipped", "STALE_SUBJECT"
        assert evidence is not None
        assert evidence_row is not None
        assert mapped is not None
        before = (
            {
                "release_group_mbid": identity["release_group_mbid"],
                "release_mbid": identity["release_mbid"],
            }
            if identity is not None
            else {}
        )
        if decision_source == "automatic":
            # S-1/S-2: capture the reversible prior-identity snapshot before
            # any mutation, inside this same transaction.
            assert album is not None
            prior_tracks = connection.execute(
                "SELECT ti.local_track_id, ti.recording_mbid, ti.release_mbid, "
                "ti.release_track_mbid, ti.medium_position, "
                "ti.release_track_position, ti.decision_source, ti.attempt_id, "
                "ti.selected_at FROM local_track_external_identities ti "
                "JOIN local_tracks t ON t.id = ti.local_track_id "
                "WHERE t.local_album_id = ? AND t.availability = 'indexed' "
                "ORDER BY ti.local_track_id",
                (work["local_album_id"],),
            ).fetchall()
            connection.execute(
                "INSERT INTO library_automatic_edition_undo "
                "(id, local_album_id, job_id, evidence_id, prior_identity_json, "
                "prior_track_identities_json, expected_post_album_revision, "
                "expected_post_identity_revision, reason_code, created_at) "
                "VALUES (?,?,?,?,?,?,?,?,?,?) "
                "ON CONFLICT(local_album_id) DO UPDATE SET id = excluded.id, "
                "job_id = excluded.job_id, evidence_id = excluded.evidence_id, "
                "prior_identity_json = excluded.prior_identity_json, "
                "prior_track_identities_json = excluded.prior_track_identities_json, "
                "expected_post_album_revision = excluded.expected_post_album_revision, "
                "expected_post_identity_revision = "
                "excluded.expected_post_identity_revision, "
                "reason_code = excluded.reason_code, created_at = excluded.created_at, "
                "consumed_at = NULL, consumed_action_id = NULL",
                (
                    str(uuid.uuid4()),
                    work["local_album_id"],
                    job_id,
                    finding["evidence_id"],
                    json.dumps(
                        {
                            "release_group_mbid": identity["release_group_mbid"],
                            "release_mbid": identity["release_mbid"],
                            "decision_source": identity["decision_source"],
                            "matcher_version": identity["matcher_version"],
                            "attempt_id": identity["attempt_id"],
                            "selected_by_user_id": identity["selected_by_user_id"],
                            "selected_at": identity["selected_at"],
                            "row_revision": int(identity["row_revision"]),
                        },
                        sort_keys=True,
                    )
                    if identity is not None
                    else None,
                    json.dumps([dict(row) for row in prior_tracks], sort_keys=True),
                    int(album["row_revision"]),
                    (int(identity["row_revision"]) + 1 if identity is not None else 1),
                    evidence.reason_code,
                    now,
                ),
            )
        connection.execute(
            "INSERT INTO local_album_external_identities "
            "(local_album_id, provider, release_group_mbid, release_mbid, "
            "decision_source, matcher_version, attempt_id, selected_by_user_id, "
            "selected_at) "
            "VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(local_album_id, provider) DO UPDATE SET "
            "release_group_mbid = excluded.release_group_mbid, "
            "release_mbid = excluded.release_mbid, "
            "decision_source = excluded.decision_source, "
            "matcher_version = excluded.matcher_version, "
            "attempt_id = excluded.attempt_id, "
            "selected_by_user_id = excluded.selected_by_user_id, "
            "selected_at = excluded.selected_at, row_revision = row_revision + 1",
            (
                work["local_album_id"],
                evidence.release_group_mbid,
                evidence.release_mbid,
                decision_source,
                evidence.matcher_version,
                evidence_row["attempt_id"],
                actor_user_id,
                now,
            ),
        )
        connection.execute(
            "DELETE FROM local_track_external_identities WHERE local_track_id IN "
            "(SELECT id FROM local_tracks WHERE local_album_id = ? "
            "AND availability = 'indexed')",
            (work["local_album_id"],),
        )
        for item in mapped:
            connection.execute(
                "INSERT INTO local_track_external_identities "
                "(local_track_id, provider, recording_mbid, release_mbid, "
                "release_track_mbid, medium_position, release_track_position, "
                "decision_source, attempt_id, selected_at) "
                "VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    item.local_track_id,
                    item.recording_mbid,
                    evidence.release_mbid,
                    item.release_track_mbid,
                    item.candidate_disc_number,
                    item.candidate_track_position,
                    decision_source,
                    evidence_row["attempt_id"],
                    now,
                ),
            )
        connection.execute(
            "DELETE FROM library_custom_edition_active WHERE local_album_id = ?",
            (work["local_album_id"],),
        )
        connection.execute(
            "DELETE FROM library_management_exclusions WHERE local_album_id = ?",
            (work["local_album_id"],),
        )
        connection.execute(
            "UPDATE library_identification_reviews SET state = 'resolved', "
            "reason_code = 'SUGGESTED_EDITION_ACCEPTED', decided_by_user_id = ?, "
            "decided_at = ?, updated_at = ?, decision_revision = decision_revision + 1, "
            "row_revision = row_revision + 1 WHERE local_album_id = ? "
            "AND state != 'resolved'",
            (actor_user_id, now, now, work["local_album_id"]),
        )
        after = {
            "release_group_mbid": evidence.release_group_mbid,
            "release_mbid": evidence.release_mbid,
            "tracks": [
                {
                    "local_track_id": item.local_track_id,
                    "recording_mbid": item.recording_mbid,
                    "release_track_mbid": item.release_track_mbid,
                    "medium_position": item.candidate_disc_number,
                    "release_track_position": item.candidate_track_position,
                }
                for item in mapped
            ],
        }
        if decision_source == "automatic":
            # S-1: one dedicated audit row whose source string records the
            # automatic acceptance with reason, ranking inputs, evidence id,
            # prior identity revision, and actor=system (NULL user).
            connection.execute(
                "INSERT INTO library_catalog_actions "
                "(id, actor_user_id, action_kind, local_album_id, operation_job_id, "
                "before_json, after_json, reason_code, created_at) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                (
                    str(uuid.uuid4()),
                    None,
                    "automatic_exact_edition",
                    work["local_album_id"],
                    job_id,
                    json.dumps(
                        {
                            **before,
                            "prior_identity_revision": (
                                int(identity["row_revision"])
                                if identity is not None
                                else None
                            ),
                        },
                        sort_keys=True,
                    ),
                    json.dumps(
                        {
                            **after,
                            "evidence_id": finding["evidence_id"],
                            "gate_reason": "AUTO_ACCEPT",
                            "ranking_inputs": ranking_inputs,
                            "actor": "system",
                        },
                        sort_keys=True,
                    ),
                    evidence.reason_code,
                    now,
                ),
            )
        else:
            connection.execute(
                "INSERT INTO library_catalog_actions "
                "(id, actor_user_id, action_kind, local_album_id, operation_job_id, "
                "before_json, after_json, reason_code, created_at) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                (
                    str(uuid.uuid4()),
                    actor_user_id,
                    "accept_suggested_edition",
                    work["local_album_id"],
                    job_id,
                    json.dumps(before, sort_keys=True),
                    json.dumps(after, sort_keys=True),
                    "SUGGESTED_EDITION_ACCEPTED",
                    now,
                ),
            )
        connection.execute(
            "UPDATE library_identity_repair_findings SET state = 'applied', "
            "apply_result = 'EDITION_ACCEPTED', updated_at = ?, "
            "row_revision = row_revision + 1 WHERE id = ?",
            (now, finding["id"]),
        )
        self._bump_catalog(connection)
        return "succeeded", None

    async def list_repair_findings(
        self,
        job_id: str,
        *,
        limit: int,
        finding_codes: list[str] | None = None,
        cursor_updated_at: float | None = None,
        cursor_id: str | None = None,
        current_only: bool = False,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            params: list[Any] = [job_id]
            finding_filter = ""
            if finding_codes:
                placeholders = ",".join("?" for _ in finding_codes)
                finding_filter = f"AND f.finding_code IN ({placeholders})"
                params.extend(finding_codes)
            cursor = ""
            if cursor_updated_at is not None and cursor_id is not None:
                cursor = "AND (f.updated_at < ? OR (f.updated_at = ? AND f.id < ?))"
                params.extend((cursor_updated_at, cursor_updated_at, cursor_id))
            current_filter = ""
            if current_only:
                # D-EDITION-AUTO: an applied auto-accept stays listed while
                # its undo snapshot is live, so the readiness UI can offer
                # the revisioned undo action.
                current_filter = (
                    "AND ("
                    "(f.state = 'open' "
                    "AND a.row_revision = f.expected_album_revision "
                    "AND ((f.expected_identity_revision IS NULL "
                    "AND identity.row_revision IS NULL) "
                    "OR identity.row_revision = f.expected_identity_revision))"
                    " OR (f.finding_code = 'exact_release_auto_accepted' "
                    "AND f.state = 'applied' "
                    "AND EXISTS (SELECT 1 FROM library_automatic_edition_undo u "
                    "WHERE u.local_album_id = f.local_album_id "
                    "AND u.consumed_at IS NULL))"
                    ")"
                )
            rows = connection.execute(
                "SELECT f.*, a.title AS album_title, "
                "a.album_artist_name, a.year AS album_year, "
                "CASE WHEN artwork.source IS NOT NULL OR identity.release_group_mbid IS NOT NULL "
                "THEN 1 ELSE 0 END AS cover_available, "
                "(SELECT r.id FROM library_identification_reviews r "
                "WHERE r.local_album_id = f.local_album_id ORDER BY r.updated_at DESC, r.id DESC "
                "LIMIT 1) review_id FROM library_identity_repair_findings f "
                "JOIN local_albums a ON a.id = f.local_album_id "
                "LEFT JOIN local_album_artwork artwork ON artwork.local_album_id = a.id "
                "LEFT JOIN local_album_external_identities identity "
                "ON identity.local_album_id = a.id AND identity.provider = 'musicbrainz' "
                "WHERE f.job_id = ? "
                f"{current_filter} {finding_filter} {cursor} "
                "ORDER BY f.updated_at DESC, f.id DESC LIMIT ?",
                (*params, limit + 1),
            ).fetchall()
            count_rows = connection.execute(
                "SELECT f.finding_code, COUNT(*) AS count "
                "FROM library_identity_repair_findings f "
                "JOIN local_albums a ON a.id = f.local_album_id "
                "LEFT JOIN local_album_external_identities identity "
                "ON identity.local_album_id = a.id AND identity.provider = 'musicbrainz' "
                "WHERE f.job_id = ? "
                f"{current_filter} GROUP BY f.finding_code",
                (job_id,),
            ).fetchall()
            snapshot = connection.execute(
                "SELECT target_matcher_version FROM library_repair_snapshots "
                "WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            return {
                "rows": [dict(row) for row in rows[:limit]],
                "has_more": len(rows) > limit,
                "current_counts_by_finding": {
                    str(row["finding_code"]): int(row["count"]) for row in count_rows
                },
                "target_matcher_version": (
                    str(snapshot["target_matcher_version"]) if snapshot else ""
                ),
            }

        return await self._read(operation)

    async def save_migration_dry_run(
        self,
        migration_id: str,
        *,
        source_revision: str,
        root_revision: str,
        report_json: str,
        created_at: float,
    ) -> None:
        def operation(connection: sqlite3.Connection) -> None:
            existing = connection.execute(
                "SELECT source_revision, root_revision, state FROM library_migration_runs WHERE id = ?",
                (migration_id,),
            ).fetchone()
            if existing is not None and (
                existing["source_revision"] != source_revision
                or existing["root_revision"] != root_revision
            ):
                raise StaleRevisionError(
                    "The legacy migration input or library roots changed after this report was created."
                )
            connection.execute(
                "INSERT INTO library_migration_runs "
                "(id, source_revision, root_revision, state, report_json, started_at, updated_at) "
                "VALUES (?, ?, ?, 'dry_run', ?, ?, ?) "
                "ON CONFLICT(id) DO UPDATE SET report_json = excluded.report_json, "
                "updated_at = excluded.updated_at",
                (
                    migration_id,
                    source_revision,
                    root_revision,
                    report_json,
                    created_at,
                    created_at,
                ),
            )

        await self._write(operation)

    async def get_completed_migration_report(
        self,
        migration_id: str,
        *,
        source_revision: str,
        root_revision: str,
    ) -> str | None:
        def operation(connection: sqlite3.Connection) -> str | None:
            run = connection.execute(
                "SELECT source_revision, root_revision, state, report_json "
                "FROM library_migration_runs WHERE id = ?",
                (migration_id,),
            ).fetchone()
            if run is None:
                return None
            if (
                run["source_revision"] != source_revision
                or run["root_revision"] != root_revision
            ):
                raise StaleRevisionError(
                    "The legacy migration input or library roots changed after this report was created."
                )
            if run["state"] != "completed":
                return None
            marker = connection.execute(
                "SELECT source_revision FROM library_migration_markers "
                "WHERE marker = 'legacy_catalog_import_complete'"
            ).fetchone()
            if marker is None or marker["source_revision"] != source_revision:
                raise StaleRevisionError(
                    "The completed migration is missing its matching target marker."
                )
            return str(run["report_json"])

        return await self._read(operation)

    async def require_migration_input(
        self,
        migration_id: str,
        *,
        source_revision: str,
        root_revision: str,
    ) -> None:
        def operation(connection: sqlite3.Connection) -> None:
            run = connection.execute(
                "SELECT source_revision, root_revision FROM library_migration_runs WHERE id = ?",
                (migration_id,),
            ).fetchone()
            if run is None or (
                run["source_revision"] != source_revision
                or run["root_revision"] != root_revision
            ):
                raise StaleRevisionError(
                    "The migration report no longer matches the copied source and library roots."
                )

        await self._read(operation)

    async def apply_legacy_catalog_bundle(
        self,
        bundle: LegacyCatalogImportBundle,
        *,
        migration_run_id: str,
        source_revision: str,
        allow_existing_artists: bool = False,
        allow_existing_album: bool = False,
    ) -> bool:
        """Import one bounded catalog bundle and its provenance atomically."""

        def operation(connection: sqlite3.Connection) -> bool:
            run = connection.execute(
                "SELECT source_revision FROM library_migration_runs WHERE id = ?",
                (migration_run_id,),
            ).fetchone()
            if run is None or run["source_revision"] != source_revision:
                raise StaleRevisionError(
                    "The migration report no longer matches the copied source."
                )
            existing = []
            for provenance in bundle.provenance:
                row = connection.execute(
                    "SELECT target_kind, target_id, source_revision "
                    "FROM library_migration_provenance "
                    "WHERE source_kind = ? AND source_key = ?",
                    (provenance.source_kind, provenance.source_key),
                ).fetchone()
                if row is not None:
                    if (
                        row["target_kind"] != provenance.target_kind
                        or row["target_id"] != provenance.target_id
                        or row["source_revision"] != provenance.source_revision
                    ):
                        raise StaleRevisionError(
                            "A legacy catalog row changed after it was imported."
                        )
                    existing.append(row)
            if existing:
                if len(existing) != len(bundle.provenance):
                    raise StaleRevisionError(
                        "A legacy album import has incomplete provenance."
                    )
                return False

            album = bundle.membership.album
            existing_album = connection.execute(
                "SELECT 1 FROM local_albums WHERE id = ?", (album.id,)
            ).fetchone()
            if existing_album is not None and allow_existing_album:
                owned_album = connection.execute(
                    "SELECT 1 FROM library_migration_provenance p "
                    "JOIN local_tracks t ON t.id = p.target_id "
                    "WHERE p.migration_run_id = ? AND p.target_kind = 'local_track' "
                    "AND t.local_album_id = ? LIMIT 1",
                    (migration_run_id, album.id),
                ).fetchone()
                if owned_album is None:
                    raise StaleRevisionError(
                        "A legacy album collides with catalog data outside this migration."
                    )

            self._insert_catalog_membership(
                connection,
                bundle.membership,
                allow_existing_artists=allow_existing_artists,
                allow_existing_album=allow_existing_album,
            )
            if bundle.album_identity is not None:
                identity = bundle.album_identity
                connection.execute(
                    f"INSERT {'OR IGNORE ' if allow_existing_album else ''}INTO local_album_external_identities "
                    "(local_album_id, provider, release_group_mbid, release_mbid, "
                    "decision_source, matcher_version, attempt_id, selected_by_user_id, "
                    "selected_at, row_revision) VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, ?, ?, ?)",
                    (
                        identity.local_album_id,
                        identity.release_group_mbid,
                        identity.release_mbid,
                        identity.decision_source,
                        identity.matcher_version,
                        identity.attempt_id,
                        identity.selected_by_user_id,
                        identity.selected_at,
                        identity.row_revision,
                    ),
                )
            connection.executemany(
                f"INSERT {'OR IGNORE ' if allow_existing_artists else ''}INTO local_artist_external_identities "
                "(local_artist_id, provider, provider_artist_id, decision_source, attempt_id, "
                "selected_by_user_id, selected_at, row_revision) "
                "VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, ?)",
                [
                    (
                        identity.local_artist_id,
                        identity.provider_artist_id,
                        identity.decision_source,
                        identity.attempt_id,
                        identity.selected_by_user_id,
                        identity.selected_at,
                        identity.row_revision,
                    )
                    for identity in bundle.artist_identities
                ],
            )
            connection.executemany(
                "INSERT INTO local_track_external_identities "
                "(local_track_id, provider, recording_mbid, release_mbid, "
                "release_track_mbid, medium_position, release_track_position, "
                "decision_source, attempt_id, selected_at, row_revision) "
                "VALUES (?, 'musicbrainz', ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    (
                        identity.local_track_id,
                        identity.recording_mbid,
                        identity.release_mbid,
                        identity.release_track_mbid,
                        identity.medium_position,
                        identity.release_track_position,
                        identity.decision_source,
                        identity.attempt_id,
                        identity.selected_at,
                        identity.row_revision,
                    )
                    for identity in bundle.track_identities
                ],
            )
            connection.executemany(
                f"INSERT {'OR IGNORE ' if allow_existing_artists else ''}INTO local_artist_aliases "
                "(alias, local_artist_id, kind, created_at) VALUES (?,?,?,?)",
                [
                    (alias.alias, alias.local_artist_id, alias.kind, alias.created_at)
                    for alias in bundle.artist_aliases
                ],
            )
            connection.executemany(
                f"INSERT {'OR IGNORE ' if allow_existing_album else ''}INTO local_album_aliases "
                "(alias, local_album_id, kind, created_at) VALUES (?,?,?,?)",
                [
                    (alias.alias, alias.local_album_id, alias.kind, alias.created_at)
                    for alias in bundle.album_aliases
                ],
            )
            if bundle.artwork is not None:
                artwork = bundle.artwork
                connection.execute(
                    f"INSERT {'OR IGNORE ' if allow_existing_album else ''}INTO local_album_artwork "
                    "(local_album_id, cover_url, source, source_locator, version, updated_at, row_revision) "
                    "VALUES (?,?,?,?,?,?,?)",
                    (
                        artwork.local_album_id,
                        artwork.cover_url,
                        artwork.source,
                        artwork.source_locator,
                        artwork.version,
                        artwork.updated_at,
                        artwork.row_revision,
                    ),
                )
            connection.executemany(
                "INSERT INTO library_identification_reviews "
                "(id, local_album_id, local_track_id, state, reason_code, input_revision, "
                "created_at, updated_at, decided_at) VALUES (?,?,?,?,?,?,?,?,?)",
                [
                    (
                        review.id,
                        review.local_album_id,
                        review.local_track_id,
                        review.state,
                        review.reason_code,
                        review.input_revision,
                        review.created_at,
                        review.updated_at,
                        review.decided_at,
                    )
                    for review in bundle.reviews
                ],
            )
            if any(
                not self._migration_reference_matches(connection, provenance)
                for provenance in bundle.provenance
            ):
                raise StaleRevisionError(
                    "A migrated catalog row was not materialized as planned."
                )
            connection.executemany(
                "INSERT INTO library_migration_provenance "
                "(source_kind, source_key, target_kind, target_id, source_revision, "
                "imported_at, migration_run_id) VALUES (?,?,?,?,?,?,?)",
                [
                    (
                        provenance.source_kind,
                        provenance.source_key,
                        provenance.target_kind,
                        provenance.target_id,
                        provenance.source_revision,
                        provenance.imported_at,
                        migration_run_id,
                    )
                    for provenance in bundle.provenance
                ],
            )
            self._bump_catalog(connection)
            return True

        return await self._write(operation)

    async def apply_reference_provenance_batch(
        self,
        provenance_rows: list[MigrationProvenance],
        *,
        migration_run_id: str,
        source_revision: str,
        tombstones: list[MigrationTombstone] | None = None,
        copy_playlists: bool = True,
    ) -> int:
        def operation(connection: sqlite3.Connection) -> int:
            def row_value(row: sqlite3.Row, key: str) -> Any:
                return row[key] if key in row.keys() else None

            def stable_membership(
                target_kind: str, target_id: str
            ) -> tuple[str | None, str | None, str | None]:
                if target_kind == "local_track":
                    row = connection.execute(
                        "SELECT t.id AS track_id, t.local_album_id AS album_id, "
                        "COALESCE(ta.local_artist_id, a.album_artist_id) AS artist_id "
                        "FROM local_tracks t "
                        "JOIN local_albums a ON a.id = t.local_album_id "
                        "LEFT JOIN local_track_artists ta "
                        "ON ta.local_track_id = t.id AND ta.position = 0 "
                        "WHERE t.id = ?",
                        (target_id,),
                    ).fetchone()
                    if row is not None:
                        return row["track_id"], row["album_id"], row["artist_id"]
                elif target_kind == "local_album":
                    row = connection.execute(
                        "SELECT id, album_artist_id FROM local_albums WHERE id = ?",
                        (target_id,),
                    ).fetchone()
                    if row is not None:
                        return None, row["id"], row["album_artist_id"]
                elif target_kind == "local_artist":
                    return None, None, target_id
                return None, None, None

            def materialize_reference(provenance: MigrationProvenance) -> None:
                track_id, album_id, artist_id = stable_membership(
                    provenance.target_kind, provenance.target_id
                )
                if provenance.source_kind == "favorite":
                    user_id, item_kind, source_item_id = provenance.source_key.split(
                        ":", 2
                    )
                    connection.execute(
                        "INSERT OR IGNORE INTO library_user_favorites "
                        "(user_id, item_kind, item_id, created_at) "
                        "SELECT user_id, item_kind, ?, created_at FROM user_favorites "
                        "WHERE user_id = ? AND item_kind = ? AND item_id = ?",
                        (
                            provenance.target_id,
                            user_id,
                            item_kind,
                            source_item_id,
                        ),
                    )
                elif provenance.source_kind == "history":
                    source = connection.execute(
                        "SELECT * FROM play_history WHERE id = ?",
                        (provenance.source_key,),
                    ).fetchone()
                    if source is None:
                        return
                    connection.execute(
                        "INSERT INTO library_play_history "
                        "(id, user_id, local_track_id, local_album_id, local_artist_id, "
                        "track_name, artist_name, album_name, recording_mbid, "
                        "release_group_mbid, duration_ms, source, played_at) "
                        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) "
                        "ON CONFLICT(id) DO UPDATE SET "
                        "local_track_id = excluded.local_track_id, "
                        "local_album_id = excluded.local_album_id, "
                        "local_artist_id = excluded.local_artist_id",
                        (
                            source["id"],
                            source["user_id"],
                            track_id,
                            album_id,
                            artist_id,
                            source["track_name"],
                            source["artist_name"],
                            row_value(source, "album_name"),
                            row_value(source, "recording_mbid"),
                            row_value(source, "release_group_mbid"),
                            row_value(source, "duration_ms"),
                            row_value(source, "source"),
                            source["played_at"],
                        ),
                    )
                elif provenance.source_kind == "playlist_track":
                    source = connection.execute(
                        "SELECT * FROM playlist_tracks WHERE id = ?",
                        (provenance.source_key,),
                    ).fetchone()
                    if source is None:
                        return
                    connection.execute(
                        "INSERT OR IGNORE INTO library_playlist_tracks "
                        "(id, playlist_id, position, track_name, artist_name, album_name, "
                        "album_id, artist_id, track_source_id, cover_url, source_type, "
                        "available_sources, format, track_number, disc_number, duration, "
                        "created_at, plex_rating_key, library_file_id, local_track_id, "
                        "local_album_id, local_artist_id, reference_tombstone_id) "
                        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        (
                            source["id"],
                            source["playlist_id"],
                            source["position"],
                            source["track_name"],
                            source["artist_name"],
                            source["album_name"],
                            row_value(source, "album_id"),
                            row_value(source, "artist_id"),
                            row_value(source, "track_source_id"),
                            row_value(source, "cover_url"),
                            source["source_type"],
                            row_value(source, "available_sources"),
                            row_value(source, "format"),
                            row_value(source, "track_number"),
                            row_value(source, "disc_number"),
                            row_value(source, "duration"),
                            source["created_at"],
                            row_value(source, "plex_rating_key"),
                            row_value(source, "library_file_id"),
                            track_id,
                            album_id,
                            artist_id,
                            provenance.target_id
                            if provenance.target_kind == "reference_tombstone"
                            else None,
                        ),
                    )
                elif provenance.source_kind == "album_release_pin":
                    connection.execute(
                        "INSERT OR IGNORE INTO library_album_release_pins "
                        "(local_album_id, release_group_mbid, release_mbid, "
                        "set_by_user_id, set_at) "
                        "SELECT ?, release_group_mbid, release_mbid, set_by_user_id, "
                        "set_at FROM album_release_pins WHERE release_group_mbid = ?",
                        (album_id, provenance.source_key),
                    )
                elif provenance.source_kind == "compat_bookmark" and track_id:
                    user_id, source_file_id = provenance.source_key.split(":", 1)
                    connection.execute(
                        "INSERT OR IGNORE INTO library_compat_bookmarks "
                        "(user_id, local_track_id, position_ms, comment, created_at, changed_at) "
                        "SELECT user_id, ?, position_ms, comment, created_at, changed_at "
                        "FROM compat_bookmarks WHERE user_id = ? AND file_id = ?",
                        (track_id, user_id, source_file_id),
                    )
                elif provenance.source_kind == "compat_play_queue":
                    connection.execute(
                        "INSERT OR IGNORE INTO library_compat_play_queues "
                        "(user_id, current_index, position_ms, updated_at, changed_by_client) "
                        "SELECT user_id, current_index, position_ms, updated_at, "
                        "changed_by_client FROM compat_play_queues WHERE user_id = ?",
                        (provenance.source_key,),
                    )
                elif provenance.source_kind == "compat_play_queue_item" and track_id:
                    user_id, item_index = provenance.source_key.rsplit(":", 1)
                    connection.execute(
                        "INSERT OR IGNORE INTO library_compat_play_queue_items "
                        "(user_id, item_index, local_track_id) VALUES (?, ?, ?)",
                        (user_id, int(item_index), track_id),
                    )
                elif provenance.source_kind == "jellyfin_id_map":
                    if provenance.target_kind == "reference_tombstone":
                        source = connection.execute(
                            "SELECT kind, internal_id FROM compat_id_map WHERE jf_id = ?",
                            (provenance.source_key,),
                        ).fetchone()
                        if source is None:
                            return
                        kind = str(source["kind"])
                        internal_id = str(source["internal_id"])
                    else:
                        kind = {
                            "local_artist": "artist",
                            "local_album": "album",
                            "local_track": "track",
                        }.get(provenance.target_kind, provenance.target_kind)
                        internal_id = provenance.target_id
                    connection.execute(
                        "INSERT OR IGNORE INTO library_compat_id_map "
                        "(jf_id, kind, internal_id) VALUES (?, ?, ?)",
                        (provenance.source_key, kind, internal_id),
                    )

            run = connection.execute(
                "SELECT source_revision FROM library_migration_runs WHERE id = ?",
                (migration_run_id,),
            ).fetchone()
            if run is None or run["source_revision"] != source_revision:
                raise StaleRevisionError(
                    "The migration report no longer matches the copied source."
                )
            if copy_playlists:
                playlist_columns = {
                    str(row["name"])
                    for row in connection.execute(
                        "PRAGMA table_info(playlists)"
                    ).fetchall()
                }
                connection.execute(
                    "INSERT OR IGNORE INTO library_playlists "
                    "(id, name, cover_image_path, created_at, updated_at, source_ref, "
                    "user_id, is_public) "
                    "SELECT id, name, "
                    f"{'cover_image_path' if 'cover_image_path' in playlist_columns else 'NULL'}, "
                    "created_at, updated_at, "
                    f"{'source_ref' if 'source_ref' in playlist_columns else 'NULL'}, "
                    f"{'user_id' if 'user_id' in playlist_columns else 'NULL'}, "
                    f"{'COALESCE(is_public, 0)' if 'is_public' in playlist_columns else '0'} "
                    "FROM playlists"
                )
            inserted = 0
            for tombstone in tombstones or []:
                connection.execute(
                    "INSERT INTO library_reference_tombstones "
                    "(id, source_kind, source_key, legacy_file_id, title, artist_name, "
                    "album_name, source_type, created_at) VALUES (?,?,?,?,?,?,?,?,?) "
                    "ON CONFLICT(source_kind, source_key) DO NOTHING",
                    (
                        tombstone.id,
                        tombstone.source_kind,
                        tombstone.source_key,
                        tombstone.legacy_file_id,
                        tombstone.title,
                        tombstone.artist_name,
                        tombstone.album_name,
                        tombstone.source_type,
                        tombstone.created_at,
                    ),
                )
            for provenance in provenance_rows:
                materialize_reference(provenance)
                if not self._migration_reference_matches(connection, provenance):
                    raise StaleRevisionError(
                        "A persisted legacy reference was not materialized as planned."
                    )
                existing = connection.execute(
                    "SELECT target_kind, target_id, source_revision "
                    "FROM library_migration_provenance "
                    "WHERE source_kind = ? AND source_key = ?",
                    (provenance.source_kind, provenance.source_key),
                ).fetchone()
                if existing is not None:
                    if (
                        existing["target_kind"] != provenance.target_kind
                        or existing["target_id"] != provenance.target_id
                        or existing["source_revision"] != provenance.source_revision
                    ):
                        raise StaleRevisionError(
                            "A persisted legacy reference changed after it was imported."
                        )
                    continue
                connection.execute(
                    "INSERT INTO library_migration_provenance "
                    "(source_kind, source_key, target_kind, target_id, source_revision, "
                    "imported_at, migration_run_id) VALUES (?,?,?,?,?,?,?)",
                    (
                        provenance.source_kind,
                        provenance.source_key,
                        provenance.target_kind,
                        provenance.target_id,
                        provenance.source_revision,
                        provenance.imported_at,
                        migration_run_id,
                    ),
                )
                inserted += 1
            return inserted

        return await self._write(operation)

    async def materialize_unlinked_history_batch(
        self,
        rows: list[dict[str, Any]],
        *,
        migration_run_id: str,
        source_revision: str,
    ) -> None:
        """Retain legacy play history rows that cannot resolve to a track.

        NULL linkage matches the runtime write path for plays outside the
        local catalog. No provenance is recorded; these are retained data,
        not migrated references.
        """
        if not rows:
            return

        def operation(connection: sqlite3.Connection) -> None:
            run = connection.execute(
                "SELECT source_revision FROM library_migration_runs WHERE id = ?",
                (migration_run_id,),
            ).fetchone()
            if run is None or run["source_revision"] != source_revision:
                raise StaleRevisionError(
                    "The migration report no longer matches the copied source."
                )

            def row_value(row: sqlite3.Row, key: str) -> Any:
                return row[key] if key in row.keys() else None

            for row in rows:
                source = connection.execute(
                    "SELECT * FROM play_history WHERE id = ?",
                    (str(row.get("id")),),
                ).fetchone()
                if source is None:
                    continue
                connection.execute(
                    "INSERT OR IGNORE INTO library_play_history "
                    "(id, user_id, local_track_id, local_album_id, local_artist_id, "
                    "track_name, artist_name, album_name, recording_mbid, "
                    "release_group_mbid, duration_ms, source, played_at) "
                    "VALUES (?,?,NULL,NULL,NULL,?,?,?,?,?,?,?,?)",
                    (
                        source["id"],
                        source["user_id"],
                        source["track_name"],
                        source["artist_name"],
                        row_value(source, "album_name"),
                        row_value(source, "recording_mbid"),
                        row_value(source, "release_group_mbid"),
                        row_value(source, "duration_ms"),
                        row_value(source, "source"),
                        source["played_at"],
                    ),
                )

        await self._write(operation)

    async def finish_migration(
        self,
        migration_id: str,
        *,
        source_revision: str,
        report_json: str,
        completed_at: float,
    ) -> int:
        def operation(connection: sqlite3.Connection) -> int:
            existing = connection.execute(
                "SELECT source_revision, state FROM library_migration_runs WHERE id = ?",
                (migration_id,),
            ).fetchone()
            if (
                existing is not None
                and existing["source_revision"] == source_revision
                and existing["state"] == "completed"
            ):
                marker = connection.execute(
                    "SELECT target_catalog_revision FROM library_migration_markers "
                    "WHERE marker = 'legacy_catalog_import_complete'"
                ).fetchone()
                if marker is None:
                    raise StaleRevisionError(
                        "The completed migration is missing its target marker."
                    )
                return int(marker["target_catalog_revision"])
            run = connection.execute(
                "UPDATE library_migration_runs SET state = 'completed', report_json = ?, "
                "updated_at = ?, completed_at = ?, row_revision = row_revision + 1 "
                "WHERE id = ? AND source_revision = ? AND state IN ('dry_run','applying') "
                "AND row_revision < ? RETURNING row_revision",
                (
                    report_json,
                    completed_at,
                    completed_at,
                    migration_id,
                    source_revision,
                    MAX_REVISION,
                ),
            ).fetchone()
            if run is None:
                self._refuse_max_revision(
                    connection,
                    table="library_migration_runs",
                    predicate="id = ?",
                    parameters=(migration_id,),
                )
                raise StaleRevisionError(
                    "The migration input changed before completion was recorded."
                )
            catalog_revision = self._bump_catalog(connection)
            connection.execute(
                "INSERT INTO library_migration_markers "
                "(marker, source_revision, target_catalog_revision, created_at) "
                "VALUES ('legacy_catalog_import_complete', ?, ?, ?) "
                "ON CONFLICT(marker) DO UPDATE SET source_revision = excluded.source_revision, "
                "target_catalog_revision = excluded.target_catalog_revision, "
                "created_at = excluded.created_at",
                (source_revision, catalog_revision, completed_at),
            )
            return catalog_revision

        return await self._write(operation)

    async def record_migration_provenance(
        self, provenance: MigrationProvenance, *, migration_run_id: str | None = None
    ) -> bool:
        def operation(connection: sqlite3.Connection) -> bool:
            existing = connection.execute(
                "SELECT target_kind, target_id, source_revision "
                "FROM library_migration_provenance WHERE source_kind = ? AND source_key = ?",
                (provenance.source_kind, provenance.source_key),
            ).fetchone()
            if existing is not None:
                if (
                    existing["target_kind"] == provenance.target_kind
                    and existing["target_id"] == provenance.target_id
                    and existing["source_revision"] == provenance.source_revision
                ):
                    return False
                raise StaleRevisionError(
                    "A legacy migration source changed after it was imported."
                )
            cursor = connection.execute(
                "INSERT INTO library_migration_provenance "
                "(source_kind, source_key, target_kind, target_id, source_revision, "
                "imported_at, migration_run_id) VALUES (?,?,?,?,?,?,?) "
                "ON CONFLICT(source_kind, source_key) DO NOTHING",
                (
                    provenance.source_kind,
                    provenance.source_key,
                    provenance.target_kind,
                    provenance.target_id,
                    provenance.source_revision,
                    provenance.imported_at,
                    migration_run_id,
                ),
            )
            return cursor.rowcount == 1

        return await self._write(operation)

    async def resolve_migrated_reference(
        self, source_kind: str, source_key: str
    ) -> tuple[str, str] | None:
        def operation(connection: sqlite3.Connection) -> tuple[str, str] | None:
            row = connection.execute(
                "SELECT target_kind, target_id FROM library_migration_provenance "
                "WHERE source_kind = ? AND source_key = ?",
                (source_kind, source_key),
            ).fetchone()
            return (
                (str(row["target_kind"]), str(row["target_id"]))
                if row is not None
                else None
            )

        return await self._read(operation)

    @staticmethod
    def _foreign_key_schema_sha256(connection: sqlite3.Connection) -> str:
        tables = connection.execute(
            "SELECT name, sql FROM sqlite_master WHERE type = 'table' "
            "AND name NOT LIKE 'sqlite_%' ORDER BY name"
        ).fetchall()
        payload = {
            "sqlite_version": sqlite3.sqlite_version,
            "validator_revision": _FOREIGN_KEY_VALIDATION_REVISION,
            "tables": [(str(row["name"]), str(row["sql"])) for row in tables],
        }
        return hashlib.sha256(
            json.dumps(payload, separators=(",", ":"), sort_keys=True).encode()
        ).hexdigest()

    @staticmethod
    def _catalog_integrity_counts(
        connection: sqlite3.Connection,
    ) -> dict[str, int]:
        mmap_row = connection.execute(
            f"PRAGMA mmap_size={_CATALOG_VALIDATION_MMAP_BYTES}"
        ).fetchone()
        mmap_bytes = int(mmap_row[0]) if mmap_row is not None else 0
        connection.execute("BEGIN IMMEDIATE")
        database_pages = int(connection.execute("PRAGMA page_count").fetchone()[0])
        schema_sha256 = NativeLibraryStore._foreign_key_schema_sha256(connection)
        validation_state = connection.execute(
            "SELECT schema_sha256, validator_revision, clean "
            "FROM library_foreign_key_validation_state WHERE singleton = 1"
        ).fetchone()
        foreign_key_cache_hit = bool(
            validation_state is not None
            and int(validation_state["clean"]) == 1
            and int(validation_state["validator_revision"])
            == _FOREIGN_KEY_VALIDATION_REVISION
            and str(validation_state["schema_sha256"]) == schema_sha256
        )

        def measured_count(
            clause: str,
            operation: Callable[[], tuple[int, int]],
            *,
            validation_mode: str = "full",
        ) -> int:
            started = time.perf_counter()
            result, subject_rows = operation()
            logger.info(
                "target_startup.catalog_integrity_clause clause=%s elapsed_ms=%.3f "
                "result_count=%d subject_rows=%d database_pages=%d mmap_bytes=%d "
                "validation_mode=%s",
                clause,
                (time.perf_counter() - started) * 1000,
                result,
                subject_rows,
                database_pages,
                mmap_bytes,
                validation_mode,
            )
            return result

        def count_pair(statement: str) -> tuple[int, int]:
            row = connection.execute(statement).fetchone()
            return int(row[0]), int(row[1])

        def foreign_key_violations() -> tuple[int, int]:
            if foreign_key_cache_hit:
                return 0, -1
            violations = sum(
                1 for _row in connection.execute("PRAGMA foreign_key_check")
            )
            connection.execute(
                "UPDATE library_foreign_key_validation_state "
                "SET schema_sha256 = ?, validator_revision = ?, clean = ?, "
                "validated_at = CASE WHEN ? = 0 THEN ? ELSE NULL END "
                "WHERE singleton = 1",
                (
                    schema_sha256,
                    _FOREIGN_KEY_VALIDATION_REVISION,
                    int(violations == 0),
                    violations,
                    time.time(),
                ),
            )
            return violations, -1

        return {
            "foreign_key_violations": measured_count(
                "foreign_key_violations",
                foreign_key_violations,
                validation_mode="cached" if foreign_key_cache_hit else "full",
            ),
            "orphan_tracks": measured_count(
                "orphan_tracks",
                lambda: count_pair(
                    "SELECT COALESCE(SUM(a.id IS NULL), 0), COUNT(*) "
                    "FROM local_tracks t LEFT JOIN local_albums a "
                    "ON a.id = t.local_album_id"
                ),
            ),
            "duplicate_paths": measured_count(
                "duplicate_paths",
                lambda: count_pair(
                    "SELECT COALESCE(SUM(group_size > 1), 0), "
                    "COALESCE(SUM(group_size), 0) FROM ("
                    "SELECT COUNT(*) AS group_size FROM local_tracks "
                    "GROUP BY root_id, relative_path)"
                ),
            ),
            "unresolved_provenance": measured_count(
                "unresolved_provenance",
                lambda: count_pair(
                    "SELECT COALESCE(SUM(target_id IS NULL OR target_id = ''), 0), "
                    "COUNT(*) FROM library_migration_provenance"
                ),
            ),
        }

    async def validate_catalog_integrity(self) -> dict[str, int]:
        return await self._write(self._catalog_integrity_counts)

    async def validate_migration_references(self) -> int:
        def operation(connection: sqlite3.Connection) -> int:
            return int(
                connection.execute(
                    "SELECT COUNT(*) FROM library_migration_provenance p WHERE NOT ("
                    "CASE p.target_kind "
                    "WHEN 'library_root' THEN p.source_kind = 'root' AND p.target_id != '' "
                    "WHEN 'library' THEN p.source_kind = 'jellyfin_id_map' AND p.target_id != '' "
                    "WHEN 'genre' THEN p.source_kind = 'jellyfin_id_map' AND p.target_id != '' "
                    "WHEN 'compat_play_queue' THEN EXISTS ("
                    "SELECT 1 FROM library_compat_play_queues q WHERE q.user_id = p.target_id) "
                    "WHEN 'local_track' THEN EXISTS ("
                    "SELECT 1 FROM local_tracks t WHERE t.id = p.target_id) "
                    "WHEN 'local_album' THEN EXISTS ("
                    "SELECT 1 FROM local_albums a WHERE a.id = p.target_id) "
                    "WHEN 'local_artist' THEN EXISTS ("
                    "SELECT 1 FROM local_artists a WHERE a.id = p.target_id) "
                    "WHEN 'playlist' THEN EXISTS ("
                    "SELECT 1 FROM library_playlists l WHERE l.id = p.target_id) "
                    "WHEN 'reference_tombstone' THEN EXISTS ("
                    "SELECT 1 FROM library_reference_tombstones t WHERE t.id = p.target_id) "
                    "ELSE 0 END "
                    "AND CASE p.source_kind "
                    "WHEN 'favorite' THEN EXISTS ("
                    "SELECT 1 FROM library_user_favorites f WHERE "
                    "f.user_id = SUBSTR(p.source_key, 1, INSTR(p.source_key, ':') - 1) "
                    "AND f.item_kind = SUBSTR("
                    "p.source_key, INSTR(p.source_key, ':') + 1, "
                    "INSTR(SUBSTR(p.source_key, INSTR(p.source_key, ':') + 1), ':') - 1) "
                    "AND f.item_id = p.target_id) "
                    "WHEN 'history' THEN EXISTS ("
                    "SELECT 1 FROM library_play_history h WHERE h.id = p.source_key AND ("
                    "(p.target_kind = 'local_track' AND h.local_track_id = p.target_id) OR "
                    "(p.target_kind = 'local_album' AND h.local_album_id = p.target_id) OR "
                    "(p.target_kind = 'local_artist' AND h.local_artist_id = p.target_id))) "
                    "WHEN 'playlist_track' THEN EXISTS ("
                    "SELECT 1 FROM library_playlist_tracks t WHERE t.id = p.source_key AND ("
                    "(p.target_kind = 'local_track' AND t.local_track_id = p.target_id) OR "
                    "(p.target_kind = 'local_album' AND t.local_album_id = p.target_id) OR "
                    "(p.target_kind = 'local_artist' AND t.local_artist_id = p.target_id) OR "
                    "(p.target_kind = 'reference_tombstone' "
                    "AND t.reference_tombstone_id = p.target_id))) "
                    "WHEN 'album_release_pin' THEN EXISTS ("
                    "SELECT 1 FROM library_album_release_pins r "
                    "WHERE r.local_album_id = p.target_id "
                    "AND r.release_group_mbid = p.source_key) "
                    "WHEN 'compat_bookmark' THEN EXISTS ("
                    "SELECT 1 FROM library_compat_bookmarks b WHERE "
                    "b.user_id = SUBSTR(p.source_key, 1, INSTR(p.source_key, ':') - 1) "
                    "AND b.local_track_id = p.target_id) "
                    "WHEN 'compat_play_queue' THEN p.source_key = p.target_id "
                    "WHEN 'compat_play_queue_item' THEN EXISTS ("
                    "SELECT 1 FROM library_compat_play_queue_items i "
                    "WHERE i.user_id = SUBSTR(p.source_key, 1, INSTR(p.source_key, ':') - 1) "
                    "AND i.item_index = CAST(SUBSTR("
                    "p.source_key, INSTR(p.source_key, ':') + 1) AS INTEGER) "
                    "AND p.source_key = i.user_id || ':' || i.item_index "
                    "AND i.local_track_id = p.target_id) "
                    "WHEN 'jellyfin_id_map' THEN EXISTS ("
                    "SELECT 1 FROM library_compat_id_map m WHERE m.jf_id = p.source_key "
                    "AND ((p.target_kind = 'reference_tombstone' AND EXISTS ("
                    "SELECT 1 FROM compat_id_map s WHERE s.jf_id = p.source_key "
                    "AND s.kind = m.kind AND s.internal_id = m.internal_id)) OR "
                    "(p.target_kind != 'reference_tombstone' "
                    "AND m.internal_id = p.target_id AND m.kind = CASE p.target_kind "
                    "WHEN 'local_artist' THEN 'artist' WHEN 'local_album' THEN 'album' "
                    "WHEN 'local_track' THEN 'track' ELSE p.target_kind END))) "
                    "WHEN 'review_row' THEN EXISTS ("
                    "SELECT 1 FROM library_identification_reviews r "
                    "WHERE r.local_track_id = p.target_id AND r.reason_code LIKE 'legacy_%') "
                    "WHEN 'manual_decision' THEN EXISTS ("
                    "SELECT 1 FROM library_identification_reviews r "
                    "WHERE r.local_track_id = p.target_id AND r.reason_code LIKE 'legacy_%') "
                    "WHEN 'native_album_alias' THEN EXISTS ("
                    "SELECT 1 FROM local_album_aliases a WHERE a.alias = p.source_key "
                    "AND a.local_album_id = p.target_id) "
                    "WHEN 'native_artist_alias' THEN EXISTS ("
                    "SELECT 1 FROM local_artist_aliases a WHERE a.alias = p.source_key "
                    "AND a.local_artist_id = p.target_id) "
                    "WHEN 'artwork_reference' THEN EXISTS ("
                    "SELECT 1 FROM local_album_artwork a WHERE a.local_album_id = p.target_id) "
                    "WHEN 'root' THEN 1 WHEN 'library_file' THEN 1 "
                    "WHEN 'subsonic_id' THEN 1 ELSE 0 END)"
                ).fetchone()[0]
            )

        return await self._read(operation)

    async def validate_migrated_catalog(self) -> dict[str, int]:
        invariants = await self.validate_catalog_integrity()
        unresolved_references = await self.validate_migration_references()
        return {**invariants, "unresolved_references": unresolved_references}

    async def get_target_startup_state(self) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            marker = connection.execute(
                "SELECT source_revision, target_catalog_revision, created_at "
                "FROM library_migration_markers "
                "WHERE marker = 'legacy_catalog_import_complete'"
            ).fetchone()
            migration = None
            if marker is not None:
                migration = connection.execute(
                    "SELECT id, state, source_revision, completed_at "
                    "FROM library_migration_runs WHERE source_revision = ? "
                    "ORDER BY completed_at DESC, id DESC LIMIT 1",
                    (marker["source_revision"],),
                ).fetchone()
            catalog_revision = int(
                connection.execute(
                    "SELECT value FROM library_catalog_revision WHERE singleton = 1"
                ).fetchone()[0]
            )
            return {
                "marker": dict(marker) if marker is not None else None,
                "migration": dict(migration) if migration is not None else None,
                "catalog_revision": catalog_revision,
            }

        return await self._read(operation)

    async def get_migrated_root_ids(self) -> set[str]:
        def operation(connection: sqlite3.Connection) -> set[str]:
            return {
                str(row["target_id"])
                for row in connection.execute(
                    "SELECT target_id FROM library_migration_provenance "
                    "WHERE source_kind = 'root' AND target_kind = 'library_root'"
                ).fetchall()
            }

        return await self._read(operation)

    async def get_migrated_legacy_source_keys(
        self, kinds: set[str] | None = None
    ) -> dict[str, set[str]]:
        """Return provenance source keys per kind for already-migrated legacy rows."""

        def operation(connection: sqlite3.Connection) -> dict[str, set[str]]:
            result: dict[str, set[str]] = {}
            query = "SELECT source_kind, source_key FROM library_migration_provenance"
            parameters: tuple[object, ...] = ()
            if kinds:
                placeholders = ",".join("?" for _ in kinds)
                query += f" WHERE source_kind IN ({placeholders})"
                parameters = tuple(sorted(kinds))
            for row in connection.execute(query, parameters):
                result.setdefault(str(row["source_kind"]), set()).add(
                    str(row["source_key"])
                )
            return result

        return await self._read(operation)

    async def has_completed_legacy_migration_marker(self) -> bool:
        def operation(connection: sqlite3.Connection) -> bool:
            present = connection.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' "
                "AND name = 'library_migration_markers'"
            ).fetchone()
            if present is None:
                return False
            return (
                connection.execute(
                    "SELECT 1 FROM library_migration_markers "
                    "WHERE marker = 'legacy_catalog_import_complete'"
                ).fetchone()
                is not None
            )

        return await self._read(operation)

    async def get_migration_run_state(self, migration_id: str) -> str | None:
        def operation(connection: sqlite3.Connection) -> str | None:
            row = connection.execute(
                "SELECT state FROM library_migration_runs WHERE id = ?",
                (migration_id,),
            ).fetchone()
            return str(row["state"]) if row is not None else None

        return await self._read(operation)

    async def get_existing_local_track_paths(self, paths: list[str]) -> set[str]:
        """Return the subset of paths already owned by local_tracks rows."""

        def operation(connection: sqlite3.Connection) -> set[str]:
            present = connection.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'local_tracks'"
            ).fetchone()
            if present is None or not paths:
                return set()
            existing: set[str] = set()
            for start in range(0, len(paths), 500):
                chunk = paths[start : start + 500]
                placeholders = ",".join("?" for _ in chunk)
                existing.update(
                    str(row[0])
                    for row in connection.execute(
                        f"SELECT file_path FROM local_tracks WHERE file_path IN ({placeholders})",
                        tuple(chunk),
                    )
                )
            return existing

        return await self._read(operation)

    async def get_pending_legacy_counts(self) -> dict[str, int]:
        """Count legacy rows that have no migration provenance yet."""

        def operation(connection: sqlite3.Connection) -> dict[str, int]:
            pending: dict[str, int] = {}

            def count_absent(
                table: str, kind: str, *, active_only: bool = False
            ) -> int:
                present = connection.execute(
                    "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?",
                    (table,),
                ).fetchone()
                if present is None:
                    return 0
                clause = "WHERE deleted_at IS NULL" if active_only else ""
                legacy = int(
                    connection.execute(
                        f"SELECT COUNT(*) FROM {table} {clause}"
                    ).fetchone()[0]
                )
                migrated = int(
                    connection.execute(
                        "SELECT COUNT(*) FROM library_migration_provenance "
                        "WHERE source_kind = ?",
                        (kind,),
                    ).fetchone()[0]
                )
                return max(0, legacy - migrated)

            pending["library_file"] = count_absent(
                "library_files", "library_file", active_only=True
            )
            pending["review_row"] = count_absent("manual_review_queue", "review_row")
            for table, kind in (
                ("user_favorites", "favorite"),
                ("play_history", "history"),
                ("playlist_tracks", "playlist_track"),
                ("album_release_pins", "album_release_pin"),
                ("compat_bookmarks", "compat_bookmark"),
                ("compat_play_queues", "compat_play_queue"),
                ("compat_play_queue_items", "compat_play_queue_item"),
                ("compat_id_map", "jellyfin_id_map"),
            ):
                pending[kind] = count_absent(table, kind)
            return pending

        return await self._read(operation)

    async def catalog_has_tracks(self) -> bool:
        def operation(connection: sqlite3.Connection) -> bool:
            return (
                connection.execute("SELECT 1 FROM local_tracks LIMIT 1").fetchone()
                is not None
            )

        return await self._read(operation)

    async def get_restorable_root_paths(
        self, root_ids: list[str]
    ) -> dict[str, dict[str, object]]:
        """Recover a removed root's path from its catalog tracks.

        The migration stores root IDs but not paths. The common ancestor of
        the sampled files' parents is a heuristic: a root whose tracks all sit
        in one directory tree comes back one level too deep.
        """
        if not root_ids:
            return {}

        def operation(
            connection: sqlite3.Connection,
        ) -> dict[str, dict[str, object]]:
            placeholders = ", ".join("?" for _ in root_ids)
            sampled = connection.execute(
                "SELECT root_id, file_path FROM ("
                "SELECT root_id, file_path, "
                "ROW_NUMBER() OVER (PARTITION BY root_id ORDER BY file_path) AS rn "
                f"FROM local_tracks WHERE root_id IN ({placeholders})) "
                "WHERE rn <= 500",
                root_ids,
            ).fetchall()
            counts = dict(
                connection.execute(
                    f"SELECT root_id, COUNT(*) FROM local_tracks "
                    f"WHERE root_id IN ({placeholders}) GROUP BY root_id",
                    root_ids,
                ).fetchall()
            )
            paths_by_root: dict[str, list[Path]] = {}
            for row in sampled:
                paths_by_root.setdefault(str(row["root_id"]), []).append(
                    Path(str(row["file_path"])).parent
                )
            restored: dict[str, dict[str, object]] = {}
            for root_id, parents in paths_by_root.items():
                try:
                    common = os.path.commonpath(parents)
                except ValueError:
                    continue
                restored[root_id] = {
                    "path": str(common),
                    "indexed_file_count": int(counts[root_id]),
                }
            return restored

        return await self._read(operation)

    async def get_migration_provenance_counts(
        self, migration_run_id: str
    ) -> dict[str, int]:
        def operation(connection: sqlite3.Connection) -> dict[str, int]:
            return {
                str(row["source_kind"]): int(row["count"])
                for row in connection.execute(
                    "SELECT source_kind, COUNT(*) AS count "
                    "FROM library_migration_provenance WHERE migration_run_id = ? "
                    "GROUP BY source_kind",
                    (migration_run_id,),
                ).fetchall()
            }

        return await self._read(operation)

    async def get_bounded_migrated_artist_count(self) -> int:
        def operation(connection: sqlite3.Connection) -> int:
            return int(
                connection.execute(
                    "SELECT COUNT(*) FROM local_artists WHERE id NOT IN (?, ?)",
                    (VARIOUS_ARTISTS_ID, UNKNOWN_ARTIST_ID),
                ).fetchone()[0]
            )

        return await self._read(operation)

    async def get_bounded_migrated_catalog_counts(self) -> dict[str, int]:
        def operation(connection: sqlite3.Connection) -> dict[str, int]:
            identified_albums = int(
                connection.execute(
                    "SELECT COUNT(*) FROM local_albums a WHERE EXISTS ("
                    "SELECT 1 FROM local_album_external_identities e "
                    "WHERE e.local_album_id = a.id AND e.provider = 'musicbrainz')"
                ).fetchone()[0]
            )
            identified_tracks = int(
                connection.execute(
                    "SELECT COUNT(*) FROM local_tracks t WHERE EXISTS ("
                    "SELECT 1 FROM local_album_external_identities e "
                    "WHERE e.local_album_id = t.local_album_id "
                    "AND e.provider = 'musicbrainz')"
                ).fetchone()[0]
            )
            albums = int(
                connection.execute("SELECT COUNT(*) FROM local_albums").fetchone()[0]
            )
            tracks = int(
                connection.execute("SELECT COUNT(*) FROM local_tracks").fetchone()[0]
            )
            return {
                "identified_albums": identified_albums,
                "identified_tracks": identified_tracks,
                "local_only_albums": albums - identified_albums,
                "local_only_tracks": tracks - identified_tracks,
            }

        return await self._read(operation)

    async def get_policy_scope_counts(
        self, scopes: list[tuple[str, str]]
    ) -> dict[tuple[str, str], tuple[int, int]]:
        def operation(
            connection: sqlite3.Connection,
        ) -> dict[tuple[str, str], tuple[int, int]]:
            requested = [
                {
                    "root_id": root_id,
                    "relative_path": relative_path,
                    "prefix": relative_path.strip("/"),
                    "escaped_prefix": _escape_like(relative_path.strip("/")),
                }
                for root_id, relative_path in dict.fromkeys(scopes)
            ]
            if not requested:
                return {}
            rows = connection.execute(
                "WITH requested AS (SELECT "
                "json_extract(value, '$.root_id') root_id, "
                "json_extract(value, '$.relative_path') relative_path, "
                "json_extract(value, '$.prefix') prefix, "
                "json_extract(value, '$.escaped_prefix') escaped_prefix "
                "FROM json_each(?)) "
                "SELECT requested.root_id, requested.relative_path, "
                "COALESCE(SUM(track.availability = 'indexed'), 0) indexed_count, "
                "COALESCE(SUM(track.availability IN ('indexed','excluded')), 0) on_disk_count "
                "FROM requested LEFT JOIN local_tracks track ON track.root_id = requested.root_id "
                "AND (requested.prefix IN ('', '.') OR track.relative_path = requested.prefix "
                "OR track.relative_path LIKE requested.escaped_prefix || '/%' ESCAPE '\\') "
                "GROUP BY requested.root_id, requested.relative_path",
                (json.dumps(requested, sort_keys=True),),
            ).fetchall()
            return {
                (str(row["root_id"]), str(row["relative_path"])): (
                    int(row["indexed_count"]),
                    int(row["on_disk_count"]),
                )
                for row in rows
            }

        return await self._read(operation)

    async def get_policy_scope_total_counts(
        self, scopes: list[ScanScope]
    ) -> tuple[int, int]:
        def operation(connection: sqlite3.Connection) -> tuple[int, int]:
            normalized = sorted(
                {
                    (
                        scope.root_id,
                        scope.relative_path.strip("/")
                        if scope.relative_path.strip("/") not in {"", "."}
                        else ".",
                    )
                    for scope in scopes
                },
                key=lambda item: (item[0], len(item[1]), item[1]),
            )
            collapsed: list[tuple[str, str]] = []
            for root_id, prefix in normalized:
                if any(
                    parent_root == root_id
                    and (
                        parent_prefix == "."
                        or prefix == parent_prefix
                        or prefix.startswith(f"{parent_prefix}/")
                    )
                    for parent_root, parent_prefix in collapsed
                ):
                    continue
                collapsed.append((root_id, prefix))
            requested = [
                {
                    "root_id": root_id,
                    "prefix": prefix,
                    "escaped_prefix": _escape_like(prefix),
                }
                for root_id, prefix in collapsed
            ]
            if not requested:
                return (0, 0)
            row = connection.execute(
                "WITH requested AS (SELECT "
                "json_extract(value, '$.root_id') root_id, "
                "json_extract(value, '$.prefix') prefix, "
                "json_extract(value, '$.escaped_prefix') escaped_prefix "
                "FROM json_each(?)) "
                "SELECT COALESCE(SUM(track.availability = 'indexed'), 0) indexed_count, "
                "COALESCE(SUM(track.availability IN ('indexed','excluded')), 0) on_disk_count "
                "FROM local_tracks track WHERE EXISTS (SELECT 1 FROM requested "
                "WHERE requested.root_id = track.root_id AND (requested.prefix IN ('', '.') "
                "OR track.relative_path = requested.prefix "
                "OR track.relative_path LIKE requested.escaped_prefix || '/%' ESCAPE '\\'))",
                (json.dumps(requested, sort_keys=True),),
            ).fetchone()
            return (int(row["indexed_count"]), int(row["on_disk_count"]))

        return await self._read(operation)

    @staticmethod
    def _active_album_input(
        connection: sqlite3.Connection, album_id: str
    ) -> tuple[sqlite3.Row, list[sqlite3.Row], str] | None:
        album = connection.execute(
            "SELECT * FROM local_albums WHERE id = ? AND retired_into_album_id IS NULL",
            (album_id,),
        ).fetchone()
        if album is None:
            return None
        tracks = connection.execute(
            "SELECT * FROM local_tracks WHERE local_album_id = ? "
            "AND availability = 'indexed' ORDER BY disc_number, track_number, id",
            (album_id,),
        ).fetchall()
        if not tracks:
            return None
        return album, list(tracks), _album_input_revision(list(tracks))

    @classmethod
    def _contribution_row(
        cls, connection: sqlite3.Connection, contribution_id: str
    ) -> dict[str, Any] | None:
        row = connection.execute(
            "SELECT * FROM library_contribution_drafts WHERE id = ?",
            (contribution_id,),
        ).fetchone()
        if row is None:
            return None
        current = cls._active_album_input(connection, str(row["local_album_id"]))
        if current is None:
            result = dict(row)
            result["album_active"] = False
            result["current_album_row_revision"] = None
            result["current_input_revision"] = None
            return result
        album, _tracks, input_revision = current
        result = dict(row)
        result["album_active"] = True
        result["current_album_row_revision"] = int(album["row_revision"])
        result["current_input_revision"] = input_revision
        return result

    async def create_or_get_library_contribution(
        self,
        *,
        local_album_id: str,
        actor_user_id: str,
        album_row_revision: int,
        input_revision: str,
        local_snapshot_json: str,
        resolved_draft_json: str,
        source_selection_json: str,
        now: float,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            current = self._active_album_input(connection, local_album_id)
            if current is None:
                raise ResourceNotFoundError("Library album not found.")
            album, _tracks, current_input_revision = current
            if (
                int(album["row_revision"]) != album_row_revision
                or current_input_revision != input_revision
            ):
                raise StaleRevisionError(
                    "The album changed before the contribution could be created."
                )
            existing = connection.execute(
                "SELECT id FROM library_contribution_drafts WHERE local_album_id = ? "
                "AND state NOT IN ('linked','cancelled','stale') "
                "ORDER BY created_at DESC LIMIT 1",
                (local_album_id,),
            ).fetchone()
            if existing is not None:
                result = self._contribution_row(connection, str(existing["id"]))
                if result is None:
                    raise ResourceNotFoundError("Library contribution not found.")
                return result
            contribution_id = str(uuid.uuid4())
            try:
                connection.execute(
                    "INSERT INTO library_contribution_drafts "
                    "(id, local_album_id, created_by_user_id, updated_by_user_id, state, "
                    "album_row_revision, input_revision, local_snapshot_json, "
                    "resolved_draft_json, source_selection_json, created_at, updated_at) "
                    "VALUES (?, ?, ?, ?, 'draft', ?, ?, ?, ?, ?, ?, ?)",
                    (
                        contribution_id,
                        local_album_id,
                        actor_user_id,
                        actor_user_id,
                        album_row_revision,
                        input_revision,
                        local_snapshot_json,
                        resolved_draft_json,
                        source_selection_json,
                        now,
                        now,
                    ),
                )
            except sqlite3.IntegrityError:
                existing = connection.execute(
                    "SELECT id FROM library_contribution_drafts WHERE local_album_id = ? "
                    "AND state NOT IN ('linked','cancelled','stale') LIMIT 1",
                    (local_album_id,),
                ).fetchone()
                if existing is None:
                    raise
                contribution_id = str(existing["id"])
            result = self._contribution_row(connection, contribution_id)
            if result is None:
                raise ResourceNotFoundError("Library contribution not found.")
            return result

        return await self._write(operation)

    async def get_library_contribution(
        self, contribution_id: str
    ) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            return self._contribution_row(connection, contribution_id)

        return await self._read(operation)

    async def get_active_album_contribution(
        self, local_album_id: str
    ) -> dict[str, Any] | None:
        def operation(connection: sqlite3.Connection) -> dict[str, Any] | None:
            row = connection.execute(
                "SELECT id FROM library_contribution_drafts WHERE local_album_id = ? "
                "AND state NOT IN ('linked','cancelled','stale') "
                "ORDER BY created_at DESC LIMIT 1",
                (local_album_id,),
            ).fetchone()
            if row is None:
                return None
            contribution = self._contribution_row(connection, str(row["id"]))
            return (
                contribution
                if contribution is not None and contribution["album_active"]
                else None
            )

        return await self._read(operation)

    async def update_library_contribution_draft(
        self,
        *,
        contribution_id: str,
        expected_row_revision: int,
        actor_user_id: str,
        resolved_draft_json: str,
        state: str,
        now: float,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            row = self._contribution_row(connection, contribution_id)
            if row is None or not row["album_active"]:
                raise ResourceNotFoundError("Library contribution not found.")
            if row["state"] not in {"draft", "ready", "needs_review"}:
                raise ConflictError("This contribution can no longer be edited.")
            if int(row["row_revision"]) != expected_row_revision:
                raise StaleRevisionError(
                    "The contribution changed before this edit was saved."
                )
            if row["input_revision"] != row["current_input_revision"] or int(
                row["album_row_revision"]
            ) != int(row["current_album_row_revision"]):
                connection.execute(
                    "UPDATE library_contribution_drafts SET state = 'stale', "
                    "terminal_at = ?, updated_at = ?, row_revision = row_revision + 1 "
                    "WHERE id = ? AND row_revision = ? AND row_revision < ?",
                    (
                        now,
                        now,
                        contribution_id,
                        expected_row_revision,
                        MAX_REVISION,
                    ),
                )
                raise StaleRevisionError(
                    "The local album changed. Rebuild the contribution before editing."
                )
            updated = connection.execute(
                "UPDATE library_contribution_drafts SET resolved_draft_json = ?, state = ?, "
                "updated_by_user_id = ?, duplicate_result_json = NULL, "
                "duplicate_checked_at = NULL, duplicate_input_revision = NULL, "
                "updated_at = ?, row_revision = row_revision + 1 "
                "WHERE id = ? AND row_revision = ? AND row_revision < ? RETURNING *",
                (
                    resolved_draft_json,
                    state,
                    actor_user_id,
                    now,
                    contribution_id,
                    expected_row_revision,
                    MAX_REVISION,
                ),
            ).fetchone()
            if updated is None:
                self._refuse_max_revision(
                    connection,
                    table="library_contribution_drafts",
                    predicate="id = ?",
                    parameters=(contribution_id,),
                )
                raise StaleRevisionError(
                    "The contribution changed before this edit was saved."
                )
            result = self._contribution_row(connection, contribution_id)
            if result is None:
                raise ResourceNotFoundError("Library contribution not found.")
            return result

        return await self._write(operation)

    async def rebuild_library_contribution(
        self,
        *,
        contribution_id: str,
        expected_row_revision: int,
        actor_user_id: str,
        album_row_revision: int,
        input_revision: str,
        local_snapshot_json: str,
        resolved_draft_json: str,
        source_selection_json: str,
        now: float,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            existing = connection.execute(
                "SELECT * FROM library_contribution_drafts WHERE id = ?",
                (contribution_id,),
            ).fetchone()
            if existing is None:
                raise ResourceNotFoundError("Library contribution not found.")
            if int(existing["row_revision"]) != expected_row_revision:
                raise StaleRevisionError(
                    "The contribution changed before it could be rebuilt."
                )
            current = self._active_album_input(
                connection, str(existing["local_album_id"])
            )
            if current is None:
                raise ResourceNotFoundError("Library album not found.")
            album, _tracks, current_input_revision = current
            if (
                int(album["row_revision"]) != album_row_revision
                or current_input_revision != input_revision
            ):
                raise StaleRevisionError(
                    "The album changed before the contribution could be rebuilt."
                )
            connection.execute(
                "UPDATE library_contribution_drafts SET state = 'stale', terminal_at = ?, "
                "updated_at = ?, row_revision = row_revision + 1 "
                "WHERE id = ? AND row_revision = ?",
                (now, now, contribution_id, expected_row_revision),
            )
            connection.execute(
                "UPDATE library_contribution_callback_tokens SET consumed_at = ? "
                "WHERE contribution_id = ? AND consumed_at IS NULL",
                (now, contribution_id),
            )
            connection.execute(
                "UPDATE library_contribution_verification_jobs SET state = 'cancelled', "
                "terminal_at = ?, updated_at = ?, row_revision = row_revision + 1, "
                "event_revision = event_revision + 1 WHERE contribution_id = ? "
                "AND state IN ('queued','running')",
                (now, now, contribution_id),
            )
            new_id = str(uuid.uuid4())
            connection.execute(
                "INSERT INTO library_contribution_drafts "
                "(id, local_album_id, created_by_user_id, updated_by_user_id, state, "
                "album_row_revision, input_revision, local_snapshot_json, "
                "resolved_draft_json, source_selection_json, created_at, updated_at) "
                "VALUES (?, ?, ?, ?, 'draft', ?, ?, ?, ?, ?, ?, ?)",
                (
                    new_id,
                    existing["local_album_id"],
                    actor_user_id,
                    actor_user_id,
                    album_row_revision,
                    input_revision,
                    local_snapshot_json,
                    resolved_draft_json,
                    source_selection_json,
                    now,
                    now,
                ),
            )
            result = self._contribution_row(connection, new_id)
            if result is None:
                raise ResourceNotFoundError("Library contribution not found.")
            return result

        return await self._write(operation)

    async def cancel_library_contribution(
        self,
        *,
        contribution_id: str,
        expected_row_revision: int,
        actor_user_id: str,
        now: float,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            row = self._contribution_row(connection, contribution_id)
            if row is None or not row["album_active"]:
                raise ResourceNotFoundError("Library contribution not found.")
            if row["state"] in {"linked", "cancelled", "stale"}:
                raise ConflictError("This contribution is already closed.")
            updated = connection.execute(
                "UPDATE library_contribution_drafts SET state = 'cancelled', "
                "updated_by_user_id = ?, terminal_at = ?, updated_at = ?, "
                "seed_snapshot_json = NULL, row_revision = row_revision + 1 "
                "WHERE id = ? AND row_revision = ? AND row_revision < ? RETURNING id",
                (
                    actor_user_id,
                    now,
                    now,
                    contribution_id,
                    expected_row_revision,
                    MAX_REVISION,
                ),
            ).fetchone()
            if updated is None:
                self._refuse_max_revision(
                    connection,
                    table="library_contribution_drafts",
                    predicate="id = ?",
                    parameters=(contribution_id,),
                )
                raise StaleRevisionError(
                    "The contribution changed before it could be cancelled."
                )
            connection.execute(
                "UPDATE library_contribution_callback_tokens SET consumed_at = ? "
                "WHERE contribution_id = ? AND consumed_at IS NULL",
                (now, contribution_id),
            )
            connection.execute(
                "UPDATE library_contribution_verification_jobs SET state = 'cancelled', "
                "terminal_at = ?, updated_at = ?, row_revision = row_revision + 1, "
                "event_revision = event_revision + 1 WHERE contribution_id = ? "
                "AND state IN ('queued','running')",
                (now, now, contribution_id),
            )
            result = dict(
                connection.execute(
                    "SELECT * FROM library_contribution_drafts WHERE id = ?",
                    (contribution_id,),
                ).fetchone()
            )
            result["current_album_row_revision"] = row["current_album_row_revision"]
            result["current_input_revision"] = row["current_input_revision"]
            result["album_active"] = row["album_active"]
            return result

        return await self._write(operation)

    async def mark_library_contribution_stale(
        self, *, contribution_id: str, expected_row_revision: int, now: float
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            row = connection.execute(
                "SELECT * FROM library_contribution_drafts WHERE id = ?",
                (contribution_id,),
            ).fetchone()
            if row is None:
                raise ResourceNotFoundError("Library contribution not found.")
            if str(row["state"]) not in {
                "linked",
                "cancelled",
                "stale",
            }:
                updated = connection.execute(
                    "UPDATE library_contribution_drafts SET state = 'stale', "
                    "terminal_at = ?, updated_at = ?, seed_snapshot_json = NULL, "
                    "row_revision = row_revision + 1 WHERE id = ? AND row_revision = ? "
                    "AND row_revision < ?",
                    (
                        now,
                        now,
                        contribution_id,
                        expected_row_revision,
                        MAX_REVISION,
                    ),
                )
                if updated.rowcount != 1:
                    if int(row["row_revision"]) >= MAX_REVISION:
                        raise RevisionOverflowError(
                            "The contribution revision cannot be increased."
                        )
                    raise StaleRevisionError(
                        "The contribution changed before it could be marked stale."
                    )
                connection.execute(
                    "UPDATE library_contribution_verification_jobs SET state = 'cancelled', "
                    "terminal_at = ?, updated_at = ?, row_revision = row_revision + 1, "
                    "event_revision = event_revision + 1 WHERE contribution_id = ? "
                    "AND state IN ('queued','running')",
                    (now, now, contribution_id),
                )
            result = dict(
                connection.execute(
                    "SELECT * FROM library_contribution_drafts WHERE id = ?",
                    (contribution_id,),
                ).fetchone()
            )
            current = self._active_album_input(
                connection, str(result["local_album_id"])
            )
            result["album_active"] = current is not None
            result["current_album_row_revision"] = (
                int(current[0]["row_revision"]) if current is not None else None
            )
            result["current_input_revision"] = (
                current[2] if current is not None else None
            )
            return result

        return await self._write(operation)

    async def upsert_local_entity_source_link(
        self,
        *,
        local_artist_id: str | None,
        local_album_id: str | None,
        local_track_id: str | None,
        provider: str,
        external_entity_type: str,
        external_id: str,
        canonical_url: str,
        decision_source: str,
        selected_by_user_id: str | None,
        verified_at: float,
        now: float,
    ) -> dict[str, Any]:
        subjects = [local_artist_id, local_album_id, local_track_id]
        if sum(subject is not None for subject in subjects) != 1:
            raise ValidationError("A source link requires exactly one local subject.")

        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            columns = (
                ("local_artist_id", local_artist_id)
                if local_artist_id is not None
                else (
                    ("local_album_id", local_album_id)
                    if local_album_id is not None
                    else ("local_track_id", local_track_id)
                )
            )
            subject_column, subject_id = columns
            existing = connection.execute(
                f"SELECT * FROM local_entity_source_links WHERE {subject_column} = ? "
                "AND provider = ? AND external_entity_type = ? AND external_id = ?",
                (subject_id, provider, external_entity_type, external_id),
            ).fetchone()
            if existing is not None:
                updated = connection.execute(
                    "UPDATE local_entity_source_links SET canonical_url = ?, "
                    "decision_source = ?, selected_by_user_id = ?, verified_at = ?, "
                    "updated_at = ?, row_revision = row_revision + 1 WHERE id = ? "
                    "AND row_revision < ? RETURNING *",
                    (
                        canonical_url,
                        decision_source,
                        selected_by_user_id,
                        verified_at,
                        now,
                        existing["id"],
                        MAX_REVISION,
                    ),
                ).fetchone()
                if updated is None:
                    raise RevisionOverflowError(
                        "The source-link revision cannot be increased."
                    )
                return dict(updated)
            link_id = str(uuid.uuid4())
            connection.execute(
                "INSERT INTO local_entity_source_links "
                "(id, local_artist_id, local_album_id, local_track_id, provider, "
                "external_entity_type, external_id, canonical_url, decision_source, "
                "selected_by_user_id, verified_at, created_at, updated_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    link_id,
                    local_artist_id,
                    local_album_id,
                    local_track_id,
                    provider,
                    external_entity_type,
                    external_id,
                    canonical_url,
                    decision_source,
                    selected_by_user_id,
                    verified_at,
                    now,
                    now,
                ),
            )
            return dict(
                connection.execute(
                    "SELECT * FROM local_entity_source_links WHERE id = ?", (link_id,)
                ).fetchone()
            )

        return await self._write(operation)

    async def remove_local_album_source_link(
        self,
        *,
        local_album_id: str,
        provider: str,
        external_entity_type: str,
        external_id: str,
    ) -> bool:
        def operation(connection: sqlite3.Connection) -> bool:
            result = connection.execute(
                "DELETE FROM local_entity_source_links WHERE local_album_id = ? "
                "AND provider = ? AND external_entity_type = ? AND external_id = ?",
                (local_album_id, provider, external_entity_type, external_id),
            )
            return result.rowcount > 0

        return await self._write(operation)

    async def select_discogs_source_for_contribution(
        self,
        *,
        contribution_id: str,
        expected_row_revision: int,
        actor_user_id: str,
        release_id: str,
        canonical_url: str,
        source_selection_json: str,
        provider_snapshot_expires_at: float,
        verified_at: float,
        now: float,
    ) -> dict[str, Any]:
        def operation(connection: sqlite3.Connection) -> dict[str, Any]:
            row = self._contribution_row(connection, contribution_id)
            if row is None or not row["album_active"]:
                raise ResourceNotFoundError("Library contribution not found.")
            if row["state"] not in {"draft", "ready", "needs_review"}:
                raise ConflictError("This contribution can no longer be edited.")
            if int(row["row_revision"]) != expected_row_revision:
                raise StaleRevisionError(
                    "The contribution changed before the source was selected."
                )
            if row["input_revision"] != row["current_input_revision"]:
                raise StaleRevisionError(
                    "The local album changed. Rebuild the contribution first."
                )
            album_id = str(row["local_album_id"])
            connection.execute(
                "DELETE FROM local_entity_source_links WHERE local_album_id = ? "
                "AND provider = 'discogs' AND external_entity_type = 'release' "
                "AND external_id <> ?",
                (album_id, release_id),
            )
            existing = connection.execute(
                "SELECT id, row_revision FROM local_entity_source_links "
                "WHERE local_album_id = ? AND provider = 'discogs' "
                "AND external_entity_type = 'release' AND external_id = ?",
                (album_id, release_id),
            ).fetchone()
            if existing is None:
                connection.execute(
                    "INSERT INTO local_entity_source_links "
                    "(id, local_album_id, provider, external_entity_type, external_id, "
                    "canonical_url, decision_source, selected_by_user_id, verified_at, "
                    "created_at, updated_at) VALUES (?, ?, 'discogs', 'release', ?, ?, "
                    "'curator_selected', ?, ?, ?, ?)",
                    (
                        str(uuid.uuid4()),
                        album_id,
                        release_id,
                        canonical_url,
                        actor_user_id,
                        verified_at,
                        now,
                        now,
                    ),
                )
            else:
                if int(existing["row_revision"]) >= MAX_REVISION:
                    raise RevisionOverflowError(
                        "The source-link revision cannot be increased."
                    )
                connection.execute(
                    "UPDATE local_entity_source_links SET canonical_url = ?, "
                    "selected_by_user_id = ?, verified_at = ?, updated_at = ?, "
                    "row_revision = row_revision + 1 WHERE id = ?",
                    (
                        canonical_url,
                        actor_user_id,
                        verified_at,
                        now,
                        existing["id"],
                    ),
                )
            updated = connection.execute(
                "UPDATE library_contribution_drafts SET source_selection_json = ?, "
                "provider_snapshot_expires_at = ?, updated_by_user_id = ?, "
                "duplicate_result_json = NULL, duplicate_checked_at = NULL, "
                "duplicate_input_revision = NULL, updated_at = ?, "
                "row_revision = row_revision + 1 WHERE id = ? AND row_revision = ? "
                "AND row_revision < ? RETURNING id",
                (
                    source_selection_json,
                    provider_snapshot_expires_at,
                    actor_user_id,
                    now,
                    contribution_id,
                    expected_row_revision,
                    MAX_REVISION,
                ),
            ).fetchone()
            if updated is None:
                self._refuse_max_revision(
                    connection,
                    table="library_contribution_drafts",
                    predicate="id = ?",
                    parameters=(contribution_id,),
                )
                raise StaleRevisionError(
                    "The contribution changed before the source was selected."
                )
            result = self._contribution_row(connection, contribution_id)
            if result is None:
                raise ResourceNotFoundError("Library contribution not found.")
            return result

        return await self._write(operation)

